const SQL_SPECIFIC_MUSCLES = `INSERT INTO specific_muscles (id, name, broad_category) VALUES (1,'Mięsień piersiowy większy','Klatka piersiowa'),(2,'Mięsień piersiowy mniejszy','Klatka piersiowa'),(3,'Mięsień najszerszy grzbietu','Plecy'),(4,'Mięsień czworoboczny grzbietu','Plecy'),(5,'Mięśnie równoległoboczne','Plecy'),(6,'Mięsień obły większy','Plecy'),(7,'Prostowniki grzbietu','Plecy'),(8,'Mięsień naramienny (głowa przednia)','Barki'),(9,'Mięsień naramienny (głowa boczna)','Barki'),(10,'Mięsień naramienny (głowa tylna)','Barki'),(11,'Mięśnie stożka rotatorów','Barki'),(12,'Mięsień dwugłowy ramienia','Biceps'),(13,'Mięsień ramienny','Biceps'),(14,'Mięsień trójgłowy ramienia','Triceps'),(15,'Zginacze nadgarstka i palców','Przedramiona'),(16,'Prostowniki nadgarstka i palców','Przedramiona'),(17,'Mięsień prosty brzucha','Brzuch'),(18,'Mięśnie skośne brzucha','Brzuch'),(19,'Mięsień poprzeczny brzucha','Brzuch'),(20,'Mięsień pośladkowy wielki','Pośladki'),(21,'Mięsień pośladkowy średni','Pośladki'),(22,'Mięsień pośladkowy mały','Pośladki'),(23,'Mięsień czworogłowy uda','Mięśnie czworogłowe uda'),(24,'Mięśnie kulszowo-goleniowe','Mięśnie dwugłowe uda'),(25,'Mięśnie przywodziciele uda','Przywodziciele'),(26,'Mięśnie odwodziciele uda','Odwodziciele'),(27,'Mięsień brzuchaty łydki','Łydki'),(28,'Mięsień płaszczkowaty','Łydki') ON CONFLICT (name) DO UPDATE SET broad_category=EXCLUDED.broad_category`;

const SQL_SM_SETVAL = `SELECT setval('specific_muscles_id_seq',(SELECT MAX(id) FROM specific_muscles))`;

const SQL_EXERCISES_0 = `INSERT INTO exercises (id,name,slug,main_muscle_group,secondary_muscle_groups,equipment,equipment_other,training_location,difficulty_level,movement_pattern,description,execution_instructions,common_mistakes,coaching_tips,breathing_tips,safety_notes,exercise_type,suitable_experience_levels,training_goals,movement_category,plane_of_motion,execution,resistance_type,requires_spotter,can_be_performed_to_failure,joint_stress,learning_difficulty,neurological_fatigue,doms_potential,exercise_priority,is_active,suitable_for_no_activity,movement_complexity,sub_target_biases) VALUES (1,'Wyciskanie sztangi leżąc','wyciskanie-sztangi-lezac','Klatka piersiowa',ARRAY['Barki','Triceps'],ARRAY['Sztanga','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie poziome','Podstawowe ćwiczenie wielostawowe na klatkę piersiową wykonywane w leżeniu na ławce.','Połóż się na ławce, chwyć sztangę nachwytem szerzej niż barki, zsuń ją z podpórek, opuść do klatki piersiowej i wypchnij do góry.','Odbijanie sztangi od klatki piersiowej, zbyt szeroki chwyt, odklejanie miednicy od ławki.','Ściągnij łopatki, zachowaj naturalne wygięcie odcinka lędźwiowego, kontroluj tempo opuszczania.',NULL,NULL,'Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Push','Poprzeczna','Obustronne','Sztanga',true,'Z ostrożnością','Średnie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"mid_chest": 0.6, "lower_chest": 0.2, "upper_chest": 0.2}'::jsonb),(2,'Podciąganie na drążku','podciaganie-na-drazku','Plecy',ARRAY['Biceps','Przedramiona'],ARRAY['Drążek'],NULL,ARRAY['Siłownia','Plener','Dom'],'Zaawansowany','Przyciąganie pionowe','Ćwiczenie z masą własnego ciała rozwijające siłę i szerokość pleców.','Chwyć drążek nachwytem, zwiśnij swobodnie, podciągnij się aż broda znajdzie się nad drążkiem, następnie kontrolowanie opuść się do pełnego wyprostu.','Kołysanie ciałem, niepełny zakres ruchu, brak kontroli w fazie opuszczania.','Zacznij od wersji z gumą asekuracyjną, jeśli klient nie wykonuje jeszcze pełnego powtórzenia.',NULL,NULL,'Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa','Wytrzymałość siłowa'],'Pull','Strzałkowa','Obustronne','Ciężar własnego ciała',false,'Z ostrożnością','Średnie',4,3,3,'Wysoki',true,NULL,'Złożona','{"lats": 0.7, "upper_back": 0.3}'::jsonb),(3,'Przysiad ze sztangą','przysiad-ze-sztanga','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przysiad','Podstawowe ćwiczenie wielostawowe na dolne partie ciała.','Umieść sztangę na górnej części pleców, wykonaj przysiad schodząc do momentu, gdy uda są równoległe do podłoża lub niżej, następnie wróć do pozycji stojącej.','Zapadanie kolan do środka, unoszenie pięt, nadmierne pochylenie tułowia.','Utrzymuj napięty brzuch, prowadź ruch od bioder, kontroluj pozycję kolan względem palców stóp.',NULL,NULL,'Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Squat','Strzałkowa','Obustronne','Sztanga',true,'Z ostrożnością','Wysokie',4,4,4,'Wysoki',true,NULL,'Złożona','{"dwugłowe": 0.15, "pośladki": 0.3, "czworogłowe": 0.55}'::jsonb),(4,'Wyciskanie hantli nad głowę','wyciskanie-hantli-nad-g-owe','Barki',ARRAY['Triceps'],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Pchanie pionowe','Ćwiczenie izolowane rozwijające siłę i masę barków.','Siedząc lub stojąc, unieś hantle na wysokość barków, wypchnij je nad głowę do pełnego wyprostu ramion, następnie kontrolowanie opuść.','Nadmierne odginanie tułowia do tyłu, zbyt szybkie tempo wykonywania.','Zacznij od mniejszego obciążenia, aby wypracować pełny zakres ruchu.',NULL,NULL,'Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Push','Czołowa','Obustronne','Hantle',false,'Z ostrożnością','Średnie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"rear_delt": 0.1, "front_delt": 0.55, "lateral_delt": 0.35}'::jsonb),(5,'Plank','plank','Brzuch',ARRAY['Całe ciało'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Anti-ekstensja','Ćwiczenie izometryczne wzmacniające mięśnie głębokie tułowia.','Ułóż się w podporze na przedramionach, utrzymuj ciało w linii od głowy do stóp, napnij brzuch i pośladki.','Opadanie bioder, unoszenie pośladków, wstrzymywanie oddechu.','Zacznij od krótszych czasów utrzymania (20-30s) i stopniowo wydłużaj.',NULL,NULL,'Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Stabilizacja','Wytrzymałość siłowa'],'Core','Strzałkowa','Obustronne','Ciężar własnego ciała',false,'Z ostrożnością','Niskie',1,1,1,'Wysoki',true,true,'Prosta','{"brzuch": 1}'::jsonb),(88,'Przysiad goblet z hantlem','przysiad-goblet-z-hantlem','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda','Przywodziciele'],ARRAY['Hantle','Kettlebell'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Przysiad','Przysiad goblet to ćwiczenie złożone angażujące czworogłowe uda, pośladki i core, podczas którego hantel lub kettlebell trzymany jest przy klatce piersiowej jako przeciwwaga.','Stań w rozkroku na szerokość barków lub nieco szerzej, trzymając hantel oburącz przy mostek. Wykonaj głęboki przysiad, utrzymując klatkę piersiową uniesioną i kolana podążające za palcami stóp. Wypychaj pięty w podłogę, wracając do pozycji wyjściowej.','Zaokrąglanie pleców w odcinku lędźwiowym oraz opadanie kolan do środka. Zbyt mała głębokość przysiadu ogranicza aktywację pośladków.','Użyj hantla jako przeciwwagi, aby siedzieć głębiej i utrzymać wyprostowaną klatkę. Łokcie powinny dotykać kolan wewnątrz w najniższym punkcie.','Wdech przed zejściem w dół, wydech podczas wypychania się do góry.','Nie forsuj zakresu ruchu, jeśli odczuwasz ból kolan lub bioder. Zacznij od lekkiego ciężaru.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Przysiad','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Średnie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.4, "czworogłowe": 0.6}'::jsonb),(89,'Przysiad do skrzyni','przysiad-do-skrzyni','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Sztanga','Hantle','Kettlebell','Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Przysiad','Przysiad do skrzyni ogranicza głębokość ruchu do określonej wysokości pudła, ułatwiając naukę techniki i bezpieczne obciążenie stawów kolanowych.','Ustaw skrzynię lub ławkę za sobą na odpowiedniej wysokości. Stań w rozkroku, zaczerpnij wdech i powoli opuść biodra, aż siedzisz lekko na skrzyni. Zachowaj napięcie całego ciała i wypychaj przez pięty do pozycji stojącej.','Siadanie z hukiem i utrata napięcia mięśniowego na skrzyni. Zbyt wąski rozkrok ogranicza głębokość przysiadu.','Dotykaj skrzyni lekko i kontrolowanie — to oznacza aktywne, a nie pasywne siedzenie. Wychyl tułów lekko do przodu, aby zachować środek ciężkości.','Głęboki wdech przed zejściem, wydech podczas wstawania.','Dobierz wysokość skrzyni do swoich możliwości ruchowych bioder i kolan.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Przysiad','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Średnie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.4, "czworogłowe": 0.6}'::jsonb),(90,'Przysiad do skrzyni z masą własnego ciała','przysiad-do-skrzyni-z-masa-w-asnego-cia-a','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Przysiad','Najprostsza forma przysiadu do skrzyni bez dodatkowego obciążenia — idealna dla osób rozpoczynających aktywność fizyczną lub powracających po przerwie.','Stań przed skrzynią lub krzesłem z rękami wyciągniętymi przed siebie dla równowagi. Powoli opuść się kontrolowanym ruchem, aż uda dotkną powierzchni skrzyni. Zatrzymaj się na chwilę i wstań, wypychając przez pięty.','Opadanie bezwładnie na skrzynię bez kontroli ekscentrycznej. Zbyt gwałtowne wstawanie z użyciem zamchu.','Im wolniej się opuszczasz, tym więcej pracują mięśnie. Skup się na kontrolowanym ruchu, nie na szybkości.','Wdech podczas opadania, wydech podczas wstawania.','Upewnij się, że skrzynia lub krzesło są stabilne i nie ześlizgną się. Zacznij od wyższej powierzchni i stopniowo obniżaj.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Masa mięśniowa'],'Przysiad','Strzałkowa','Obustronne','Masa własnego ciała',false,'Tak','Niskie',1,1,1,'Wysoki',true,true,'Prosta','{"pośladki": 0.4, "czworogłowe": 0.6}'::jsonb),(91,'Hack squat na maszynie','hack-squat-na-maszynie','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przysiad','Hack squat na maszynie to ćwiczenie złożone z prowadnicą skośną, które mocno akcentuje czworogłowe uda przy zmniejszonym obciążeniu kręgosłupa w porównaniu ze sztangą.','Ustaw stopy na platformie na szerokość barków lub nieco szerzej. Odblokuj maszynę i powoli opuszczaj biodra, aż uda będą równoległe do podłogi lub niżej. Wypychaj przez całą stopę, wracając do pozycji wyjściowej bez blokowania kolan.','Odrywanie pięt od platformy oraz blokowanie kolan na szczycie ruchu. Zbyt wąskie ustawienie stóp powoduje nadmierne napięcie stawu rzepkowo-udowego.','Im niżej postawisz stopy na platformie, tym większe zaangażowanie czworogłowych. Wyższe ustawienie stóp angażuje więcej pośladków i kulszowo-goleniowych.','Wdech przed zejściem, wydech podczas wypychania na górę.','Nie blokuj kolan na szczycie i nie forsuj zakresu ruchu z bólem w kolanie.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Przysiad','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Wysokie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.25, "czworogłowe": 0.75}'::jsonb),(92,'Wypychanie nóg na suwnicy 45°','wypychanie-nog-na-suwnicy-45','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda','Przywodziciele'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Przysiad','Wypychanie nóg na suwnicy to ćwiczenie złożone na maszynie 45°, angażujące czworogłowe uda, pośladki i kulszowo-goleniowe przy stabilnym prowadzeniu ruchu.','Usiądź w suwnicy i ustaw stopy na platformie na szerokość barków. Odblokuj bezpieczniki i powoli ugnij kolana do kąta ok. 90°, utrzymując plecy płasko przy oparciu. Wypychaj platformę przez pięty i śródstopie do niemal pełnego wyprostu kolan.','Odrywanie pośladków od siedzenia podczas opuszczania. Zbyt małe ugięcie kolan ogranicza zakres pracy mięśni.','Wysokie ustawienie stóp na platformie angażuje więcej pośladków; niskie ustawienie akcentuje czworogłowe. Nie blokuj kolan całkowicie na górze.','Wdech podczas opuszczania, wydech podczas wypychania.','Nigdy nie blokuj kolan na szczycie — grozi to urazem stawu kolanowego. Używaj bezpieczników maszyny.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Przysiad','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Średnie',2,2,3,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.35, "czworogłowe": 0.65}'::jsonb),(93,'Przysiad na suwnicy Smitha','przysiad-na-suwnicy-smitha','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przysiad','Przysiad na suwnicy Smitha wykonywany jest na prowadnicy, która stabilizuje ruch pionowy sztangi, pozwalając skupić się na technice dolnych partii ciała.','Ustaw sztangę na wysokości ramion i wyjdź pod nią, umieszczając ją na mięśniach czworobocznych lub tylnych naramiennych. Ustaw stopy lekko przed tułowiem. Powoli zejdź do równoległości lub niżej, a następnie wypychaj do góry przez pięty.','Ustawienie stóp zbyt daleko z przodu powoduje nadmierne odchylanie tułowia. Blokowanie kolan na górze jest częstym błędem.','Wysunięcie stóp przed oś bioder daje głębszy przysiad i zmniejsza obciążenie kolan. Przetestuj kilka ustawień stóp, aby znaleźć optymalne.','Wdech przed zejściem, wydech podczas wychodzenia z przysiadu.','Suwnica Smitha ogranicza naturalny ruch — słuchaj swojego ciała i nie forsuj zakresu ruchu.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Przysiad','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Średnie',2,3,3,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.4, "czworogłowe": 0.6}'::jsonb),(94,'Przysiad bułgarski','przysiad-bu-garski','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Hantle','Sztanga','Masa własnego ciała','Ławka'],NULL,ARRAY['Siłownia','Dom'],'Zaawansowany','Wykrok','Przysiad bułgarski to jednostronne ćwiczenie złożone, w którym tylna noga opiera się na ławce, co wymaga dużej mobilności bioder i siły jednej nogi.','Stań przodem do ławki i odsuń się o długość uda. Oprzyj grzbiet tylnej stopy na ławce. Opuść biodra prosto w dół, zginając kolano nogi z przodu do kąta 90°. Kolano przedniej nogi podąża za palcami stopy. Wypychaj przez piętę do pozycji stojącej.','Zbyt duże pochylenie tułowia do przodu oraz opadanie kolana przedniej nogi do środka. Zbyt bliskie ustawienie do ławki powoduje nadmierne zginanie kolana.','Trzymaj tułów możliwie pionowo, aby skupić pracę na czworogłowych. Cofnięcie tułowia i ugięcie przedniej nogi angażuje bardziej pośladki.','Wdech podczas opadania, wydech podczas wychodzenia z przysiadu.','Zacznij bez obciążenia, aby opanować technikę. Ból w przednim kolanie może wskazywać na zbyt duże nachylenie do przodu.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Wykrok','Strzałkowa','Jednostronne','Hantle',false,'Z ostrożnością','Wysokie',4,4,4,'Wysoki',true,NULL,'Złożona','{"pośladki": 0.45, "czworogłowe": 0.55}'::jsonb),(95,'Przysiad wykroczny z podparciem','przysiad-wykroczny-z-podparciem','Mięśnie czworogłowe uda',ARRAY['Pośladki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Wykrok','Przysiad wykroczny z podparciem to jednostronne ćwiczenie, w którym trzymanie się ściany lub drążka pozwala bezpiecznie opanować wzorzec wykroku przy ograniczonej mobilności lub sile.','Stań przy ścianie lub drążku z boku i chwyć go jedną ręką dla podparcia. Wysuń jedną nogę do przodu i opuść biodra prosto w dół, zginając obie nogi do kąta 90°. Kolano tylnej nogi nie dotyka podłogi zbyt gwałtownie. Wypychaj przez piętę przedniej nogi do góry.','Nadmierne pochylanie tułowia do przodu i brak kontroli kolana tylnej nogi przy podłodze.','Podparcie ułatwia utrzymanie pionowego tułowia — z czasem ograniczaj wsparcie dłoni.','Wdech podczas opadania, wydech podczas wstawania.','Odpowiednie ćwiczenie dla osób z ograniczoną równowagą lub po przerwie w aktywności.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany'],ARRAY['Zdrowie ogólne','Masa mięśniowa'],'Wykrok','Strzałkowa','Jednostronne','Masa własnego ciała',false,'Tak','Niskie',2,2,2,'Wysoki',true,true,'Prosta','{"pośladki": 0.4, "czworogłowe": 0.6}'::jsonb),(96,'Wykrok w tył','wykrok-w-ty','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Hantle','Sztanga','Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Wykrok','Wykrok w tył jest bezpieczniejszą alternatywą dla wykroku w przód — zmniejsza ścinające siły na kolanie i ułatwia naukę wzorca wykroku.','Stań prosto z hantlami w dłoniach lub z masą własnego ciała. Zrób krok do tyłu jedną nogą, opuszczając kolano tejże nogi blisko podłogi. Przód kolana przedniej nogi pozostaje nad stopą. Wróć do pozycji wyjściowej, odpychając się piętą nogi z przodu.','Wykonywanie zbyt małego kroku, przez co kolano przedniej nogi wychodzi poza linię stopy. Opadanie kolan do środka.','Utrzymuj tułów pionowo przez cały ruch. Krok w tył powinien być wystarczająco duży, by tylne kolano mogło opaść nisko.','Wdech podczas kroku w tył i opuszczania, wydech podczas powrotu.','Zacznij bez obciążenia, skupiając się na równowadze i technice przed dodaniem ciężarów.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Wykrok','Strzałkowa','Jednostronne','Hantle',false,'Z ostrożnością','Średnie',2,2,3,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.45, "czworogłowe": 0.55}'::jsonb),(97,'Wykroki chodzone','wykroki-chodzone','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Hantle','Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Wykrok','Wykroki chodzone to dynamiczna wersja wykroku, w której każdy krok do przodu tworzy ciągłe obciążenie dla całej nogi, angażując równocześnie stabilizatory bioder.','Stań prosto z hantlami wzdłuż tułowia. Zrób duży krok do przodu jedną nogą, opuść kolano tylnej nogi blisko podłogi. Bez zatrzymywania się, podnieś się i wykonaj krok następną nogą. Kontynuuj naprzemiennie.','Zbyt małe kroki uniemożliwiają pełny zakres ruchu. Zachwianie równowagi wynika zwykle z nieodpowiedniej siły stabilizatorów.','Utrzymuj klatkę piersiową uniesioną i wzrok skierowany przed siebie. Każdy krok powinien być duży i pewny.','Wydech podczas wypychania się z każdego kroku.','Wymaga odpowiedniej przestrzeni. Zacznij od mniejszych ciężarów z powodu większego wymagania koordynacji.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Wykrok','Strzałkowa','Jednostronne','Hantle',false,'Z ostrożnością','Średnie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.45, "czworogłowe": 0.55}'::jsonb),(98,'Wejście na podest','wejscie-na-podest','Mięśnie czworogłowe uda',ARRAY['Pośladki'],ARRAY['Masa własnego ciała','Hantle'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Wykrok','Wejście na podest to funkcjonalne ćwiczenie jednostronne naśladujące wchodzenie po schodach, skutecznie angażujące czworogłowe uda i pośladki.','Stań przed stabilnym podium lub schodkiem. Postaw jedną nogę płasko na powierzchni podestu. Wypychaj przez piętę nogi z podestu, unosząc drugie kolano do góry. Kontrolowanie zejdź i naprzemiennie zmieniaj nogi.','Odpychanie się od podłogi tylną nogą zamiast pracować przednią. Zbyt niska skrzynia nie daje wystarczającego bodźca.','Całkowicie przenieś ciężar ciała na przednią nogę przed wejściem. Wysokość podestu wpływa na intensywność — zacznij od niższego.','Wydech podczas wchodzenia na podest, wdech podczas schodzenia.','Upewnij się, że podest jest stabilny i nie ześlizgnie się. Dla większego wyzwania trzymaj hantle wzdłuż tułowia.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Masa mięśniowa'],'Wykrok','Strzałkowa','Jednostronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',2,2,2,'Średni',true,NULL,'Umiarkowana',NULL),(99,'Prostowanie nóg na maszynie','prostowanie-nog-na-maszynie','Mięśnie czworogłowe uda',ARRAY[]::text[],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Wyprost kolana','Prostowanie nóg na maszynie to izolowane ćwiczenie skupiające się wyłącznie na mięśniu czworogłowym uda, wykonywane w siadzie z kontrolowanym ruchem prostowania kolana.','Usiądź w maszynie i ustaw wałek na poziomie kostek. Wyprostuj nogi do pełnego wyprostu, napinając czworogłowe na szczycie. Powoli opuść ciężar, kontrolując fazę ekscentryczną przez pełny zakres ruchu.','Szarpanie i używanie zamachu zamiast kontrolowanego ruchu. Przesuwanie się na siodełku podczas wyprostu.','Napinaj czworogłowe świadomie na górze ruchu i trzymaj napięcie przez chwilę. Powolna faza ekscentryczna maksymalizuje efekt.','Wydech podczas wyprostu, wdech podczas opuszczania ciężaru.','Osoby z bólem rzepki powinny ograniczyć kąt zginania kolana lub unikać tego ćwiczenia.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Średnie',1,1,2,'Średni',true,NULL,'Prosta',NULL),(100,'Martwy ciąg rumuński ze sztangą','martwy-ciag-rumunski-ze-sztanga','Mięśnie dwugłowe uda',ARRAY['Pośladki','Plecy'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Zawias biodrowy','Martwy ciąg rumuński ze sztangą to ćwiczenie zawiasowe skupiające się na kulszowo-goleniowych i pośladkach przez pełne rozciągnięcie przy zgiętych kolanach.','Stań z nogami na szerokość bioder, trzymając sztangę nachwytem przed udami. Zachowując plecy proste i kolana lekko ugięte, powoli opuszczaj sztangę wzdłuż nóg, wysuwając biodra do tyłu. Zatrzymaj się gdy poczujesz rozciąganie w kulszowo-goleniowych, a następnie wróć do pozycji stojącej, wypychając biodra do przodu.','Zaokrąglanie dolnego odcinka kręgosłupa i zginanie kolan zbyt mocno, co zamienia ćwiczenie w zwykły martwy ciąg.','Ruch pochodzi z bioder, nie z pleców. Wyobraź sobie, że odpychasz biodra do ściany za sobą.','Wdech przed opuszczaniem, wydech podczas powrotu do pionu.','Nigdy nie zaokrąglaj lędźwi pod ciężarem. Zatrzymaj ruch gdy kręgosłup zaczyna się wyginać.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Zawiasowe','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Średnie',3,3,4,'Wysoki',true,NULL,'Umiarkowana','{"dwugłowe": 0.55, "pośladki": 0.45}'::jsonb),(101,'Martwy ciąg rumuński z hantlami','martwy-ciag-rumunski-z-hantlami','Mięśnie dwugłowe uda',ARRAY['Pośladki','Plecy'],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Zawias biodrowy','Martwy ciąg rumuński z hantlami to łagodniejsza wersja RDL, która umożliwia bardziej naturalny ruch ramion i jest łatwiej dostępna dla osób z ograniczoną mobilnością.','Stań z hantlami przed udami, stopami na szerokość bioder. Z lekko ugiętymi kolanami, wysuń biodra do tyłu i opuszczaj hantle blisko nóg, aż poczujesz rozciąganie kulszowo-goleniowych. Wróć do pionu, napinając pośladki na górze.','Odsuwanie hantli od nóg, przez co wzmaga się napięcie w dolnych plecach. Zbyt głęboke opuszczanie z zaokrąglonymi plecami.','Hantle powinny ''jechać'' po nogach w dół. Wyobraź sobie zamknięcie szuflady biodrami na szczycie ruchu.','Wdech przed opuszczaniem, wydech na górze ruchu.','Bezpieczna odmiana RDL dla początkujących — zacznij od lekkiego ciężaru i skup się na technice.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Zawiasowe','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',2,2,3,'Wysoki',true,NULL,'Umiarkowana','{"dwugłowe": 0.55, "pośladki": 0.45}'::jsonb),(102,'Martwy ciąg z trap barem','martwy-ciag-z-trap-barem','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda','Plecy'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Zawias biodrowy','Martwy ciąg z trap barem łączy cechy przysiadu i martwego ciągu — neutralny chwyt i środek ciężkości wewnątrz baru zmniejsza wymagania techniczne i obciążenie kręgosłupa.','Wejdź do środka trap bara, stopy na szerokość bioder. Chwyć uchwyty, ustaw plecy neutralnie i odepchnij podłogę, unosząc ciężar. Biodra i barki unoszą się razem. Wróć do podłogi kontrolowanie.','Zbyt wysoko unoszące się biodra na początku ruchu (zamieniając ćwiczenie w RDL) lub zbyt nisko (zamieniając w przysiad). Zaokrąglanie górnego odcinka pleców.','Użyj wyższych uchwytów baru, jeśli masz ograniczoną mobilność. Trap bar jest świetnym ćwiczeniem do nauki wzorca martwego ciągu dla początkujących.','Wdech i napięcie całego ciała przed podniesieniem, wydech po zakończeniu powtórzenia.','Zachowaj neutralny kręgosłup przez cały zakres ruchu. Nie zaokrąglaj lędźwi pod ciężarem.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Zawiasowe','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Średnie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"dwugłowe": 0.2, "pośladki": 0.3, "czworogłowe": 0.5}'::jsonb),(103,'Martwy ciąg z kettlebell','martwy-ciag-z-kettlebell','Mięśnie dwugłowe uda',ARRAY['Pośladki','Plecy'],ARRAY['Kettlebell'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Zawias biodrowy','Martwy ciąg z kettlebell to najprostsza forma wzorca zawiasowego, doskonała dla osób rozpoczynających trening — kettlebell wisi między stopami, co ułatwia utrzymanie naturalnej pozycji pleców.','Stań nad kettlebell z nogami nieco szerzej niż szerokość bioder. Kucnij i chwyć kettlebell oburącz. Wyprostuj plecy, napnij core i unieś kettlebell, wypychając podłogę piętami. Stań prosto, napinając pośladki na górze. Odwróć ruch, opuszczając kettlebell z kontrolą.','Unoszenie bioder przed barkami, przez co dolne plecy przejmują cały ciężar. Zaokrąglanie kręgosłupa piersiowego.','Wyobraź sobie, że ciągniesz podłogę do siebie piętami — to aktywuje tylny łańcuch mięśniowy poprawnie.','Głęboki wdech i wciśnięcie powietrza w brzuch przed podniesieniem, wydech po.','Idealne ćwiczenie wejściowe dla No Activity — zacznij od lekkiego kettlebell i doskonal wzorzec ruchowy.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Siła'],'Zawiasowe','Strzałkowa','Obustronne','Kettlebell',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,true,'Prosta','{"dwugłowe": 0.5, "pośladki": 0.5}'::jsonb),(104,'Hip thrust','hip-thrust','Pośladki',ARRAY['Mięśnie dwugłowe uda','Mięśnie czworogłowe uda'],ARRAY['Sztanga','Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Zawias biodrowy','Hip thrust to jedno z najbardziej efektywnych ćwiczeń na pośladki, wykonywane z plecami opartymi o ławkę i sztangą na biodrach — maksymalny skrót mięśnia pośladkowego w pełnym wyproście.','Oprzyj górną część pleców o ławkę, połóż sztangę na biodrach. Stopy ustaw na szerokość bioder, równolegle lub lekko na zewnątrz. Opuść biodra do podłogi, a następnie gwałtownie wypchnij je do góry, napinając pośladki mocno na szczycie. Utrzymaj wyprost przez chwilę.','Zbyt silne odginanie lędźwi zamiast pełnego wyprostu bioder. Zbyt szerokie lub wąskie ustawienie stóp.','Napnij pośladki aktywnie, a nie tylko unieś biodra. Kolana powinny pozostawać prostopadle do ławki lub lekko na zewnątrz.','Wdech przed opuszczeniem bioder, wydech podczas mocnego wyciśnięcia w górę.','Użyj maty lub podkładki pod sztangę, aby chronić biodra przed dyskomfortem.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Zawiasowe','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Niskie',2,2,3,'Wysoki',true,NULL,'Umiarkowana','{"dwugłowe": 0.15, "pośladki": 0.85}'::jsonb),(105,'Glute bridge','glute-bridge','Pośladki',ARRAY['Mięśnie dwugłowe uda'],ARRAY['Masa własnego ciała','Hantle'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Zawias biodrowy','Glute bridge to podstawowe ćwiczenie aktywujące pośladki wykonywane w leżeniu na podłodze — idealne dla początkujących i jako ćwiczenie rehabilitacyjne.','Połóż się na plecach, kolana ugięte, stopy płasko na podłodze blisko pośladków. Napnij core i mocno wyciśnij biodra w górę, napinając pośladki na szczycie. Utrzymaj pozycję przez chwilę i kontrolowanie opuść biodra.','Zbyt duże odchylanie lędźwi zamiast rzeczywistego wyprostu bioder. Zbyt szerokie lub wąskie ustawienie stóp.','Wyobraź sobie, że zgniatasz orzech pośladkami na górze. Biodra, uda i tułów tworzą prostą linię.','Wdech na dole, wydech podczas wypchnięcia bioder w górę.','Bezpieczne dla osób z bólem dolnego odcinka pleców — wzmacnia stabilizatory lędźwi.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Masa mięśniowa'],'Zawiasowe','Strzałkowa','Obustronne','Masa własnego ciała',false,'Tak','Niskie',1,1,2,'Wysoki',true,true,'Prosta','{"dwugłowe": 0.1, "pośladki": 0.9}'::jsonb),(106,'Uginanie nóg siedząc na maszynie','uginanie-nog-siedzac-na-maszynie','Mięśnie dwugłowe uda',ARRAY[]::text[],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie kolana','Uginanie nóg siedząc na maszynie to izolowane ćwiczenie na kulszowo-goleniowe, w którym biodra są w lekkim zgięciu, co zmienia zaangażowanie mięśnia dwugłowego.','Usiądź w maszynie, ustaw oparcie na odpowiedniej wysokości i umieść wałek nad kostkami. Ugnij kolana, przyciągając wałek do ud, napinając kulszowo-goleniowe na szczycie. Powoli wróć do pozycji wyjściowej.','Unoszenie pośladków z siodełka podczas ruchu. Zbyt szybka faza koncentryczna bez kontroli.','Siedząca pozycja zmienia kąt w biodrach — to inny bodziec niż uginanie leżąc. Obie wersje warto łączyć.','Wydech podczas uginania, wdech podczas powrotu.','Ustaw maszynę tak, by oś obrotu pokrywała się z osią kolana. Nadmierne zaciśnięcie oparcia może powodować dyskomfort.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,3,'Średni',true,NULL,'Prosta',NULL),(107,'Uginanie nóg leżąc na maszynie','uginanie-nog-lezac-na-maszynie','Mięśnie dwugłowe uda',ARRAY['Łydki'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie kolana','Uginanie nóg leżąc na maszynie to klasyczne ćwiczenie izolowane na kulszowo-goleniowe, wykonywane w leżeniu przodem, z wyprostowanymi biodrami.','Połóż się przodem na maszynie, umieszczając wałek powyżej kostek. Trzymaj się uchwytów bocznych i zegnij kolana, przyciągając wałek ku pośladkom. Zatrzymaj się na szczycie napięcia i powoli wróć do wyprostu.','Unoszenie bioder z oparcia podczas pełnego zakresu ruchu. Zbyt szybkie wykonywanie bez napięcia na szczycie.','Leżąca pozycja z wyprostowanymi biodrami maksymalizuje długość kulszowo-goleniowych na starcie. Utrzymuj miednicę płasko na oparciu.','Wydech podczas uginania, wdech podczas wyprostu.','Zacznij od lekkiego zakresu ruchu jeśli masz skrócone kulszowo-goleniowe. Nie forsuj końcowego zakresu.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,3,'Średni',true,NULL,'Prosta',NULL),(108,'Pull-through na wyciągu','pull-through-na-wyciagu','Pośladki',ARRAY['Mięśnie dwugłowe uda'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Zawias biodrowy','Pull-through na wyciągu to ćwiczenie zawiasowe z niskiego wyciągu, które uczy wzorca hip hinge z minimalnym obciążeniem kręgosłupa — idealne do nauki techniki.','Stań przodem od wyciągu, chwyć linkę między nogami. Cofnij kilka kroków i pochyl się do przodu, wysuwając biodra do tyłu. Wyprostuj się, wypychając biodra mocno do przodu i napinając pośladki. Ramiona pozostają proste i pasywne.','Zginanie kolan zbyt mocno, co zamienia ćwiczenie w przysiad. Pochylanie tułowia zamiast wysuwania bioder.','Ćwiczenie uczy ruchu zawiasowego — skup się na wypchnięciu bioder, nie na podciąganiu linki rękami.','Wdech podczas pochylenia z biodrami do tyłu, wydech podczas wyprostu.','Lekki opór i prosta technika czynią to ćwiczenie bezpiecznym wstępem do cięższych wariantów zawiasowych.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Zawiasowe','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,2,2,'Średni',true,NULL,'Umiarkowana',NULL),(109,'Wspięcia na palce stojąc','wspiecia-na-palce-stojac','Łydki',ARRAY[]::text[],ARRAY['Maszyna','Masa własnego ciała','Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Inne','Wspięcia na palce stojąc to izolowane ćwiczenie na mięsień brzuchaty łydki, wykonywane w pełnym wyprostowaniu nogi, co maksymalizuje zaangażowanie tej głowy.','Stań na krawędzi stopnia lub platformy, pięty wysuniętymi poza krawędź. Opuść pięty poniżej poziomu platformy dla pełnego rozciągnięcia. Unieś się na palcach jak najwyżej, napinając łydki. Powoli opuść i powtórz.','Zbyt szybki ruch bez pełnego rozciągnięcia na dole i pełnego napięcia na górze. Ugięte kolana zmniejszają zaangażowanie mięśnia brzuchatego.','Pełny zakres ruchu — od maksymalnego rozciągnięcia do pełnego napięcia — daje najlepsze wyniki. Spróbuj 3-sekundowej fazy ekscentrycznej.','Wydech podczas wspięcia, wdech podczas opuszczania.','Uważaj na równowagę na krawędzi stopnia. Trzymaj się uchwytu dla stabilizacji.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Zawiasowe','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',1,1,3,'Średni',true,NULL,'Prosta',NULL),(110,'Wspięcia na palce siedząc','wspiecia-na-palce-siedzac','Łydki',ARRAY[]::text[],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Inne','Wspięcia na palce siedząc izolują mięsień płaszczkowaty, który jest aktywny przede wszystkim przy ugiętym kolanie — ten wariant uzupełnia stojące wspięcia.','Usiądź w maszynie do siedząco-wspięć, umieszczając wałek na kolanach. Oprzyj śródstopie na platformie, opuść pięty poniżej linii platformy. Unieś się na palcach jak najwyżej, napinając łydki. Powoli wróć do rozciągnięcia.','Skrócony zakres ruchu bez pełnego rozciągnięcia na dole. Zbyt szybkie tempo uniemożliwia efektywną pracę mięśniową.','Mięsień płaszczkowaty jest odporny na zmęczenie — potrzebuje większej ilości powtórzeń niż stojące wspięcia. Stosuj 15–25 powtórzeń.','Wydech na górze, wdech podczas opuszczania.','Sprawdź, że wałek maszyny leży wygodnie na kolanach, nie na kości piszczelowej.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Zawiasowe','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,3,'Średni',true,NULL,'Prosta',NULL),(111,'Odwodzenie nóg na maszynie','odwodzenie-nog-na-maszynie','Odwodziciele',ARRAY['Pośladki'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Odwodzenie','Odwodzenie nóg na maszynie to izolowane ćwiczenie na odwodziciele uda i pośladki boczne, wzmacniające stabilizatory bioder.','Usiądź w maszynie, ustaw oparcie na wewnętrznej stronie nóg. Rozsuń nogi jak najszerzej, napinając pośladek boczny. Powoli wróć do pozycji wyjściowej, kontrolując fazę powrotną.','Zbyt duży opór, przez który ruch wykonuje dolna część pleców zamiast odwodziciele. Zbyt szybka faza powrotna bez kontroli.','Skupiona kontrola po powrocie — nie pozwól, by maszyna biernie przyciągnęła nogi z powrotem.','Wydech podczas rozciągania nóg, wdech podczas ich zbliżania.','Bezdźwięczny powrót nóg do siebie — zbyt szybkie uderzenie rolek nie służy stawom.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Czołowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,2,'Niski',true,NULL,'Prosta',NULL),(112,'Przywodzenie nóg na maszynie','przywodzenie-nog-na-maszynie','Przywodziciele',ARRAY['Pośladki'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Przywodzenie','Przywodzenie nóg na maszynie to izolowane ćwiczenie skupione na przywodzicielach uda, ważnych stabilizatorach kolana i kości miednicy.','Usiądź w maszynie z poduszkami na zewnętrznej stronie ud. Zbliż nogi do siebie, napinając przywodziciele. Kontrolowanie powróć do szerokiego ustawienia, czując rozciągnięcie mięśni wewnętrznej strony uda.','Zbyt duży zakres ruchu powodujący dyskomfort w stawie biodrowym. Zbyt szybka faza ekscentryczna.','Utrzymuj napięcie przywodzicieli przez cały ruch i nie opieraj się o ogranicznik maszyny bezwładnie.','Wydech podczas zbliżania nóg, wdech podczas rozchodzenia.','Ogranicz zakres ruchu, jeśli czujesz dyskomfort w pachwinie lub biodrze.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Czołowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,2,'Niski',true,NULL,'Prosta',NULL),(113,'Wyciskanie hantli na ławce skośnej dodatniej','wyciskanie-hantli-na-awce-skosnej-dodatniej','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie poziome','Wyciskanie hantli na ławce skośnej akcentuje górną część klatki piersiowej dzięki kątowi nachylenia ławki 30–45°, angażując jednocześnie tricepsy i przednie naramienne.','Ustaw ławkę pod kątem 30–45°. Usiądź z hantlami na kolanach, a następnie unieś je do pozycji wyjściowej — na poziomie górnej klatki piersiowej. Wyciśnij hantle w górę i lekko do środka, kontrolowanie opuść do pełnego rozciągnięcia mięśnia piersiowego.','Zbyt duże nachylenie ławki (ponad 45°) przenosi nacisk z klatki na barki. Niekontrolowane odbijanie hantli od klatki piersiowej.','Łokcie powinny znajdować się pod kątem ok. 45–75° do tułowia — nie w płaskiej linii z ramionami. Czuj rozciągnięcie klatki na dole.','Wdech podczas opuszczania hantli, wydech podczas wyciskania.','Unikaj pełnego wyprostu łokci na szczycie — zostawia to napięcie w mięśniach zamiast przerzucać je na stawy.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Pchanie','Poprzeczna','Obustronne','Hantle',false,'Z ostrożnością','Średnie',2,2,3,'Wysoki',true,NULL,'Umiarkowana','{"mid_chest": 0.3, "lower_chest": 0.1, "upper_chest": 0.6}'::jsonb),(114,'Wyciskanie sztangi na ławce skośnej dodatniej','wyciskanie-sztangi-na-awce-skosnej-dodatniej','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Sztanga','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie poziome','Wyciskanie sztangi na ławce skośnej to złożone ćwiczenie na górną część klatki piersiowej, pozwalające na duże obciążenia dzięki stabilności chwytu oburącz.','Ustaw ławkę na 30–45°. Chwyć sztangę nachwytem nieco szerzej niż szerokość barków. Opuść sztangę do górnej klatki piersiowej, utrzymując łokcie pod kątem 45–75°. Wyciśnij do góry bez blokowania łokci na szczycie.','Zbyt szerokie ustawienie rąk zwiększa ryzyko urazu barku. Odbijanie sztangi od klatki piersiowej.','Używaj tej samej techniki co przy płaskim wyciskaniu, ale skieruj wysiłek na górną część klatki piersiowej przez wyobrażenie sobie ''zgniatania'' piersi ku górze.','Wdech podczas opuszczania sztangi, wydech podczas wyciskania.','Zawsze miej dostępnego asekuranta lub stosuj bezpieczniki — szczególnie przy cięższych seriach.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Sztanga',true,'Z ostrożnością','Średnie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"mid_chest": 0.3, "lower_chest": 0.1, "upper_chest": 0.6}'::jsonb),(115,'Wyciskanie na maszynie siedząc','wyciskanie-na-maszynie-siedzac','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Pchanie poziome','Wyciskanie na maszynie do klatki piersiowej to idealne ćwiczenie dla początkujących — prowadnica maszyny eliminuje wymóg stabilizacji i pozwala skupić się na pracy mięśni klatki.','Ustaw siodełko tak, by uchwyty były na poziomie środkowej klatki piersiowej. Chwyć uchwyty, łokcie pod kątem 45–75°. Wyciśnij ramiona do przodu, nie blokując łokci. Powoli wróć do pozycji wyjściowej, czując rozciągnięcie klatki.','Zbyt niskie lub zbyt wysokie siodełko zmienia kąt pracy klatki. Wzruszanie barkami podczas wyciskania.','Cofnij łopatki i napnij je razem przed każdą serią — to chroni barki i wzmacnia nacisk na klatkę.','Wdech podczas cofania rąk, wydech podczas wyciskania.','Bezpieczna opcja dla osób zaczynających trening klatki — brak potrzeby asekuranty.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Pchanie','Poprzeczna','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,2,2,'Wysoki',true,true,'Prosta','{"mid_chest": 0.6, "lower_chest": 0.2, "upper_chest": 0.2}'::jsonb),(116,'Pompki na podwyższeniu','pompki-na-podwyzszeniu','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Pchanie poziome','Pompki na podwyższeniu zmniejszają udźwignięty procent masy ciała i służą jako progresja od pompek na kolanach do pompek klasycznych.','Oprzyj dłonie na stabilnym podwyższeniu (ławka, stół, parapet) na szerokość nieco ponad barki. Ciało tworzy prostą linię. Zegnij łokcie i opuść klatkę do podwyższenia. Wypchnij się do góry, nie blokując łokci.','Opadające biodra lub wygięte w górę pośladki przerywają prawidłową linię ciała. Głowa powinna być neutralna, nie opuszczona.','Im wyższe podwyższenie, tym łatwiejsze ćwiczenie. Stopniowo obniżaj poziom podporu, by przejść do pompek klasycznych.','Wdech podczas opuszczania, wydech podczas wypychania.','Upewnij się, że podwyższenie jest stabilne i nie ześlizgnie się pod ciężarem ciała.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Tak','Niskie',1,1,2,'Wysoki',true,true,'Prosta','{"mid_chest": 0.35, "lower_chest": 0.55, "upper_chest": 0.1}'::jsonb),(117,'Pompki klasyczne','pompki-klasyczne','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener','Plener'],'Początkujący','Pchanie poziome','Pompki klasyczne to fundamentalne ćwiczenie na klatkę piersiową, tricepsy i barki z masą własnego ciała, dostępne wszędzie bez sprzętu.','Przyjmij pozycję podporu na dłoniach nieco szerzej niż barki. Ciało tworzy prostą linię od głowy do pięt. Zegnij łokcie i opuść klatkę do podłogi, bez dotykania. Wypchnij się mocno do pozycji wyjściowej.','Opadanie miednicy do podłogi lub wygięcie pośladków zbyt wysoko. Ustawienie rąk zbyt szeroko lub zbyt wąsko.','Kciuk i palec wskazujący tworzą trójkąt — to wygodne i efektywne ustawienie dłoni dla większości osób.','Wdech podczas opuszczania, wydech podczas wypychania.','Jeśli masz ból nadgarstków, spróbuj pompek na pięściach lub na poręczach.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Tak','Niskie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"mid_chest": 0.55, "lower_chest": 0.25, "upper_chest": 0.2}'::jsonb),(118,'Pompki na kolanach','pompki-na-kolanach','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Pchanie poziome','Pompki na kolanach to regresja pompek klasycznych zmniejszająca udźwignięty procent masy ciała — dobra opcja dla osób zaczynających lub powracających po przerwie.','Połóż kolana na podłodze, stopy uniesione. Dłonie nieco szerzej niż barki. Opuść klatkę ku podłodze, utrzymując proste plecy od kolan do głowy. Wypchnij się do góry.','Zapadanie się w biodrach tak, że ciało tworzy łuk. Zbyt wolne lub zbyt szybkie tempo bez kontroli.','To ćwiczenie przejściowe — gdy robisz 15–20 powtórzeń łatwo, przejdź do pompek na podwyższeniu.','Wdech podczas opuszczania, wydech podczas wypychania.','Podłóż miękką matę pod kolana dla komfortu stawów.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący'],ARRAY['Zdrowie ogólne','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Tak','Niskie',1,1,1,'Średni',true,true,'Prosta','{"mid_chest": 0.55, "lower_chest": 0.25, "upper_chest": 0.2}'::jsonb),(119,'Rozpiętki na maszynie Pec Deck','rozpietki-na-maszynie-pec-deck','Klatka piersiowa',ARRAY['Barki'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Przywodzenie','Rozpiętki na maszynie Pec Deck izolują mięsień piersiowy większy przez ruch przywodzenia poziomego, bez angażowania tricepsów jako głównych stabilizatorów.','Usiądź z plecami przylegającymi do oparcia. Chwyć uchwyty boczne lub ustaw przedramiona na ramionach maszyny. Zbliż ramiona do siebie przed klatką, napinając mięsień piersiowy. Powoli wróć do pozycji wyjściowej, nie dopuszczając do przeprostu.','Zbyt szeroki zakres ruchu powrotu powoduje nadmierne napięcie barku. Wzruszanie barkami zamiast pracy klatki.','Myśl o ''zaciskaniu ołówka'' między klatkami — to aktywuje mięsień piersiowy lepiej niż myślenie o ruchach rąk.','Wydech podczas zbliżania ramion, wdech podczas powrotu.','Nie cofaj ramion poza neutralną pozycję barkową — ryzyko urazu kaletki barkowej.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,3,'Średni',true,NULL,'Prosta','{"mid_chest": 0.6, "lower_chest": 0.15, "upper_chest": 0.25}'::jsonb),(120,'Rozpiętki na bramie na wysokości klatki','rozpietki-na-bramie-na-wysokosci-klatki','Klatka piersiowa',ARRAY['Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przywodzenie','Rozpiętki na bramie na poziomie klatki piersiowej z linkami ustawionymi po bokach izolują mięsień piersiowy w środkowej i zewnętrznej strefie.','Ustaw wyciągi na poziomie klatki piersiowej. Chwyć uchwyty i wejdź krok do przodu. Pochyl tułów lekko do przodu, ramiona lekko ugięte w łokciach. Zbliż uchwyty przed sobą łukiem, napinając klatkę. Powoli powróć do szerokiej pozycji.','Prostowanie łokci i przekształcanie ćwiczenia w wyciskanie. Zbyt wąski zakres ruchu powrotnego.','Wyobraź sobie, że obejmujesz duże drzewo — łokcie pozostają stale lekko ugięte i skierowane na zewnątrz.','Wydech podczas zbliżania uchwytów, wdech podczas rozchodzenia.','Kontroluj ruch powrotny, by nie przeciążać tylnej kapsułki barku.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,3,'Średni',true,NULL,'Umiarkowana','{"mid_chest": 0.6, "lower_chest": 0.15, "upper_chest": 0.25}'::jsonb),(121,'Rozpiętki na bramie z dołu do góry','rozpietki-na-bramie-z-do-u-do-gory','Klatka piersiowa',ARRAY['Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przywodzenie','Rozpiętki z dołu do góry akcentują górną część klatki piersiowej przez ukos ruchu z dołu ku górze i do środka, co angażuje włókna obojczykowe mięśnia piersiowego.','Ustaw wyciągi nisko przy podłodze. Chwyć uchwyty i wejdź krok do przodu. Z pochylonym tułowiem lub wyprostowanym, unieś ramiona ku górze i ku środkowi, zatrzymując uchwyty na poziomie klatki lub wyżej. Powoli powróć.','Prostowanie łokci i angażowanie tricepsów. Zbyt małe unoszenie rąk, przez co nie trafia się w górną klatkę.','Końcowy punkt ruchu powinien być powyżej klatki piersiowej — wtedy górna część klatki jest maksymalnie zaangażowana.','Wydech podczas zbliżania uchwytów w górę, wdech podczas powrotu.','Upewnij się, że linki wyciągu nie zahaczają o ciało podczas ruchu.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,3,'Średni',true,NULL,'Umiarkowana','{"mid_chest": 0.25, "lower_chest": 0.1, "upper_chest": 0.65}'::jsonb),(122,'Rozpiętki na bramie z góry w dół','rozpietki-na-bramie-z-gory-w-do','Klatka piersiowa',ARRAY['Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przywodzenie','Rozpiętki z góry w dół akcentują dolną część klatki piersiowej przez ruch z góry ku dołowi i do środka, angażując głównie włókna sternalne mięśnia piersiowego.','Ustaw wyciągi wysoko powyżej głowy. Chwyć uchwyty i wejdź krok do przodu. Z pionowym lub lekko pochylonym tułowiem, opuść ramiona ku dołowi i ku środkowi, zatrzymując uchwyty na poziomie bioder. Powoli wróć.','Zbyt duże pochylenie do przodu zamienia ćwiczenie w wiosłowanie. Prostowanie łokci i angażowanie tricepsów.','Czuj dolną część klatki — napinaj ją aktywnie w końcowym punkcie ruchu. Łokcie lekko ugięte przez cały czas.','Wydech podczas opuszczania uchwytów ku dołowi, wdech podczas powrotu.','Powolna i kontrolowana faza powrotna chroni bark przed nadmiernym rozciągnięciem.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,3,'Średni',true,NULL,'Umiarkowana','{"mid_chest": 0.25, "lower_chest": 0.65, "upper_chest": 0.1}'::jsonb) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,main_muscle_group=EXCLUDED.main_muscle_group,secondary_muscle_groups=EXCLUDED.secondary_muscle_groups,equipment=EXCLUDED.equipment,training_location=EXCLUDED.training_location,difficulty_level=EXCLUDED.difficulty_level,movement_pattern=EXCLUDED.movement_pattern,exercise_type=EXCLUDED.exercise_type,suitable_experience_levels=EXCLUDED.suitable_experience_levels,training_goals=EXCLUDED.training_goals,movement_category=EXCLUDED.movement_category,is_active=EXCLUDED.is_active,exercise_priority=EXCLUDED.exercise_priority,sub_target_biases=EXCLUDED.sub_target_biases`;

const SQL_EXERCISES_1 = `INSERT INTO exercises (id,name,slug,main_muscle_group,secondary_muscle_groups,equipment,equipment_other,training_location,difficulty_level,movement_pattern,description,execution_instructions,common_mistakes,coaching_tips,breathing_tips,safety_notes,exercise_type,suitable_experience_levels,training_goals,movement_category,plane_of_motion,execution,resistance_type,requires_spotter,can_be_performed_to_failure,joint_stress,learning_difficulty,neurological_fatigue,doms_potential,exercise_priority,is_active,suitable_for_no_activity,movement_complexity,sub_target_biases) VALUES (123,'Ściąganie drążka wyciągu górnego chwytem neutralnym','sciaganie-drazka-wyciagu-gornego-chwytem-neutralnym','Plecy',ARRAY['Biceps','Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie pionowe','Ściąganie drążka z chwytem neutralnym (dłonie zwrócone ku sobie) to przyjazna dla barków wersja lat pulldown, angażująca latissimus dorsi i bicepsy.','Usiądź w maszynie i chwyć drążek V-bar chwytem neutralnym. Ustabilizuj udami pod podpórką. Ściągnij drążek do górnej klatki piersiowej, prowadząc łokcie w dół i za siebie. Napnij mięśnie pleców na dole ruchu i powoli wróć do góry.','Odchylanie tułowia do tyłu i generowanie zamachu zamiast pracy mięśni grzbietu. Unoszenie ramion do uszu zamiast cofania łopatkę.','Zanim zaczniesz ciągnąć, wyobraź sobie, że za pomocą łokci próbujesz dotknąć tylnych kieszeni spodni.','Wdech w górze, wydech podczas ściągania.','Idealne ćwiczenie dla No Activity i początkujących — opór łatwo regulowany wyciągiem.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,true,'Prosta','{"lats": 0.65, "upper_back": 0.35}'::jsonb),(124,'Ściąganie drążka wyciągu górnego szerokim nachwytem','sciaganie-drazka-wyciagu-gornego-szerokim-nachwytem','Plecy',ARRAY['Biceps','Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie pionowe','Ściąganie szerokim nachwytem to klasyczna wersja lat pulldown, akcentująca szerokie rozłożenie latissimus dorsi.','Chwyć drążek nachwytem szerzej niż szerokość barków. Usiądź pod drążkiem z klatką wysuniętą lekko do przodu. Ściągnij drążek do górnej klatki, prowadząc łokcie w dół. Na dole napnij mocno plecy i powoli wróć.','Ściąganie drążka za szyję — ryzyko urazu szyjnego kręgosłupa. Zbyt szeroki chwyt ogranicza zakres ruchu.','Ściągaj drążek do klatki, nie za głowę. Łopatki cofaj i opuszczaj przed każdym powtórzeniem.','Wdech w górze, wydech podczas ściągania.','Nigdy nie ściągaj drążka za głowę — może spowodować uraz szyjnego odcinka kręgosłupa.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,true,'Prosta','{"lats": 0.7, "upper_back": 0.3}'::jsonb),(125,'Ściąganie drążka wyciągu górnego podchwytem','sciaganie-drazka-wyciagu-gornego-podchwytem','Plecy',ARRAY['Biceps'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie pionowe','Ściąganie podchwytem (dłonie skierowane ku sobie) bardziej angażuje bicepsy i często odczuwane jest jako łatwiejsze do izolowania pleców.','Chwyć drążek podchwytem na szerokość barków lub nieco węziej. Ściągnij drążek do górnej klatki, prowadząc łokcie prosto w dół wzdłuż tułowia. Napnij mięśnie pleców na dole i wróć kontrolowanie.','Zbyt wąski lub zbyt szeroki podchwyt ogranicza efektywność. Odchylanie tułowia do tyłu zamiast pracy plecami.','Podchwyt pozwala na większe zaangażowanie bicepsów — dobre ćwiczenie dla osób, które chcą jednocześnie ćwiczyć plecy i bicepsy.','Wdech w górze, wydech podczas ściągania.','Sprawdź, czy nadgarstki są komfortowo ustawione — podchwyt może być niekomfortowy przy słabej mobilności.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"lats": 0.65, "upper_back": 0.35}'::jsonb),(126,'Podciąganie na maszynie wspomagającej','podciaganie-na-maszynie-wspomagajacej','Plecy',ARRAY['Biceps'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie pionowe','Podciąganie na maszynie wspomagającej pozwala ćwiczyć wzorzec podciągania ze zmniejszonym ciężarem ciała, budując siłę potrzebną do samodzielnych podciągnięć.','Stań lub klęknij na platformie maszyny. Chwyć drążek nachwytem lub podchwytem na szerokość barków. Podciągnij się, prowadząc łokcie w dół i za siebie. Utrzymaj klatkę do góry i powoli wróć do pełnego wyprostu ramion.','Wzruszanie barkami i unoszenie głowy zamiast prowadzenia klatkę do drążka. Skracanie zakresu ruchu.','Im mniejszy ciężar wspomagający, tym trudniejsze ćwiczenie. Stopniowo zmniejszaj wspomaganie, by przejść do samodzielnych podciągnięć.','Wydech podczas podciągania, wdech podczas opuszczania.','Bezpieczna forma nauki podciągnięć — bez ryzyka upadku.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"lats": 0.7, "upper_back": 0.3}'::jsonb),(127,'Podciąganie na drążku chwytem neutralnym','podciaganie-na-drazku-chwytem-neutralnym','Plecy',ARRAY['Biceps'],ARRAY['Drążek'],NULL,ARRAY['Siłownia','Dom','Plener'],'Zaawansowany','Przyciąganie pionowe','Podciąganie chwytem neutralnym (dłonie ku sobie) angażuje latissimus dorsi i bicepsy w bardziej naturalnej pozycji barkowej, często odczuwanej jako łatwiejsza niż nachwytem.','Chwyć równoległe uchwyty drążka chwytem neutralnym. Zwis z wyprostowanymi ramionami. Podciągnij się, prowadząc łokcie w dół i ku biodrze, aż broda przekroczy poziom drążka. Powoli wróć do pełnego wyprostu.','Kiwanie całym ciałem do przodu i do tyłu zamiast izolowanego ruchu ramion i pleców. Niewystarczający zakres ruchu — zatrzymywanie się przed pełnym wyprostem.','Na szczycie ruchu staraj się przybliżyć klatkę do drążka, nie brody do drążka — to angażuje plecy bardziej niż bicepsy.','Wydech podczas podciągania, wdech podczas opuszczania.','Zacznij od mniejszej liczby powtórzeń z pełnym zakresem ruchu zamiast wielu półpowtórzeń.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Średnie',4,3,3,'Wysoki',true,NULL,'Złożona','{"lats": 0.65, "upper_back": 0.35}'::jsonb),(128,'Wiosłowanie siedząc na wyciągu chwytem neutralnym','wios-owanie-siedzac-na-wyciagu-chwytem-neutralnym','Plecy',ARRAY['Biceps','Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie poziome','Wiosłowanie siedząc na wyciągu z drążkiem V-bar to podstawowe ćwiczenie na środkowy i dolny trapez oraz latissimus dorsi, bezpieczne dla barków dzięki neutralnemu chwytowi.','Usiądź na siodełku, chwyć drążek V-bar chwytem neutralnym. Wyprostuj plecy i lekko cofnij tułów. Ciągnij drążek do pępka, sprowadzając łokcie wzdłuż tułowia. Napnij mięśnie środka pleców i powoli wróć.','Odchylanie tułowia do tyłu i generowanie zamachu. Zaokrąglanie dolnych pleców przy powrocie do pozycji wyjściowej.','Łopatki najpierw — cofaj je zanim zaczniesz ciągnąć, to inicjuje ruch plecami, nie bicepsami.','Wdech przed ciągnięciem, wydech podczas wiosłowania.','Regulowane obciążenie wyciągu czyni to ćwiczenie bezpiecznym dla każdego poziomu zaawansowania.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,true,'Prosta','{"lats": 0.35, "upper_back": 0.65}'::jsonb),(129,'Wiosłowanie hantlami z podparciem klatki','wios-owanie-hantlami-z-podparciem-klatki','Plecy',ARRAY['Biceps'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie poziome','Wiosłowanie hantlami z klatką opartą o ławkę skośną eliminuje rotację tułowia i pozwala skupić się na bilateralnej pracy mięśni pleców.','Ustaw ławkę pod kątem 45°. Oprzyj klatkę o ławkę, trzymając hantle. Ciągnij hantle ku górze, prowadząc łokcie wzdłuż boków ciała. Napnij mięśnie pleców na szczycie i powoli opuść.','Rotacja tułowia zamiast izolowanej pracy pleców. Wzruszanie barkami przy wyciąganiu hantli.','Podparcie klatki o ławkę stabilizuje tułów — możesz skupić się wyłącznie na sile pleców.','Wdech przed ciągnięciem, wydech podczas wiosłowania.','Dobierz kąt ławki tak, by ramiona swobodnie zwisały prostopadle do podłogi w pozycji wyjściowej.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"lats": 0.3, "upper_back": 0.7}'::jsonb),(130,'Wiosłowanie na maszynie','wios-owanie-na-maszynie','Plecy',ARRAY['Biceps'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie poziome','Wiosłowanie na maszynie to bezpieczna i efektywna wersja wiosłowania z prowadnicą, idealna dla początkujących i osób, które chcą uniknąć zaokrąglania pleców.','Usiądź w maszynie, oprzyj klatkę o podpórkę lub uchwyć siodełko. Chwyć uchwyty i ciągnij je ku sobie, prowadząc łokcie wzdłuż tułowia. Napnij mięśnie pleców i powoli wróć.','Zbyt duży zakres ruchu ramion powoduje utratę napięcia pleców. Używanie zamachu tułowia.','Maszyna zapewnia stabilność — skoncentruj się na maksymalnym napięciu mięśni grzbietu na szczycie ruchu.','Wdech przed ciągnięciem, wydech podczas wiosłowania.','Bezpieczna i prosta opcja dla osób zaczynających pracę nad plecami.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Ciągnięcie','Strzałkowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,true,'Prosta','{"lats": 0.3, "upper_back": 0.7}'::jsonb),(131,'Wiosłowanie jednorącz hantlem','wios-owanie-jednoracz-hantlem','Plecy',ARRAY['Biceps'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Przyciąganie poziome','Jednostronne wiosłowanie hantlem z podparciem kolana i dłoni na ławce to ćwiczenie na latissimus dorsi i środkowy trapez, umożliwiające większy zakres ruchu niż wiosłowanie obustronne.','Oprzyj kolano i dłoń jednej strony na ławce. Chwyć hantel drugą ręką z prostym kręgosłupem. Ciągnij hantel ku górze, prowadząc łokieć wzdłuż tułowia. Napnij plecy na szczycie i powoli opuść.','Rotacja tułowia zamiast pracy pleców. Unoszenie barku zamiast prowadzenia łokciem.','Obróć hantel lekko podczas ciągnięcia — kciuk do góry na dole, kciuk do środka na górze — to aktywuje latissimus bardziej.','Wdech w dolnej pozycji, wydech podczas ciągnięcia.','Ławka musi być stabilna i nie ześlizgnąć się podczas pracy unilateralnej.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Strzałkowa','Jednostronne','Hantle',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"lats": 0.35, "upper_back": 0.65}'::jsonb),(132,'Wiosłowanie T-bar z podparciem klatki','wios-owanie-t-bar-z-podparciem-klatki','Plecy',ARRAY['Biceps','Barki'],ARRAY['Sztanga','Maszyna'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przyciąganie poziome','Wiosłowanie T-bar z podparciem klatki o specjalną maszynę eliminuje zmęczenie prostowników grzbietu, pozwalając skupić się na środkowej części pleców.','Połóż klatkę na podpórce maszyny T-bar. Chwyć uchwyty z boku. Ciągnij uchwyty ku górze, prowadząc łokcie wzdłuż tułowia. Napnij mięśnie środka pleców i powoli opuść.','Zbyt duży ciężar powodujący rotację tułowia lub unoszenie bioder. Wzruszanie barkami zamiast pracy łopatkami.','Wiosłowanie T-bar z podparciem klatki pozwala dźwigać większy ciężar niż klasyczne wiosłowanie — użyj tej przewagi do budowania masy środkowych pleców.','Wdech przed ciągnięciem, wydech podczas wiosłowania.','Sprawdź, że klatka jest wygodnie oparta i nie uciska mostek. Dostosuj siodełko do swojego wzrostu.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Średnie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"lats": 0.35, "upper_back": 0.65}'::jsonb),(133,'Wiosłowanie na TRX','wios-owanie-na-trx','Plecy',ARRAY['Biceps','Brzuch'],ARRAY['TRX'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Przyciąganie poziome','Wiosłowanie na TRX to ćwiczenie złożone z masą własnego ciała angażujące plecy, bicepsy i core przez utrzymanie pozycji ciała podczas ruchu.','Chwyć uchwyty TRX, odchyl tułów do tyłu (ciało skośne). Im bardziej poziome ciało, tym trudniejsze. Ciągnij uchwyty ku klatce, utrzymując ciało w linii prostej. Powoli wyprostuj ramiona.','Opadanie bioder podczas ruchu — ciało traci prostą linię. Zbyt pionowa pozycja zmniejsza intensywność.','Reguluj trudność, zmieniając kąt nachylenia ciała. Napnij core przez cały ruch jak w desce.','Wdech w pozycji wyciągniętej, wydech podczas wiosłowania.','Dostosuj kąt ciała do swoich możliwości. Kotwica TRX musi być pewna i bezpieczna.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Ciągnięcie','Strzałkowa','Obustronne','TRX',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,true,'Prosta','{"lats": 0.3, "upper_back": 0.7}'::jsonb),(134,'Wiosłowanie gumą oporową','wios-owanie-guma-oporowa','Plecy',ARRAY['Biceps'],ARRAY['Gumy oporowe'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Przyciąganie poziome','Wiosłowanie gumą oporową to dostępna wszędzie forma ćwiczenia na plecy, idealna dla osób bez dostępu do siłowni lub jako uzupełnienie rehabilitacji.','Przytwierdź gumę do stabilnego punktu na poziomie talii. Chwyć końce gumy oburącz i cofnij się, aby guma była napięta. Z wyprostowanymi plecami ciągnij gumy ku pępkowi, prowadząc łokcie wzdłuż tułowia. Powoli wróć.','Zbyt duże odchylanie tułowia do tyłu. Gumy zbyt luźne — brak odpowiedniego oporu.','Lekki stały opór gumy jest szczególnie bezpieczny na zakończenie treningu lub dla rehabilitacji barków.','Wdech przed ciągnięciem, wydech podczas wiosłowania.','Sprawdzaj regularnie stan gumy — zużyte gumy mogą pęknąć i uderzyć w twarz.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Ciągnięcie','Strzałkowa','Obustronne','Gumy oporowe',false,'Tak','Niskie',1,1,1,'Wysoki',true,true,'Prosta','{"lats": 0.3, "upper_back": 0.7}'::jsonb),(135,'Ściąganie prostych ramion na wyciągu','sciaganie-prostych-ramion-na-wyciagu','Plecy',ARRAY['Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie pionowe','Ściąganie prostych ramion na wyciągu (straight-arm pulldown) to izolowane ćwiczenie na latissimus dorsi — wykonywane z prostymi łokciami, całkowicie eliminuje bicepsy z ruchu.','Stań przed wyciągiem górnym, chwyć drążek prostymi ramionami nachwytem. Lekko pochyl tułów do przodu. Opuść drążek ku biodom łukiem, trzymając łokcie stale lekko ugięte. Napnij latissimus na dole i powoli wróć.','Zginanie łokci i zamienianie ćwiczenia w pulldown. Zbyt mały zakres ruchu — drążek powinien dochodzić do bioder.','To ćwiczenie izoluje lats bez udziału bicepsów — doskonałe, gdy chcesz poczuć i aktywować mięsień najszerszy.','Wydech podczas opuszczania drążka, wdech podczas powrotu.','Nie forsuj zakresu ruchu — stop tam, gdzie kręgosłup zaczyna się wyginać.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,2,'Średni',true,NULL,'Umiarkowana','{"lats": 0.8, "upper_back": 0.2}'::jsonb),(136,'Face pull','face-pull','Barki',ARRAY['Plecy'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Przyciąganie poziome','Face pull to kluczowe ćwiczenie prewencyjne na tylne naramienne i stożek rotatorów, wykonywane na wyciągu górnym z liną, chroniące zdrowie barków.','Ustaw wyciąg na poziomie twarzy. Chwyć linkę chwytem neutralnym, odsuń się kilka kroków. Ciągnij linkę ku twarzy, rozdzielając końce linki w stronę uszu, łokcie wysoko. Napnij tylne naramienne i mięśnie lopatki na końcu ruchu i powoli wróć.','Zbyt niski wyciąg powoduje wiosłowanie zamiast face pull. Łokcie opuszczone, a nie uniesione ku bokom.','Łokcie muszą być powyżej poziomu ramion — to klucz do zaangażowania tylnych naramiennych i rotatorów.','Wydech podczas ciągnięcia linki do twarzy, wdech podczas powrotu.','Lekki opór i wysoka liczba powtórzeń (15–25) daje najlepsze wyniki dla zdrowia barków.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Masa mięśniowa'],'Ciągnięcie','Poprzeczna','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,2,'Wysoki',true,true,'Prosta','{"rear_delt": 0.7, "upper_back": 0.1, "lateral_delt": 0.2}'::jsonb),(137,'Wyciskanie na maszynie nad głowę','wyciskanie-na-maszynie-nad-g-owe','Barki',ARRAY['Triceps'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Pchanie pionowe','Wyciskanie nad głowę na maszynie to złożone ćwiczenie na barki z prowadnicą, które stabilizuje ruch i pozwala bezpiecznie rozwijać siłę naramiennych.','Usiądź i dostosuj siodełko tak, by uchwyty znajdowały się na poziomie barków lub nieco powyżej. Wyciśnij uchwyty prosto w górę, nie blokując łokci. Powoli opuść poniżej poziomu ramion.','Zbyt wysokie siodełko powoduje wyciskanie z ramionami nad głową bez prawidłowego zaangażowania naramiennych. Blokowanie łokci na szczycie.','Cofnij głowę minimalnie, by drążek lub uchwyty maszyny swobodnie przeszły przed twarzą — nie odchylaj tułowia mocno do tyłu.','Wdech podczas opuszczania, wydech podczas wyciskania.','Bezpieczna opcja dla osób zaczynających wyciskanie nad głowę — brak potrzeby asekuranty.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Pchanie','Czołowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,2,2,'Wysoki',true,true,'Prosta','{"rear_delt": 0.1, "front_delt": 0.55, "lateral_delt": 0.35}'::jsonb),(138,'Arnold press','arnold-press','Barki',ARRAY['Triceps'],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Średniozaawansowany','Pchanie pionowe','Arnold press to wyciskanie hantli z rotacją nadgarstków, angażujące wszystkie trzy głowy mięśnia naramiennego — szczególnie efektywne na przedni i boczny naramienny.','Zacznij z hantlami na poziomie twarzy, dłonie skierowane ku sobie. Wyciśnij hantle w górę, rotując nadgarstki na zewnątrz tak, że na górze dłonie są odwrócone od siebie. Powoli wróć, odwracając ruch.','Zbyt szybka rotacja bez kontroli nadgarstków. Nadmierne odchylanie tułowia do tyłu.','Rotacja musi być płynna i skoordynowana z wyciskaniem — nie odrębny ruch, ale zintegrowany.','Wydech podczas wyciskania i rotacji w górę, wdech podczas powrotu.','Osoby z bólem barku lub ograniczoną rotacją zewnętrzną powinny unikać tego ćwiczenia.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Czołowa','Obustronne','Hantle',false,'Z ostrożnością','Średnie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"rear_delt": 0.1, "front_delt": 0.5, "lateral_delt": 0.4}'::jsonb),(139,'Wyciskanie hantli siedząc','wyciskanie-hantli-siedzac','Barki',ARRAY['Triceps'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Pchanie pionowe','Wyciskanie hantli siedząc nad głowę to klasyczne ćwiczenie na wszystkie głowy naramiennych, wykonywane w stabilnej pozycji siedzącej.','Usiądź na ławce z oparciem lub bez. Hantle na poziomie barków, dłonie skierowane do przodu lub lekko na zewnątrz. Wyciśnij hantle prosto w górę, zbliżając je ku sobie łagodnie. Powoli opuść poniżej poziomu ramion.','Zbyt wąskie sprowadzenie hantli powyżej głowy — ryzyko urazu barku. Nadmierne odchylanie tułowia do tyłu.','Hantle na szczycie nie powinny się dotykać — zostaw pomiędzy nimi przerwę. Praca przez pełen zakres ruchu daje najlepsze wyniki.','Wdech podczas opuszczania hantli, wydech podczas wyciskania.','Wyciśnij hantle z kolan — nie rzucaj ich od dołu do pozycji wyjściowej.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Pchanie','Czołowa','Obustronne','Hantle',false,'Z ostrożnością','Średnie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"rear_delt": 0.1, "front_delt": 0.55, "lateral_delt": 0.35}'::jsonb),(140,'Unoszenie hantli bokiem','unoszenie-hantli-bokiem','Barki',ARRAY[]::text[],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Odwodzenie','Unoszenie hantli bokiem (lateral raise) to izolowane ćwiczenie na boczną głowę mięśnia naramiennego, odpowiedzialne za wizualne poszerzenie sylwetki.','Stań z hantlami wzdłuż tułowia, łokcie lekko ugięte. Unosić ramiona bocznym łukiem do poziomu barków — nie wyżej. Zatrzymaj się na chwilę i powoli opuść.','Unoszenie hantli powyżej poziomu barków angażuje pułapki zamiast bocznych naramiennych. Wzruszanie barkami podczas ruchu.','Wyobraź sobie, że wylewasz wodę z dzbanka kciukiem ku dołowi — ta rotacja wewnętrzna lepiej aktywuje boczny naramienny.','Wydech podczas unoszenia ramion, wdech podczas opuszczania.','Lekki ciężar i duża liczba powtórzeń to klucz — za ciężkie hantle powodują użycie zamachu.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Czołowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',1,1,3,'Wysoki',true,NULL,'Prosta','{"rear_delt": 0.1, "front_delt": 0.1, "lateral_delt": 0.8}'::jsonb),(141,'Unoszenie ramienia bokiem na wyciągu','unoszenie-ramienia-bokiem-na-wyciagu','Barki',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Odwodzenie','Jednostronne unoszenie ramienia na wyciągu bocznym zapewnia stały opór przez cały zakres ruchu — bardziej efektywny bodziec niż hantle w dolnej fazie.','Stań bokiem do wyciągu, chwyć uchwyt ręką dalszą od maszyny. Unoś ramię bocznym łukiem do poziomu barków, utrzymując łokieć lekko ugięty. Powoli opuść i powtórz, następnie zmień stronę.','Wzruszanie barkami i używanie tułowia jako dźwigni. Zbyt wysoki zakres ruchu.','Wyciąg od dołu utrzymuje napięcie przez cały ruch, w tym w dolnej fazie — wykorzystaj to, nie przyspieszaj.','Wydech podczas unoszenia, wdech podczas opuszczania.','Reguluj wysokość wyciągu tak, by ciągnął z poziomu bioder, nie z podłogi.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Czołowa','Jednostronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,2,'Wysoki',true,NULL,'Umiarkowana','{"rear_delt": 0.1, "front_delt": 0.1, "lateral_delt": 0.8}'::jsonb),(142,'Unoszenie ramion bokiem na maszynie','unoszenie-ramion-bokiem-na-maszynie','Barki',ARRAY[]::text[],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Odwodzenie','Maszyna do unoszenia ramion bokiem zapewnia stały opór w pełnym zakresie ruchu, eliminując zamach i idealnie izolując boczną głowę naramienną.','Usiądź w maszynie, ramiona wzdłuż ramion maszyny. Unoś ramiona łukiem ku górze do poziomu barków lub nieco powyżej. Powoli wróć do pozycji wyjściowej bez całkowitego zwolnienia napięcia.','Siedzenie zbyt nisko lub zbyt wysoko — oś obrotu musi pokrywać się ze stawem barkowym.','Maszyna pozwala używać umiarkowanego ciężaru z pełnym skupieniem na bocznych naramiennych bez ryzyka kontuzji.','Wydech podczas unoszenia, wdech podczas opuszczania.','Dostosuj siodełko i ramiona maszyny do swojej budowy ciała przed rozpoczęciem ćwiczenia.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Czołowa','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,true,'Prosta','{"rear_delt": 0.1, "front_delt": 0.1, "lateral_delt": 0.8}'::jsonb),(143,'Odwrotne rozpiętki na maszynie Pec Deck','odwrotne-rozpietki-na-maszynie-pec-deck','Barki',ARRAY['Plecy'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Odwodzenie','Odwrotne rozpiętki na maszynie Pec Deck siedzącego odwrócone izolują tylną głowę naramienną i mięśnie równoległoboczne, kluczowe dla postawy i zdrowia barków.','Usiądź odwrócony do maszyny, twarzą do oparcia. Chwyć uchwyty z ramionami równoległymi do podłogi. Rozsuwaj ramiona w bok i do tyłu, napinając tylne naramienne na końcu ruchu. Powoli wróć.','Wzruszanie barkami zamiast cofania łopatki. Zbyt małe rozchodzenie ramion — brak zaangażowania tylnych naramiennych.','Cofaj aktywnie łopatki podczas ruchu — to angażuje i mięśnie równoległoboczne, i tylne naramienne jednocześnie.','Wydech podczas rozsuwania ramion, wdech podczas zbliżania.','Maszyna Pec Deck musi być odwrócona lub przestawiona do wersji reverse — sprawdź ustawienie przed ćwiczeniem.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Ciągnięcie','Poprzeczna','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,NULL,'Prosta','{"rear_delt": 0.8, "lateral_delt": 0.2}'::jsonb),(144,'Odwrotne rozpiętki z hantlami','odwrotne-rozpietki-z-hantlami','Barki',ARRAY['Plecy'],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Odwodzenie','Odwrotne rozpiętki z hantlami w pochyleniu lub na ławce izolują tylną głowę naramienną i mięśnie środkowych pleców.','Stań w pochyleniu z tułowiem prawie równoległym do podłogi (lub połóż się przodem na ławce skośnej). Chwyć hantle, ramiona zwisają prostopadle do podłogi. Unosić ramiona bocznym łukiem do poziomu pleców. Napnij tylne naramienne na szczycie i powoli opuść.','Prostowanie tułowia i używanie siły całego ciała. Zbyt duże ciężary ograniczają zakres ruchu.','Lekkość jest kluczem — tylne naramienne są małym mięśniem, użyj lżejszych hantli niż myślisz.','Wydech podczas unoszenia ramion, wdech podczas opuszczania.','Zadbaj o stabilną pozycję tułowia przez cały ruch — nie kiwaj się.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Poprzeczna','Obustronne','Hantle',false,'Z ostrożnością','Niskie',2,1,2,'Wysoki',true,NULL,'Umiarkowana','{"rear_delt": 0.7, "upper_back": 0.1, "lateral_delt": 0.2}'::jsonb),(145,'Odwrotne rozpiętki na linkach','odwrotne-rozpietki-na-linkach','Barki',ARRAY['Plecy'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Odwodzenie','Odwrotne rozpiętki na skrzyżowanych linkach wyciągu zapewniają stały opór w całym zakresie ruchu dla tylnych naramiennych.','Ustaw dwa wyciągi na przeciwległych stanowiskach na poziomie klatki lub niżej. Chwyć lewą linkę prawą ręką i prawą lewą ręką (skrzyżowane). Cofnij ramiona w tył i na boki, napinając tylne naramienne. Powoli powróć.','Zbyt mocne pochylanie tułowia, przez co ćwiczenie staje się wiosłowaniem. Brak skupienia na tylnych naramiennych.','Skrzyżowane linki utrzymują stały opór przez cały zakres ruchu — idealne do pracy w technice slow-tempo.','Wydech podczas rozchodzenia rąk, wdech podczas powrotu.','Unikaj zbyt dużego obciążenia — tylne naramienne są łatwe do przeciążenia.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Poprzeczna','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,2,'Wysoki',true,NULL,'Umiarkowana','{"rear_delt": 0.7, "upper_back": 0.1, "lateral_delt": 0.2}'::jsonb),(146,'Unoszenie hantli w przód','unoszenie-hantli-w-przod','Barki',ARRAY['Klatka piersiowa'],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Odwodzenie','Unoszenie hantli w przód (front raise) izoluje przednią głowę mięśnia naramiennego, zwykle wystarczająco stymulowaną przez ćwiczenia pchania, ale użyteczne jako akcent dodatkowy.','Stań z hantlami przed udami, dłonie ku dołowi. Unoś ramiona prosto przed siebie do wysokości barków, trzymając łokcie lekko ugięte. Zatrzymaj się na chwilę i powoli opuść.','Unoszenie ramion powyżej poziomu barków bez potrzeby. Zamach tułowia zamiast izolowanej pracy barku.','Przednie naramienne są często przetrenowane przez ćwiczenia pchania — stosuj to ćwiczenie ostrożnie i z umiarkowaną intensywnością.','Wydech podczas unoszenia, wdech podczas opuszczania.','Osoby z bólem przedniego barku lub kaletki powinny unikać lub ograniczyć to ćwiczenie.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',1,1,2,'Niski',true,NULL,'Prosta','{"rear_delt": 0.05, "front_delt": 0.8, "lateral_delt": 0.15}'::jsonb),(147,'Uginanie ramion ze sztangą','uginanie-ramion-ze-sztanga','Biceps',ARRAY['Przedramiona'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie łokcia','Uginanie ramion ze sztangą prostą to klasyczne ćwiczenie na bicepsy pozwalające na duże obciążenie obustronne dla efektywnej hipertrofii.','Stań z nogami na szerokość bioder, chwyć sztangę nachwytem na szerokość barków. Trzymając łokcie przy tułowiu, ugnij ramiona, unosząc sztangę ku barkom. Napnij bicepsy na szczycie i powoli opuść.','Odchylanie tułowia do tyłu i używanie zamachu bioder. Wysuwanie łokci do przodu podczas unoszenia.','Łokcie jako oś — tylko przedramię się porusza. Wyobraź sobie, że stoisz ze stopami przyciśniętymi do ściany za plecami.','Wydech podczas uginania, wdech podczas opuszczania.','Prosta sztanga może być niekomfortowa dla nadgarstków — w takim razie spróbuj sztangi EZ.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,NULL,'Prosta','{"biceps": 1}'::jsonb),(148,'Uginanie ramion ze sztangą EZ','uginanie-ramion-ze-sztanga-ez','Biceps',ARRAY['Przedramiona'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie łokcia','Uginanie ze sztangą EZ to ergonomiczna wersja curl ze sztangą, której zakrzywiony kształt zmniejsza napięcie nadgarstków i łokci przy podobnej stymulacji bicepsów.','Chwyć sztangę EZ w środkowych, ukośnych uchwytach. Łokcie przy tułowiu, ugnie ramiona do pełnego skurczu bicepsów. Powoli wyprostuj ramiona do pełnego wyprostu.','Zbyt wąski lub zbyt szeroki chwyt zmienia ergonomię ćwiczenia. Zamach tułowia przy cięższych seriach.','Pełny wyprost na dole jest ważny — rozciągnięcie mięśnia na końcach zakresu ruchu stymuluje wzrost mięśni.','Wydech podczas uginania, wdech podczas opuszczania.','EZ bar jest łagodniejszy dla nadgarstków niż prosta sztanga — dobry wybór dla osób z bólem nadgarstków.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,NULL,'Prosta','{"biceps": 1}'::jsonb),(149,'Uginanie ramion z hantlami','uginanie-ramion-z-hantlami','Biceps',ARRAY['Przedramiona'],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Zgięcie łokcia','Uginanie ramion z hantlami naprzemiennie lub obustronne to wszechstronne ćwiczenie na bicepsy dostępne zarówno w siłowni, jak i w domu.','Stań lub usiądź z hantlami wzdłuż tułowia, dłonie ku przodowi. Ugnij jedno lub oba ramiona, unosząc hantel ku barkom. Supinuj nadgarstek (obróć dłoń ku górze) podczas ruchu. Powoli opuść.','Brak supinacji nadgarstka ogranicza zaangażowanie bicepsa. Unoszenie łokci do przodu zamiast trzymania ich przy tułowiu.','Naprzemienne powtórzenia pozwalają skupić się na każdym ramieniu osobno i dają krótki odpoczynek między strony.','Wydech podczas uginania, wdech podczas opuszczania.','Hantle nie wymagają specjalnego sprzętu — można ćwiczyć w domu na krzesłe lub stojąc.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,NULL,'Prosta','{"biceps": 1}'::jsonb),(150,'Uginanie młotkowe z hantlami','uginanie-m-otkowe-z-hantlami','Biceps',ARRAY['Przedramiona'],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Zgięcie łokcia','Hammer curl z neutralnym chwytem (dłonie ku sobie) bardziej angażuje mięsień ramienny i ramienno-promieniowy niż klasyczny curl, budując szerokość ramienia.','Stań z hantlami wzdłuż tułowia, dłonie ku sobie (neutralny chwyt). Ugnij ramiona naprzemiennie lub obustronne, trzymając dłonie przez cały czas ku sobie — bez supinacji. Powoli opuść.','Rotacja nadgarstka w kierunku supinacji — to zmienia hammer w klasyczny curl. Zamach tułowia.','Neutralny chwyt przez cały ruch — dłoń ku sobie, jakbyś trzymał młotek.','Wydech podczas uginania, wdech podczas opuszczania.','Łagodne dla nadgarstków dzięki neutralnemu chwytowi — dobry wybór przy bólu nadgarstka.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,NULL,'Prosta','{"biceps": 0.65, "przedramiona": 0.35}'::jsonb),(151,'Uginanie ramion z hantlami na ławce skośnej','uginanie-ramion-z-hantlami-na-awce-skosnej','Biceps',ARRAY[]::text[],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Zgięcie łokcia','Uginanie na ławce skośnej (incline dumbbell curl) przesuwa stawem barkowym do tyłu, maksymalizując rozciągnięcie bicepsa na starcie — silny bodziec do hipertrofii.','Usiądź na ławce skośnej (45–60°), ramiona zwisają pionowo. Ugnij ramiona, supinując nadgarstki. Unikaj wysuwania łokci do przodu — muszą pozostać pod barkami przez cały ruch. Powoli opuść do pełnego wyprostu.','Wysuwanie łokci do przodu niweluje efekt rozciągnięcia na starcie. Skracanie zakresu ruchu na dole.','Pełne rozciągnięcie na dole ruchu to kluczowy bodziec tego ćwiczenia — nie pomijaj go przez pośpiech.','Wydech podczas uginania, wdech podczas opuszczania.','Nie używaj zbyt ciężkich hantli — rozciągnięty mięsień jest bardziej podatny na urazy.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',2,1,3,'Wysoki',true,NULL,'Umiarkowana','{"biceps": 1}'::jsonb),(152,'Uginanie ramion na modlitewniku','uginanie-ramion-na-modlitewniku','Biceps',ARRAY[]::text[],ARRAY['Sztanga','Hantle','Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie łokcia','Uginanie na modlitewniku (preacher curl) stabilizuje ramiona na specjalnej ławce, eliminując zamach i zmuszając bicepsy do całej pracy.','Oprzyj tylną część ramion o pochyłą powierzchnię modlitewnika, łokcie tuż przy górnej krawędzi. Chwyć sztangę EZ lub hantle. Ugnij ramiona w pełnym zakresie — od pełnego wyprostu do pełnego skurczu. Powoli wróć.','Odrywanie ramion od modlitewnika podczas unoszenia. Skracanie zakresu ruchu na dole — to eliminuje kluczową fazę.','Modlitewnik eliminuje zamach — to zmusza bicepsy do pracy przez cały ruch. Skup się na wolnym tempie ekscentrycznym.','Wydech podczas uginania, wdech podczas opuszczania.','Pełny wyprost na modlitewniku może powodować dyskomfort w łokciu — nie forsuj końcowego zakresu.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Niskie',2,1,2,'Wysoki',true,NULL,'Umiarkowana','{"biceps": 1}'::jsonb),(153,'Uginanie ramion na wyciągu','uginanie-ramion-na-wyciagu','Biceps',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie łokcia','Uginanie ramion na wyciągu dolnym zapewnia stały opór przez cały zakres ruchu, w tym w dolnej fazie gdzie hantle mają mniejszy opór ze względu na grawitację.','Stań przed wyciągiem dolnym, chwyć drążek lub linę podchwytem. Łokcie przy tułowiu, ugnij ramiona ku barkom. Napnij bicepsy na szczycie i powoli wróć do pełnego wyprostu.','Odsuwanie się od wyciągu, przez co lina ciągnie ramiona do przodu. Wzruszanie barkami.','Wyciąg zapewnia stały opór — możesz skupić się na wolnym tempie zarówno w górę, jak i w dół.','Wydech podczas uginania, wdech podczas opuszczania.','Ustaw wyciąg blisko siebie, by nie było naprężenia w nadgarstkach z powodu kąta linki.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,NULL,'Prosta','{"biceps": 1}'::jsonb),(154,'Prostowanie ramion z liną na wyciągu','prostowanie-ramion-z-lina-na-wyciagu','Triceps',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Wyprost łokcia','Prostowanie ramion z liną na wyciągu górnym (rope pushdown) to najpopularniejsze ćwiczenie izolowane na tricepsy, pozwalające na naturalną rotację nadgarstków.','Chwyć linę z wyciągu górnego, łokcie przy tułowiu. Wyprostuj ramiona, rozdzielając końce linki w dół i na zewnątrz. Napnij tricepsy na dole ruchu i powoli wróć.','Odrywanie łokci od tułowia i używanie całego ramienia jako dźwigni. Niepełny wyprost lub zbyt mały zakres ruchu.','Końce linki rozciągają się na zewnątrz na dole ruchu — to angażuje wszystkie trzy głowy tricepsa jednocześnie.','Wydech podczas prostowania ramion, wdech podczas powrotu.','Łokcie jako stały punkt — tylko przedramię się porusza.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,NULL,'Prosta','{"triceps": 1}'::jsonb),(155,'Prostowanie ramion z drążkiem na wyciągu','prostowanie-ramion-z-drazkiem-na-wyciagu','Triceps',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Wyprost łokcia','Prostowanie ramion z drążkiem (straight bar pushdown) pozwala na większe obciążenie tricepsów niż lina, dzięki stabilnemu uchwytowi.','Chwyć drążek nachwytem lub podchwytem z wyciągu górnego, łokcie przy tułowiu. Wyprostuj ramiona w pełnym zakresie ruchu. Powoli wróć do góry, kontrolując fazę ekscentryczną.','Zbyt szeroki chwyt ogranicza zakres ruchu. Odrywanie łokci od tułowia.','Podchwyt (dłonie ku górze) angażuje bardziej długą głowę tricepsa — spróbuj obu wariantów.','Wydech podczas prostowania, wdech podczas powrotu.','Prosta sztanga może być niekomfortowa dla nadgarstków przy dużym obciążeniu — w takim razie użyj linki.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',1,1,2,'Wysoki',true,NULL,'Prosta','{"triceps": 1}'::jsonb),(156,'Prostowanie ramion nad głową z liną','prostowanie-ramion-nad-g-owa-z-lina','Triceps',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Wyprost łokcia','Prostowanie ramion nad głową z liną na wyciągu dolnym rozciąga długą głowę tricepsa w pełnym zakresie, co jest szczególnie efektywne dla hipertrofii.','Odsuń się od wyciągu dolnego z liną trzymaną za głową. Uchwyć linkę oburącz, łokcie wysoko i blisko uszu. Wyprostuj ramiona w górę za głowę. Powoli wróć do rozciągnięcia.','Rozpadanie się łokci na boki zamiast pozostawania wysoko. Zbyt mały zakres ruchu na dole — linia musi zejść do tyłu głowy.','Długa głowa tricepsa przechodzi przez staw barkowy — pozycja nad głową maksymalizuje jej rozciągnięcie i napięcie.','Wydech podczas prostowania ramion, wdech podczas powrotu.','Nie przeprostowuj łokci gwałtownie pod dużym obciążeniem.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,2,'Wysoki',true,NULL,'Umiarkowana','{"triceps": 1}'::jsonb),(157,'Wyciskanie francuskie sztangą EZ','wyciskanie-francuskie-sztanga-ez','Triceps',ARRAY[]::text[],ARRAY['Sztanga','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Wyprost łokcia','Wyciskanie francuskie (skull crusher) ze sztangą EZ to zaawansowane ćwiczenie izolowane na tricepsy wykonywane w leżeniu, angażujące wszystkie trzy głowy z dużym rozciągnięciem.','Połóż się na ławce, chwyć sztangę EZ wąskim nachwytem. Trzymaj łokcie pionowo nad barkami. Opuść sztangę powoli za głowę lub do czoła, zginając tylko łokcie. Wyprostuj ramiona, napinając tricepsy.','Ruszanie łokciami do zewnątrz zamiast ich stabilizowania nad barkami. Zbyt duże obciążenie powoduje odchylenie łokci.','Łokcie jako nieruchomy punkt obrotu — ruch tylko w stawie łokciowym. Powolna faza ekscentryczna maksymalizuje efekt.','Wdech podczas opuszczania sztangi, wydech podczas wypychania.','Zachowaj kontrolę przez cały czas — jeśli tracisz stabilizację łokci, zmniejsz ciężar.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Średnie',3,2,3,'Wysoki',true,NULL,'Umiarkowana','{"triceps": 1}'::jsonb),(158,'Wyciskanie sztangi wąskim chwytem','wyciskanie-sztangi-waskim-chwytem','Triceps',ARRAY['Klatka piersiowa','Barki'],ARRAY['Sztanga','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie poziome','Wyciskanie wąskim chwytem to złożone ćwiczenie angażujące tricepsy jako główny motor napędowy, z udziałem klatki piersiowej i przednich naramiennych.','Połóż się na ławce, chwyć sztangę na szerokość barków lub nieco węziej. Opuść sztangę ku dolnej klatce piersiowej, utrzymując łokcie blisko tułowia. Wyciśnij do góry, koncentrując się na pracy tricepsów.','Zbyt wąski chwyt (węższy niż barki) powoduje dyskomfort w nadgarstkach. Rozchodzenie się łokci na boki.','W porównaniu do zwykłego wyciskania, chwyt wąski przesuwa większe napięcie na tricepsy i mniejsze na klatkę.','Wdech podczas opuszczania, wydech podczas wyciskania.','Miej asekuranta lub bezpieczniki przy cięższych seriach.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Sztanga',true,'Z ostrożnością','Średnie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"klatka": 0.3, "triceps": 0.7}'::jsonb),(159,'Dead bug','dead-bug','Brzuch',ARRAY[]::text[],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Anti-ekstensja','Dead bug to fundamentalne ćwiczenie core w leżeniu, trenujące anti-ekstensję i stabilizację lędźwi przy naprzemiennych ruchach kończyn.','Połóż się na plecach, ramiona pionowo nad barkami, kolana ugięte pod kątem 90° nad biodrami. Napnij core i dociśnij lędźwie do podłogi. Jednocześnie opuść prawą rękę za głowę i lewą nogę ku podłodze, wróć i zmień strony.','Odrywanie lędźwi od podłogi — kluczowy błąd niwelujący sens ćwiczenia. Zbyt szybkie tempo bez kontroli.','Lędźwie muszą przez cały czas przylegać do podłogi — to jest warunek konieczny. Zacznij od małego zakresu ruchu kończyn.','Wydech podczas opuszczania kończyn (to pomaga aktywować TVA), wdech podczas powrotu.','Bezpieczne ćwiczenie dla większości osób, w tym kobiet w ciąży (pierwsze trymestry) i po rehabilitacji pleców.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Core','Strzałkowa','Obustronne','Masa własnego ciała',false,'Tak','Niskie',1,1,1,'Wysoki',true,true,'Prosta','{"brzuch": 1}'::jsonb),(160,'Bird dog','bird-dog','Brzuch',ARRAY['Plecy'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Stabilizacja tułowia','Bird dog to naprzemienne ćwiczenie stabilizacyjne na czworakach, trenujące kontrolę lędźwiowo-miedniczną i aktywację głębokich mięśni core.','Przyjmij pozycję na czworakach — dłonie pod barkami, kolana pod biodrami. Napnij core. Jednocześnie wysuń prawą rękę przed siebie i lewą nogę za siebie, tworząc prostą linię. Wróć i zmień strony.','Rotacja miednicy podczas wyciągania nogi. Unoszenie ręki lub nogi powyżej linii kręgosłupa.','Wyobraź sobie szklankę wody stojącą na dolnych plecach — nie rozlewaj jej podczas ruchu.','Wydech podczas wyciągania kończyn, wdech podczas powrotu.','Idealne ćwiczenie prewencyjne i rehabilitacyjne dla dolnego odcinka pleców.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Core','Strzałkowa','Jednostronne','Masa własnego ciała',false,'Tak','Niskie',1,1,1,'Wysoki',true,true,'Prosta','{"brzuch": 1}'::jsonb),(161,'Plank boczny','plank-boczny','Brzuch',ARRAY[]::text[],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Stabilizacja tułowia','Plank boczny trenuje mięśnie skośne brzucha i boczne stabilizatory tułowia przez statyczne utrzymanie ciała w bocznym podparciu.','Połóż się na boku, oprzyj się na przedramieniu i bocznej krawędzi stopy. Unieś biodra tak, by ciało tworzyło prostą linię od głowy do stóp. Napnij skośne i utrzymaj pozycję przez wyznaczony czas.','Opadanie bioder ku podłodze. Rotacja miednicy do przodu lub do tyłu.','Wypchnij biodra lekko do góry ponad poziom prostej linii — zwiększa to zaangażowanie bocznych mięśni core.','Spokojne, kontrolowane oddychanie przez cały czas utrzymania pozycji.','Zacznij od krótszych interwałów (15–30 s) i stopniowo wydłużaj czas. Kolana na podłodze dla łatwiejszej wersji.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Core','Czołowa','Jednostronne','Masa własnego ciała',false,'Tak','Niskie',1,1,1,'Wysoki',true,true,'Prosta','{"brzuch": 1}'::jsonb),(162,'Pallof press','pallof-press','Brzuch',ARRAY[]::text[],ARRAY['Wyciąg','Gumy oporowe'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Anti-rotacja','Pallof press to anty-rotacyjne ćwiczenie core z wyciągiem lub gumą oporową, trenujące zdolność tułowia do opierania się siłom rotacyjnym.','Stań bokiem do wyciągu lub punktu kotwiczenia gumy. Chwyć linkę oburącz przed klatką. Wyciśnij ramiona prosto przed siebie, nie pozwalając, by ciało się obróciło. Utrzymaj 1–3 sekundy i wróć. Zmień strony.','Rotacja tułowia podczas prostowania ramion — to właśnie ma się nie zdarzać. Zbyt duży opór na początku.','Kotwica wyciągu powinna być na poziomie klatki lub niżej. Im szersza stopa, tym łatwiejsze ćwiczenie.','Wydech podczas prostowania ramion, wdech podczas powrotu.','Idealne ćwiczenie prewencyjne dla sportowców i rehabilitacyjne dla dolnych pleców.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Core','Poprzeczna','Obustronne','Wyciąg',false,'Tak','Niskie',2,1,1,'Wysoki',true,true,'Prosta','{"brzuch": 1}'::jsonb) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,main_muscle_group=EXCLUDED.main_muscle_group,secondary_muscle_groups=EXCLUDED.secondary_muscle_groups,equipment=EXCLUDED.equipment,training_location=EXCLUDED.training_location,difficulty_level=EXCLUDED.difficulty_level,movement_pattern=EXCLUDED.movement_pattern,exercise_type=EXCLUDED.exercise_type,suitable_experience_levels=EXCLUDED.suitable_experience_levels,training_goals=EXCLUDED.training_goals,movement_category=EXCLUDED.movement_category,is_active=EXCLUDED.is_active,exercise_priority=EXCLUDED.exercise_priority,sub_target_biases=EXCLUDED.sub_target_biases`;

const SQL_EXERCISES_2 = `INSERT INTO exercises (id,name,slug,main_muscle_group,secondary_muscle_groups,equipment,equipment_other,training_location,difficulty_level,movement_pattern,description,execution_instructions,common_mistakes,coaching_tips,breathing_tips,safety_notes,exercise_type,suitable_experience_levels,training_goals,movement_category,plane_of_motion,execution,resistance_type,requires_spotter,can_be_performed_to_failure,joint_stress,learning_difficulty,neurological_fatigue,doms_potential,exercise_priority,is_active,suitable_for_no_activity,movement_complexity,sub_target_biases) VALUES (163,'Spięcia brzucha na wyciągu','spiecia-brzucha-na-wyciagu','Brzuch',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie tułowia','Spięcia brzucha na wyciągu górnym to ćwiczenie na mięsień prosty brzucha z regulowanym obciążeniem, skuteczniejsze niż spięcia z masą ciała przy silniejszym core.','Uklęknij przed wyciągiem górnym z liną trzymaną przy głowie. Zaokrągl tułów ku dołowi, przybliżając łokcie do kolan. Napnij mięsień prosty na dole ruchu i powoli wróć do pionowej pozycji.','Ciągnięcie linki siłą ramion zamiast pracą mięśnia prostego. Zbyt małe zaokrąglenie tułowia.','Wyobraź sobie, że chcesz dotknąć nosem do pępka — to angażuje mięsień prosty przez pełen zakres.','Wydech podczas zaokrąglania i napięcia, wdech podczas powrotu.','Klęcz na miękkiej macie. Reguluj ciężar na wyciągu stopniowo.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Core','Strzałkowa','Obustronne','Wyciąg',false,'Z ostrożnością','Niskie',2,2,2,'Średni',true,NULL,'Umiarkowana',NULL),(164,'Odwrotne spięcia brzucha','odwrotne-spiecia-brzucha','Brzuch',ARRAY[]::text[],ARRAY['Masa własnego ciała','Ławka'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Zgięcie tułowia','Odwrotne spięcia brzucha to ćwiczenie na dolną część mięśnia prostego, w którym biodra są unoszone zamiast tułowia.','Połóż się na plecach, dłonie przy biodrach dla podparcia. Ugnij kolana i unieś je ku klatce, zaokrąglając dolny odcinek lędźwiowy. Miednica unosi się lekko od podłogi na szczycie. Powoli opuść.','Używanie zamachu nóg zamiast pracy mięśnia prostego. Zbyt szybkie opuszczanie na dół.','Skup się na tym, żeby miednica się skręcała ku górze, a nie tylko nogi unosiły się — to jest sedno ćwiczenia.','Wydech podczas unoszenia nóg i miednicy, wdech podczas opuszczania.','Jeśli czujesz napięcie w dolnych plecach, zmniejsz zakres ruchu lub trzymaj nogi bardziej ugięte.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Core','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',2,1,2,'Średni',true,NULL,'Umiarkowana',NULL),(165,'Unoszenie kolan w zwisie','unoszenie-kolan-w-zwisie','Brzuch',ARRAY[]::text[],ARRAY['Drążek','Poręcze'],NULL,ARRAY['Siłownia','Plener'],'Średniozaawansowany','Zgięcie tułowia','Unoszenie kolan w zwisie to wymagające ćwiczenie core w podwieszeniu, angażujące mięsień prosty brzucha z dużym obciążeniem grawitacyjnym.','Zawis na drążku lub poręczach. Napnij core i unieś kolana ku klatce, zaokrąglając dolny odcinek grzbietu. Unikaj bujania. Powoli opuść nogi do pełnego zwisu.','Bujanie ciałem i używanie zamachu. Zbyt szybkie opuszczanie bez kontroli ekscentrycznej.','Dla zwiększenia trudności trzymaj nogi proste. Dla zmniejszenia trudności ugnij kolana mocniej.','Wydech podczas unoszenia kolan, wdech podczas opuszczania.','Wymaga odpowiedniej siły chwytu — ogranicz czas zwisu do bezpiecznego. Stosuj paski do nadgarstków jeśli potrzeba.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Core','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',2,2,3,'Wysoki',true,NULL,'Umiarkowana','{"brzuch": 1}'::jsonb),(166,'Ab wheel rollout','ab-wheel-rollout','Brzuch',ARRAY['Plecy','Barki'],ARRAY['Inny'],'Kółko',ARRAY['Siłownia','Dom'],'Zaawansowany','Anti-ekstensja','Ab wheel rollout to zaawansowane ćwiczenie anti-ekstensji na głęboki core, wymagające wysokiej siły mięśnia poprzecznego brzucha i prostowników grzbietu.','Uklęknij za ab wheel, dłonie na uchwytach. Powoli toczysz koło do przodu, utrzymując lędźwie napięte i nie pozwalając im opaść. Zasięg jest ograniczony zdolnością do utrzymania stabilizacji lędźwiowej. Wróć do pozycji wyjściowej.','Zbyt daleki zasięg do przodu i opadanie lędźwi — ryzyko urazu. Zbyt szybki powrót bez kontroli.','Zacznij od małego zasięgu i wydłużaj go z tygodnia na tydzień. To ćwiczenie wymaga długiego okresu budowania.','Wydech podczas toczenia do przodu, wdech podczas powrotu.','Nie dla osób z bólem dolnych pleców lub słabym core. Zawsze zacznij od klęcznej wersji z małym zasięgiem.','Izolowane',ARRAY['Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Core','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Wysokie',4,4,4,'Wysoki',true,false,'Złożona','{"brzuch": 1}'::jsonb),(167,'Spacer farmera','spacer-farmera','Całe ciało',ARRAY['Plecy','Brzuch','Przedramiona'],ARRAY['Hantle','Kettlebell'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Lokomocja','Spacer farmera to ćwiczenie nośne angażujące całe ciało — core, pułapki, prostowniki grzbietu, mięśnie nóg i chwytu — przez utrzymanie ciężaru podczas chodu.','Podnieś hantle lub kettlebells z podłogi z prostymi plecami. Stań prosto, ramiona wzdłuż tułowia. Idź równym krokiem, utrzymując pionową postawę i napięty core. Po wyznaczonym dystansie odłóż ciężary kontrolowanie.','Opadanie ramion i zaokrąglanie górnych pleców. Zbyt krótkie kroki ograniczają ćwiczenie.','Cofaj aktywnie ramiona, by ''napinać'' pułapki — to chroni barki i plecy. Wzrok skierowany przed siebie.','Spokojne, równomierne oddychanie przez cały dystans.','Zacznij od lekkiego ciężaru i skup się na utrzymaniu pionowej postawy przez cały dystans.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Siła'],'Dźwiganie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',1,2,2,'Wysoki',true,true,'Prosta','{"plecy": 0.4, "brzuch": 0.3, "przedramiona": 0.3}'::jsonb),(168,'Spacer walizkowy','spacer-walizkowy','Całe ciało',ARRAY['Brzuch'],ARRAY['Hantle','Kettlebell'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Lokomocja','Spacer walizkowy (suitcase carry) to jednostronne niosące ćwiczenie trenujące boczne stabilizatory core, przeciwdziałające bocznemu opadaniu miednicy pod asymetrycznym ciężarem.','Podnieś hantel lub kettlebell jedną ręką z podłogi. Stań prosto, ramię z ciężarem swobodnie zwisa. Idź równym krokiem, utrzymując miednicę poziomą i tułów pionowy — opieraj się sile ciągnącej cię na bok. Po dystansie zmień rękę.','Pochylanie tułowia w stronę ciężaru. Unoszenie ramienia z ciężarem zamiast pozwolenia mu zwisać naturalnie.','Miednica musi być pozioma przez cały dystans — kontroluj to patrząc w lustro lub prosząc trenera o obserwację.','Spokojne, regularne oddychanie przez cały czas niesienia.','Zacznij od lekkiego ciężaru — asymetryczne obciążenie wymaga dobrej propriocepcji.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Dźwiganie','Czołowa','Jednostronne','Hantle',false,'Z ostrożnością','Niskie',2,2,1,'Wysoki',true,true,'Prosta','{"plecy": 0.3, "brzuch": 0.5, "przedramiona": 0.2}'::jsonb),(169,'Bear crawl','bear-crawl','Całe ciało',ARRAY['Brzuch','Klatka piersiowa'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Lokomocja','Bear crawl to lokomocyjne ćwiczenie core i całego ciała, w którym poruszasz się na czworakach z kolanami unoszonymi tuż nad podłogą.','Przyjmij pozycję na czworakach, kolana kilka centymetrów nad podłogą. Poruszaj naprzemiennie prawą ręką i lewą nogą, następnie lewą i prawą. Utrzymuj plecy płaskie i kolana nisko przez cały czas. Idź do przodu lub do tyłu.','Opadanie bioder i utrata napięcia core. Zbyt wysokie kolana nad podłogą.','Wolniejszy ruch = większe zaangażowanie stabilizatorów. Zacznij powoli, zwracając uwagę na naprzemienny wzorzec ruchu.','Równomierne oddychanie przez cały czas wykonywania ćwiczenia.','Ćwicz na miękkiej macie lub trawiastej powierzchni, by chronić nadgarstki i kolana.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Core','Strzałkowa','Obustronne','Masa własnego ciała',false,'Tak','Niskie',2,2,1,'Wysoki',true,NULL,'Umiarkowana','{"barki": 0.3, "plecy": 0.2, "brzuch": 0.5}'::jsonb),(170,'Wyciskanie hantli leżąc','wyciskanie-hantli-lezac','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie poziome','Wyciskanie hantli leżąc na płaskiej ławce to klasyczne ćwiczenie wielostawowe na klatkę piersiową, dające większy zakres ruchu i lepsze rozciągnięcie mięśnia piersiowego niż wersja ze sztangą. Hantle pozwalają każdej ręce pracować niezależnie, wyrównując asymetrię siłową.','Usiądź na ławce, kładąc hantle na udach. Odchyl się do tyłu, unosząc hantle do pozycji startowej — dłonie skierowane ku przodowi, hantle na poziomie klatki piersiowej, łokcie pod kątem ok. 60–75° do tułowia. Wyciśnij hantle ku górze i lekko do środka, nie łącząc ich w górze. Powoli opuść do pełnego rozciągnięcia klatki.','Zbyt szerokie ustawienie łokci (90° do tułowia) nadmiernie obciąża bark. Odbijanie hantli od klatki piersiowej skraca zakres ruchu. Nadmierne łączenie hantli na górze blokuje napięcie mięśniowe.','Wyobraź sobie, że obejmujesz baryłkę — łuki łokci lekko ku klatce zachowają napięcie w mięśniu piersiowym przez cały ruch. Czuj rozciągnięcie w dolnym punkcie.','Wdech podczas opuszczania hantli, wydech podczas wyciskania.','Przy dużych ciężarach poproś o pomoc przy ustawieniu hantli lub użyj specjalnego sprzętu do podawania hantli. Kontroluj ruch powrotny, by nie stracić grips na ciężarze.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Hantle',false,'Z ostrożnością','Średnie',2,3,3,'Wysoki',true,NULL,'Umiarkowana','{"mid_chest": 0.6, "lower_chest": 0.2, "upper_chest": 0.2}'::jsonb),(171,'Wyciskanie sztangi na ławce skośnej ujemnej','wyciskanie-sztangi-na-awce-skosnej-ujemnej','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Sztanga','Ławka'],NULL,ARRAY['Siłownia'],'Zaawansowany','Pchanie poziome','Wyciskanie sztangi na ławce skośnej ujemnej (decline) akcentuje dolną i środkową część klatki piersiowej poprzez kąt nachylenia ławki ok. 20–30° w dół. Angażuje dolne włókna mostkowo-żebrowe mięśnia piersiowego większego.','Ustaw ławkę pod kątem ok. 20–30° w dół. Przytwierdź nogi do podpórek. Chwyć sztangę nachwytem nieco szerzej niż szerokość barków. Opuść sztangę do dolnej klatki piersiowej, utrzymując łokcie pod kątem 45–75°. Wyciśnij do góry bez blokowania łokci.','Zbyt duże nachylenie (ponad 30°) przenosi zbyt wiele napięcia na triceps. Podnoszenie głowy lub tyłka z ławki podczas wyciskania. Zbyt szybkie opuszczanie sztangi.','Ćwiczenie jest stosunkowo niedoceniane — pozwala na większe obciążenie niż bench płaski przy mniejszym zaangażowaniu stabilizatorów barku. Skupiaj uwagę na dolnych włóknach klatki.','Wdech podczas opuszczania sztangi, wydech podczas wyciskania.','Zawsze używaj asekuranta lub specjalnych bezpieczników przy powadze ciężaru. Logistyka opuszczania się na ławce wymaga uwagi — najpierw usiądź, potem połóż się.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Sztanga',true,'Z ostrożnością','Średnie',3,3,3,'Średni',true,NULL,'Umiarkowana','{"mid_chest": 0.3, "lower_chest": 0.6, "upper_chest": 0.1}'::jsonb),(172,'Wyciskanie hantli na ławce skośnej ujemnej','wyciskanie-hantli-na-awce-skosnej-ujemnej','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie poziome','Wyciskanie hantli na ławce skośnej ujemnej angażuje dolną część klatki piersiowej, jednocześnie oferując większy zakres ruchu niż wersja ze sztangą. Niezależna praca każdej ręki poprawia balans siłowy.','Ustaw ławkę pod kątem ok. 20–30° w dół. Przytwierdź nogi. Usiądź z hantlami na kolanach, a następnie połóż się, unosząc hantle do pozycji startowej na poziomie dolnej klatki. Wyciśnij ku górze i lekko do środka. Powoli opuść do pełnego rozciągnięcia.','Zbyt ciężki ciężar utrudniający kontrolę w pozycji decline. Odrywanie nóg od podpórek podczas ćwiczenia.','Lżejsze ciężary niż przy wersji ze sztangą — koncentruj się na czuciu mięśniowym i zakresie ruchu, nie na maksymalnym obciążeniu.','Wdech podczas opuszczania hantli, wydech podczas wyciskania.','Ostrożnie przy wstawaniu — poczekaj chwilę przed podniesieniem się, by uniknąć zawrotów głowy z powodu zmiany pozycji ciała.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Hantle',false,'Z ostrożnością','Średnie',3,2,3,'Średni',true,NULL,'Umiarkowana','{"mid_chest": 0.3, "lower_chest": 0.6, "upper_chest": 0.1}'::jsonb),(173,'Wyciskanie na suwnicy Smitha leżąc','wyciskanie-na-suwnicy-smitha-lezac','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Maszyna','Ławka'],NULL,ARRAY['Siłownia'],'Początkujący','Pchanie poziome','Wyciskanie na suwnicy Smitha w pozycji leżącej to prowadzona wersja wyciskania sztangi, w której prowadnica maszyny stabilizuje tor ruchu. Pozwala na bezpieczniejszy trening bez asekuranta i łatwiejsze skupienie się na klatce piersiowej.','Ustaw ławkę płaską pod suwnicy Smitha tak, by sztanga znajdowała się nad klatką piersiową. Połóż się i chwyć sztangę nachwytem nieco szerzej niż barki. Odblokuj sztangę obrotem. Opuść do klatki piersiowej, utrzymując łokcie pod kątem ok. 60°. Wyciśnij do góry i zablokuj obrotem po zakończeniu serii.','Ustawienie ławki za daleko do przodu lub za tyłu zmienia kąt pracy klatki. Brak odblokowywania zatrzasku bezpieczeństwa przed każdą serią.','Suwnica Smitha ogranicza naturalny tor ruchu — ustaw się tak, by sztanga opuszczała się pionowo na środkową klatkę. Cofnij łopatki, by chronić bark.','Wdech podczas opuszczania, wydech podczas wyciskania.','Nawet bez asekuranta zachowaj ostrożność — zawsze miej dostęp do zatrzasków bezpieczeństwa w zasięgu rąk podczas serii.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',2,2,3,'Średni',true,NULL,'Umiarkowana','{"mid_chest": 0.6, "lower_chest": 0.2, "upper_chest": 0.2}'::jsonb),(174,'Pompki z obciążeniem','pompki-z-obciazeniem','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Masa własnego ciała','Hantle'],NULL,ARRAY['Siłownia','Dom'],'Średniozaawansowany','Pchanie poziome','Pompki z obciążeniem to progresja pompek klasycznych z dodatkowym ciężarem (talerz lub kamizelka obciążeniowa ułożone na plecach), umożliwiająca zwiększenie oporu w ćwiczeniu z masą własnego ciała. Idealny most między pompkami a wyciskaniem leżąc.','Przyjmij pozycję pompek klasycznych. Umieść talerz wagowy lub hantla pionowo na środku pleców (poproś partnera lub użyj kamizelki obciążeniowej). Utrzymuj napięte core. Wykonaj pompkę pełnym zakresem ruchu, dbając o prostą linię ciała.','Opadanie miednicy pod ciężarem dodatkowego obciążenia. Zbyt krótki zakres ruchu gdy ciężar jest duży. Nieodpowiednie mocowanie talerza powodujące jego zsuwanie.','Zacznij od lekkiego talerza (5–10 kg) i stopniowo zwiększaj. Kamizelka obciążeniowa jest bezpieczniejsza niż luźny talerz na plecach.','Wdech podczas opuszczania, wydech podczas wypychania.','Przy użyciu luźnego talerza zawsze poproś partnera o pomoc w ustawieniu i zdjęciu go. Nie używaj zbyt dużych obciążeń, które destabilizują postawę.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',2,2,2,'Średni',true,NULL,'Umiarkowana','{"mid_chest": 0.55, "lower_chest": 0.25, "upper_chest": 0.2}'::jsonb),(175,'Dipy na poręczach','dipy-na-poreczach','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Poręcze'],NULL,ARRAY['Siłownia','Plener'],'Średniozaawansowany','Pchanie poziome','Dipy na poręczach z pochylonym tułowiem to jedno z najskuteczniejszych ćwiczeń na dolną i środkową klatkę piersiową. Pochylenie tułowia ok. 20–30° do przodu przenosi ciężar pracy z tricepsów na mięsień piersiowy. Ćwiczenie wielostawowe z masą własnego ciała.','Chwyć poręcze i unieś się do pozycji wyprostowanej. Pochyl tułów ok. 20–30° do przodu i delikatnie ugnij kolana z nogami skrzyżowanymi z tyłu. Zgięj łokcie i opuść ciało, dopóki ramię górne nie będzie równoległe do podłoża lub niżej. Wypchnij się do pozycji wyjściowej bez blokowania łokci.','Pionowy tułów (jak przy dipach tricepsowych) przenosi napięcie z klatki na triceps. Zbyt głębokie opuszczenie przy słabej mobilności barku zwiększa ryzyko urazu. Kołysanie i zamach nogami.','Im bardziej pochylasz tułów, tym więcej pracuje klatka. Jeśli celem jest klatka, skupiaj się na rozciągnięciu mięśnia piersiowego w dolnym punkcie ruchu.','Wdech podczas opuszczania, wydech podczas wypychania.','Dipy są wymagające dla stawu barkowego — unikaj ćwiczenia, jeśli masz problemy z barkami. Nie przeciągaj zakresu ruchu poniżej komfortowego dla Twojego barku.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Wysokie',3,3,3,'Wysoki',true,NULL,'Umiarkowana','{"mid_chest": 0.3, "lower_chest": 0.6, "upper_chest": 0.1}'::jsonb),(176,'Dipy wspomagane na maszynie','dipy-wspomagane-na-maszynie','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Pchanie poziome','Dipy wspomagane na maszynie to bezpieczna wersja dipów z kontrciężarem odciążającym część masy ciała. Idealne ćwiczenie przejściowe do dipów z pełną masą ciała, dostępne dla osób które nie są jeszcze w stanie wykonać dipów klasycznych.','Ustaw kontrciężar na maszynie — im większy, tym łatwiejsze ćwiczenie. Wklęknij lub postaw stopy na platformie (zależnie od modelu maszyny). Pochyl tułów lekko do przodu, by zaakcentować klatkę. Opuść do momentu, gdy ramię górne będzie równoległe do podłoża. Wypchnij się do góry.','Zbyt mały kontrciężar zanim osoba ma siłę do dipów. Pionowa sylwetka, która przenosi pracę na triceps zamiast klatki.','Stopniowo zmniejszaj kontrciężar co kilka tygodni, dążąc do dipów z masą własnego ciała. Zawsze pochylaj tułów do przodu dla pracy klatki.','Wdech podczas opuszczania, wydech podczas wypychania.','Sprawdź, czy kontrciężar jest właściwie ustawiony przed wykonaniem pierwszego powtórzenia. Maszyna wspomagająca daje fałszywe poczucie bezpieczeństwa — kontroluj zakres ruchu.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Pchanie','Poprzeczna','Obustronne','Maszyna',false,'Z ostrożnością','Niskie',1,2,2,'Średni',true,NULL,'Prosta','{"mid_chest": 0.3, "lower_chest": 0.6, "upper_chest": 0.1}'::jsonb),(177,'Svend Press','svend-press','Klatka piersiowa',ARRAY['Barki'],ARRAY['Inny'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Przywodzenie','Svend Press to ćwiczenie izolowane na klatkę piersiową, polegające na wyciskaniu talerza (lub dwóch talerzy) trzymanego dłońmi i wyciskaniu go przed siebie przy jednoczesnym aktywnym ściskaniu. Wymuszony izometryczny skurcz mięśnia piersiowego czyni go wyjątkowym uzupełnieniem treningu klatki.','Stań swobodnie lub usiądź. Chwyć talerz wagowy oburącz, ściskając go dłońmi z obu stron. Trzymaj talerz przy środkowej klatce piersiowej. Wyciśnij go przed siebie, utrzymując ciągłe napięcie i ścisk dłonią przez cały czas trwania ruchu. Powoli wróć do klatki.','Zaprzestanie ściskania talerza w połowie ruchu, co eliminuje korzyść izolowania klatki. Unoszenie ramion do uszu podczas ćwiczenia.','Cały sens ćwiczenia tkwi w nieprzerwanym ściskaniu talerza — wyobraź sobie, że próbujesz go zgnieść. Lekki ciężar (2–5 kg) w zupełności wystarczy.','Wydech podczas wypychania talerza przed siebie, wdech podczas powrotu.','Używaj małych, kompaktowych talerzy, które łatwo chwycić. Unikaj zbyt ciężkich talerzy — ćwiczenie jest skuteczne przy lekkim obciążeniu.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Inny',false,'Tak','Niskie',1,1,2,'Niski',true,NULL,'Prosta','{"mid_chest": 0.65, "lower_chest": 0.15, "upper_chest": 0.2}'::jsonb),(178,'Rozpiętki z hantlami leżąc','rozpietki-z-hantlami-lezac','Klatka piersiowa',ARRAY['Barki'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przywodzenie','Rozpiętki z hantlami leżąc na płaskiej ławce to klasyczne ćwiczenie izolowane na klatkę piersiową, zapewniające duży zakres ruchu i głębokie rozciągnięcie mięśnia piersiowego. Inaczej niż w prasach, ruch jest łukowy — hantle poruszają się po torze koła.','Połóż się na płaskiej ławce, trzymając hantle nad klatką z dłońmi skierowanymi ku sobie, łokcie lekko ugięte. Opuść hantle na boki po łuku, opuszczając je do poziomu klatki piersiowej lub nieco niżej. Wyobraź sobie, że obejmujesz baryłkę i przyciągnij hantle z powrotem do góry tym samym łukiem.','Prostowanie łokci i zamienianie ćwiczenia w wyciskanie. Zbyt ciężki ciężar powodujący utratę kontroli na dole ruchu i przeciążenie barku. Zbyt małe rozciągnięcie skraca zakresy pracy klatki.','Utrzymuj łokcie stale lekko ugięte — nie prostuj ich ani nie zginaj bardziej niż na starcie. Czuj rozciągnięcie w klatce na dole, a skurcz na górze.','Wdech podczas opuszczania hantli na boki, wydech podczas powrotu ku górze.','Mięsień piersiowy jest bardzo narażony na naciągnięcie przy zbyt głębokim rozpiętku z dużym ciężarem. Trzymaj obciążenie umiarkowane i kontroluj każde powtórzenie.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Hantle',false,'Z ostrożnością','Średnie',2,2,3,'Średni',true,NULL,'Umiarkowana','{"mid_chest": 0.6, "lower_chest": 0.15, "upper_chest": 0.25}'::jsonb),(179,'Rozpiętki z hantlami na ławce skośnej','rozpietki-z-hantlami-na-awce-skosnej','Klatka piersiowa',ARRAY['Barki'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przywodzenie','Rozpiętki z hantlami na ławce skośnej dodatniej akcentują górną część klatki piersiowej (włókna obojczykowe mięśnia piersiowego większego) przez zmianę kąta pracy. To uzupełnienie rozpiętki płaskiej dla pełnego rozwinięcia klatki.','Ustaw ławkę pod kątem 30–45°. Połóż się trzymając hantle nad klatką z dłońmi ku sobie, łokcie lekko ugięte. Opuść hantle na boki po łuku, opuszczając do poziomu klatki lub nieco niżej. Wróć łukiem do góry, skupiając napięcie na górnej klatce.','Zbyt duże nachylenie ławki (ponad 45°) przenosi zbyt wiele pracy na barki. Prostowanie łokci i zamiana w ćwiczenie wyciskaniowe. Zbyt ciężkie hantle utrudniające kontrolę.','Kąt 30° daje najlepszy balans między górną klatką a barkami. Przy 45° barki przejmują coraz więcej pracy — sprawdzaj subiektywne czucie mięśniowe.','Wdech podczas opuszczania hantli na boki, wydech podczas powrotu.','Mięsień piersiowy (szczególnie przyczepi) jest podatny na naciągnięcia przy rozpiętce. Zachowaj umiarkowany ciężar i pełną kontrolę.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Hantle',false,'Z ostrożnością','Średnie',2,2,3,'Niski',true,NULL,'Umiarkowana','{"mid_chest": 0.3, "lower_chest": 0.1, "upper_chest": 0.6}'::jsonb),(180,'Wiosłowanie sztangą w opadzie','wios-owanie-sztanga-w-opadzie','Plecy',ARRAY['Biceps','Barki'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przyciąganie poziome','Wiosłowanie sztangą w opadzie (bent-over barbell row) to jedno z najważniejszych ćwiczeń na masę pleców, angażujące szeroko mięsień najszerszy grzbietu, równoległoboczne i bicepsy w ruchu horyzontalnym.','Stań z nogami na szerokość bioder, chwyć sztangę nachwytem nieco szerzej niż barki. Pochyl tułów do kąta 45–60° przy zachowaniu prostych pleców. Ciągnij sztangę ku dolnej klatce/pępkowi, prowadząc łokcie blisko tułowia wzdłuż boków. Napnij łopatki na górze i powoli opuść.','Zaokrąglanie dolnego odcinka kręgosłupa pod obciążeniem. Używanie zamachu bioder lub tułowia. Ciągnięcie sztangi ku górnej klatce zamiast ku pępkowi.','Wyobraź sobie, że ściskasz ołówek między łopatkami na końcu ruchu. Tułów możesz lekko wyprostować przy ciężkich seriach, ale nie więcej niż do 20° zamachu.','Wdech przed opuszczeniem sztangi, wydech podczas ciągnienia.','Nigdy nie zaokrąglaj dolnych pleców pod ciężarem. Rozgrzej kręgosłup przed ciężkimi seriami.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Wysokie',3,3,4,'Wysoki',true,NULL,'Umiarkowana','{"lats": 0.3, "upper_back": 0.7}'::jsonb),(181,'Wiosłowanie podchwytem ze sztangą','wios-owanie-podchwytem-ze-sztanga','Plecy',ARRAY['Biceps'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przyciąganie poziome','Wiosłowanie podchwytem (supinated-grip row) to wariant wiosłowania w opadzie, w którym odwrócony chwyt silniej angażuje bicepsy i dolną część mięśnia czworobocznego przy jednoczesnej pracy całego grzbietu.','Pochyl tułów do 45°, chwyć sztangę podchwytem (dłonie skierowane ku górze) na szerokość barków. Ciągnij ku dolnej klatce, trzymając łokcie blisko tułowia. Napnij plecy na szczycie i powoli opuść sztangę.','Zbyt pionowa postawa zmienia ćwiczenie w deadlift-shrug. Zamach tułowia przy każdym powtórzeniu.','Podchwyt zwiększa zakres ruchu na górze i lepiej angażuje dolny czworoboczny — dobry wybór dla poprawy symetrii pleców.','Wdech w dole, wydech podczas ciągnienia.','Przy bólu nadgarstków korzystaj z podchwytu tylko do poziomego ustawienia przedramienia.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Wysokie',3,3,4,'Wysoki',true,NULL,'Umiarkowana','{"lats": 0.4, "upper_back": 0.6}'::jsonb),(182,'Martwy ciąg konwencjonalny','martwy-ciag-konwencjonalny','Plecy',ARRAY['Pośladki','Mięśnie dwugłowe uda','Mięśnie czworogłowe uda'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Zaawansowany','Zawias biodrowy','Martwy ciąg konwencjonalny to fundamentalne ćwiczenie wielostawowe angażujące prawie wszystkie mięśnie ciała — prostowniki grzbietu, pośladki, kulszowo-goleniowe i czworogłowe — szczyt budowania siły ogólnej.','Stań z nogami na szerokość bioder, palce stóp lekko na zewnątrz. Sztanga nad środkiem stopy. Złap sztangę nachwytem lub mieszanym chwytem, nieco szerzej niż nogi. Plecy proste, klatka dumna. Wciśnij podłogę od siebie (jak w przysiadzie), prostując jednocześnie kolana i biodra do pionowej pozycji. Opuść sztangę kontrolowanie tą samą ścieżką.','Zaokrąglanie lędźwi na starcie lub podczas ruchu. Odrywanie bioder zbyt wcześnie i zamienianie ruchu w ściąganie pleców. Kolana wpadające do środka.','Wyobraź sobie, że odpychasz podłogę od siebie przez pięty — to aktywuje czworogłowe i daje dobry start. Biodra i ramiona rosną jednocześnie w fazie koncentrycznej.','Głęboki wdech przed podniesieniem, napnij core jak przy ciosie. Wydech po minięciu kolan lub na górze.','Zaokrąglone lędźwie pod ciężarem to najczęstsza przyczyna urazów kręgosłupa. Opanuj technikę zanim dodasz obciążenie. Użyj pasa przy submaksymalnym ciężarze.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Zawiasowe','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Wysokie',5,5,5,'Wysoki',true,NULL,'Złożona','{"plecy": 0.4, "dwugłowe": 0.3, "pośladki": 0.3}'::jsonb),(183,'Wznosy tułowia','wznosy-tu-owia','Plecy',ARRAY['Pośladki','Mięśnie dwugłowe uda'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia'],'Początkujący','Zawias biodrowy','Wznosy tułowia (hyperextension / back extension) to izolowane ćwiczenie na ławce rzymskiej lub GHD, trenujące prostowniki grzbietu i stabilizatory lędźwiowe przez pełen zakres ruchu.','Ustaw ławkę tak, by oparcie znajdowało się poniżej bioder. Przekrzyżuj ręce na klatce lub wyciągnij je za głowę. Powoli opuść tułów w dół do kąta 90°, a następnie wznieś go do linii ciała lub nieznacznie wyżej. Na górze napnij pośladki i prostowniki grzbietu.','Nadmierny przeprost na szczycie — kręgosłup powinien tworzyć prostą linię, a nie łuk. Zbyt szybkie tempo bez kontroli.','Utrzymuj napięcie w core przez cały ruch. Możesz dodać obciążenie (talerz przy klatce), gdy masa ciała staje się za lekka.','Wdech podczas opuszczania, wydech podczas wznoszenia.','Nie przeprostowuj kręgosłupa powyżej neutralnej pozycji. Przy bólu dolnego odcinka pleców skonsultuj się ze specjalistą.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Siła'],'Zawiasowe','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',2,1,3,'Wysoki',true,NULL,'Umiarkowana','{"plecy": 0.6, "pośladki": 0.4}'::jsonb),(184,'Szrugowanie ze sztangą','szrugowanie-ze-sztanga','Plecy',ARRAY[]::text[],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Początkujący','Inne','Szrugowanie ze sztangą to izolowane ćwiczenie na górną część mięśnia czworobocznego, wykonywane przez unoszenie barków ku uszom przy wyprostowanych łokciach.','Stań wyprostowany, trzymając sztangę nachwytem przed udami. Wzrusz ramionami maksymalnie ku uszom bez zginania łokci. Utrzymaj pozycję przez chwilę, napinając górny trapez, i powoli opuść.','Toczenie barków do przodu lub do tyłu zamiast ruchu czysto pionowego. Zginanie łokci i zamienianie ćwiczenia w curl.','Ruch powinien być pionowy — w górę i w dół. Wyobraź sobie, że próbujesz dotknąć barkami uszu.','Wdech przed uniesieniem, wydech podczas opuszczania.','Nie toczaj barków — może obciążyć staw barkowo-obojczykowy. Używaj pasków do nadgarstków przy dużych ciężarach.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Czołowa','Obustronne','Sztanga',false,'Z ostrożnością','Niskie',1,1,2,'Średni',true,NULL,'Prosta',NULL),(185,'Wiosłowanie leżąc przodem z hantlami','wios-owanie-lezac-przodem-z-hantlami','Plecy',ARRAY['Biceps'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Przyciąganie poziome','Wiosłowanie w leżeniu przodem (seal row / prone dumbbell row) eliminuje zamach tułowia dzięki podparciu klatki na ławce, zapewniając pełną izolację mięśni pleców przy poziomym ciąganiu.','Połóż się brzuchem na lekko uniesionym końcu ławki, chwytając hantle oburącz. Ciągnij hantle ku bokach klatki, prowadząc łokcie w górę i cofając łopatki. Napnij plecy na górze i powoli opuść.','Nie korzystanie z pełnego podparcia ławki — tułów musi przez cały czas leżeć na ławce. Szarpanie zamiast kontrolowanego ciągnienia.','Ustaw ławkę tak, by ramiona swobodnie zwisały w dole bez dotykania ziemi. Skup się na cofaniu łopatkek przed zginaniem łokci.','Wdech w dole, wydech podczas ciągnienia.','Bezpieczne ćwiczenie — brak kompresji kręgosłupa. Idealne dla osób z bólem dolnych pleców.','Złożone',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Ciągnięcie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',2,2,3,'Wysoki',true,NULL,'Umiarkowana','{"lats": 0.3, "upper_back": 0.7}'::jsonb),(186,'Wyciskanie sztangą nad głowę','wyciskanie-sztanga-nad-g-owe','Barki',ARRAY['Triceps'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie pionowe','Wyciskanie sztangą nad głowę (OHP / military press) to fundamentalne ćwiczenie na barki budujące siłę i masę przednich i bocznych naramiennych przy jednoczesnym angażowaniu tricepsów i całego core jako stabilizatora.','Stań z nogami na szerokość barków, sztanga na poziomie obojczyków w nachwycie nieco szerzej niż barki. Napnij core i pośladki. Wyciśnij sztangę pionowo w górę, minimalnie cofając głowę, by drążek przeszedł przed twarzą. Na górze wyprostuj ramiona bez blokowania łokci. Powoli opuść do punktu startowego.','Nadmierne odchylanie kręgosłupa lędźwiowego do tyłu — kompensowanie słabych core. Zbyt szeroki chwyt, który ogranicza zakres ruchu. Opuszczanie sztangi za szyję.','Wyobraź sobie, że chcesz wycisnąć sztangę lekko do tyłu za głowę na górze — to naturalnie aktywuje górny trapez i poprawia tory ruchu. Core napięty jak przed ciosem.','Głęboki wdech przed wyciskaniem, napnij core. Wydech na górze lub po zakończeniu powtórzenia.','Nie wyciskaj ze zbyt wąskim chwytem — przeciąża to nadgarstki. Opanuj technikę z lekkim ciężarem zanim dodasz obciążenie.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Czołowa','Obustronne','Sztanga',false,'Z ostrożnością','Średnie',4,4,3,'Wysoki',true,NULL,'Złożona','{"rear_delt": 0.1, "front_delt": 0.6, "lateral_delt": 0.3}'::jsonb),(187,'Uginanie koncentryczne z hantlem','uginanie-koncentryczne-z-hantlem','Biceps',ARRAY[]::text[],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Zgięcie łokcia','Uginanie koncentryczne (concentration curl) izoluje głowę długą bicepsa przez opieranie łokcia o udo, eliminując zamach i wymuszając pełen zakres ruchu przy szczytowym skurczu mięśnia.','Usiądź na ławce, rozsuń nogi. Chwyć hantel w jedną rękę i oprzyj łokieć o wewnętrzną stronę uda tej samej nogi. Swobodnie opuść rękę. Ugnij ramię w pełnym zakresie ku barku, supinując nadgarstek na szczycie. Powoli opuść.','Odrywanie łokcia od uda i używanie tułowia jako dźwigni. Zbyt szybkie tempo bez skupienia na skurczu.','Na szczycie ruchu maksymalnie supinuj nadgarstek (obróć dłoń tak, by mały palec był wyżej). To aktywuje głowę długą bicepsa do maksimum.','Wydech podczas uginania, wdech podczas opuszczania.','Lekkie obciążenie — to ćwiczenie izolowane. Nie używaj dużych ciężarów kosztem techniki.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Jednostronne','Hantle',false,'Z ostrożnością','Niskie',1,1,2,'Średni',true,NULL,'Prosta',NULL),(188,'Uginanie Zottmana','uginanie-zottmana','Biceps',ARRAY['Przedramiona'],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Średniozaawansowany','Zgięcie łokcia','Uginanie Zottmana łączy podchwytowy curl w fazie koncentrycznej (biceps) z nachwytem w fazie ekscentrycznej (brachioradialis i prostowniki nadgarstka), trenując kompleksowo mięśnie zginaczy stawu łokciowego.','Stań z hantlami w podchwycie wzdłuż boków. Ugnij ramiona do góry w standardowym curlu (dłonie ku górze). Na szczycie obróć nadgarstki tak, by dłonie były skierowane w dół (nachwytem). Powoli opuszczaj hantle w tym ustawieniu. Obróć nadgarstki z powrotem do podchwytu na dole i powtórz.','Pomijanie rotacji nadgarstka lub wykonywanie jej za wcześnie podczas ruchu. Zbyt szybkie tempo w fazie ekscentrycznej.','Rotacja nadgarstka następuje dopiero na szczycie ruchu — nie w trakcie uginania. Faza ekscentryczna powinna być powolna (3 sekundy).','Wydech podczas uginania, wdech podczas opuszczania.','Używaj umiarkowanego ciężaru — rotacja nadgarstka przy dużym obciążeniu może obciążyć stawy łokciowe.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',3,2,3,'Średni',true,NULL,'Umiarkowana',NULL),(189,'Kickback z hantlem na triceps','kickback-z-hantlem-na-triceps','Triceps',ARRAY[]::text[],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Wyprost łokcia','Kickback z hantlem to izolowane ćwiczenie na tricepsy wykonywane w opadzie tułowia, w którym prostowanie ramienia wzdłuż ciała silnie angażuje głowę boczną i przyśrodkową mięśnia trójgłowego.','Pochyl tułów do poziomu z podparciem jednej ręki na ławce. Unieś łokieć do poziomu pleców, trzymając hantlę. Wyprostuj ramię w tył tak, by tworzył prostą linię z tułowiem. Napnij tricepsy na końcu ruchu. Powoli zegnij łokieć i wróć.','Opadanie łokcia poniżej poziomu pleców — eliminuje zaangażowanie tricepsa. Zamach hantlą zamiast kontrolowanego prostowania.','Łokieć musi być wyżej niż tułów — to jest klucz do izolacji tricepsa. Skup się na napięciu mięśnia na szczycie wyprostu.','Wydech podczas prostowania ramienia, wdech podczas powrotu.','Lekkie obciążenie. Przy bólu łokcia zredukuj ciężar lub zastąp ćwiczenie pushdownem na wyciągu.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Strzałkowa','Jednostronne','Hantle',false,'Z ostrożnością','Niskie',1,1,2,'Średni',true,NULL,'Prosta',NULL),(190,'Prostowanie ramion nad głową z hantlem','prostowanie-ramion-nad-g-owa-z-hantlem','Triceps',ARRAY[]::text[],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Wyprost łokcia','Prostowanie ramion nad głową z hantlem trzymanym oburącz rozciąga głowę długą tricepsa w pełnym zakresie — pozycja nad głową aktywuje ją silniej niż jakiekolwiek ćwiczenie tricepsowe przy boku tułowia.','Usiądź lub stań. Trzymaj jeden hantlel oburącz za górną tarczę nad głową, łokcie wąsko przy uszach. Zegnij łokcie, opuszczając hantlę za głowę w pełnym zakresie ruchu. Wyprostuj ramiona w górę bez blokowania łokci i powtórz.','Rozpadanie łokci na boki — eliminuje izolację tricepsów. Zbyt mały zakres ruchu na dole.','Łokcie muszą pozostać wąskie — wyobraź sobie, że ściskasz coś łokciami przez cały czas. Im głębiej opuścisz hantlę, tym lepsze rozciągnięcie długiej głowy.','Wdech podczas opuszczania hantla za głowę, wydech podczas prostowania.','Osoby z kontuzjami barków powinny zaczynać od małych ciężarów. Nie forsuj zakresu ruchu ponad komfortowy.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Hantle',false,'Z ostrożnością','Niskie',2,1,3,'Wysoki',true,NULL,'Umiarkowana','{"triceps": 1}'::jsonb),(191,'Przysiad ze sztangą z przodu','przysiad-ze-sztanga-z-przodu','Mięśnie czworogłowe uda',ARRAY['Pośladki','Plecy'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Zaawansowany','Przysiad','Przysiad ze sztangą z przodu (front squat) to wariant przysiadu ze sztangą ułożoną na przednich mięśniach naramiennych, który jeszcze mocniej angażuje czworogłowe i wymaga większej mobilności stawów skokowych i piersiowego odcinka kręgosłupa.','Ustaw sztangę na przednich naramiennych w pozycji czystej (łokcie wysoko, równoległe do podłogi) lub z rękoma skrzyżowanymi. Stopy na szerokość barków, palce lekko na zewnątrz. Zejdź w przysiad, trzymając tułów pionowo i kolana nad palcami. Wróć przez wypchnięcie podłogi od siebie.','Opadanie łokci i utrata pozycji czystej — sztanga zsunie się do przodu. Zaokrąglanie górnych pleców przy braku mobilności klatki. Kolana wpadające do środka.','Łokcie muszą być jak najwyżej przez cały czas — to trzyma tułów pionowo. Przysiad czołowy wymaga większej mobilności niż tylny — rozgrzewaj stawy skokowe i klatkę.','Głęboki wdech przed zejściem, napnij core. Wydech podczas wychodzenia z przysiadu.','Trudne technicznie ćwiczenie — opanuj przysiad tylny i mobilność zanim zaczniesz. Stosuj odpowiednio mniejsze ciężary niż przy przysiadzie tylnym.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Przysiad','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Wysokie',5,5,5,'Wysoki',true,NULL,'Złożona','{"pośladki": 0.25, "czworogłowe": 0.75}'::jsonb),(192,'Martwy ciąg sumo','martwy-ciag-sumo','Mięśnie dwugłowe uda',ARRAY['Pośladki','Plecy','Przywodziciele'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Zaawansowany','Zawias biodrowy','Martwy ciąg sumo to wariant ze szerokim rozstawem nóg i stopami skierowanymi na zewnątrz, który silniej angażuje przywodziciele i pośladki, pozwala zachować bardziej pionowy tułów i bywa łatwiejszy dla osób z długim tułowiem.','Ustaw stopy zdecydowanie szerzej niż barki, palce pod kątem 45°. Chwyć sztangę wąskim nachwytem między nogami. Wyprostuj kręgosłup, unieś klatkę. Wypchnij biodra do przodu i ku górze, prostując jednocześnie kolana. Utrzymaj plecy proste przez cały ruch.','Zaokrąglanie dolnych pleców — identyczne zagrożenie jak w wersji konwencjonalnej. Kolana wpadające do środka podczas wychodzenia z pozycji.','Ciągnij kolana na zewnątrz przez cały ruch — to aktywuje przywodziciele i chroni kolana. Biodra startują wyżej niż w konwencjonalnym.','Głęboki wdech przed podniesieniem, napnij core. Wydech na górze lub po zakończeniu powtórzenia.','Wymaga dobrej mobilności bioder i przywodzicieli. Nie forsuj rozstawu szerszego niż pozwala mobilność — ryzyko naderwania przywodzicieli.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Zawiasowe','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Wysokie',4,5,5,'Wysoki',true,NULL,'Złożona','{"dwugłowe": 0.35, "pośladki": 0.45, "czworogłowe": 0.2}'::jsonb),(193,'Uginanie nóg na wyciągu stojąc','uginanie-nog-na-wyciagu-stojac','Mięśnie dwugłowe uda',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie kolana','Uginanie nóg na wyciągu w pozycji stojącej to jednostronna izolacja kulszowo-goleniowych z pełnym zakresem ruchu, wykonywana z obciążeniem nakolannikiem przy wyciągu dolnym.','Przymocuj nakolannik do wyciągu dolnego na jedną nogę. Stań przodem do maszyny, trzymaj się uchwytu dla stabilności. Zegnij kolano, ciągnąc stopę ku pośladkowi w pełnym zakresie. Napnij kulszowo-goleniowe na szczycie i powoli wyprostuj.','Ruch biodrem zamiast tylko kolanem. Opuszczanie nogi zbyt szybko bez ekscentrycznej kontroli.','Udo musi pozostać nieruchome — tylko podudzie się porusza. Wykonuj ćwiczenie wolno, szczególnie w fazie ekscentrycznej.','Wydech podczas uginania, wdech podczas opuszczania.','Bezpieczna wersja jednostronna — dobra dla wyrównywania asymetrii między nogami.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Ciągnięcie','Strzałkowa','Jednostronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,3,'Średni',true,NULL,'Umiarkowana',NULL),(194,'Odwodzenie nogi w tył z wykorzystaniem linki wyciągu dolnego','donkey-kick-na-wyciagu','Pośladki',ARRAY['Mięśnie dwugłowe uda'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Zawias biodrowy','Donkey kick na wyciągu (cable hip kickback) to izolowane ćwiczenie na mięsień pośladkowy wielki, w którym opór wyciągu utrzymuje stałe napięcie przez cały zakres ruchu — skuteczniejsze od wersji z masą ciała.','Przymocuj nakolannik do wyciągu dolnego. Stań przodem do maszyny, oprzyj się o ramę, lekko pochyl tułów. Trzymając kolano zgiętym pod kątem 90°, wysuń stopę w tył i ku górze, napinając pośladek na szczycie. Powoli wróć do pozycji startowej.','Rotacja miednicy i kompensowanie ruchem lędźwi zamiast pracy pośladka. Prostowanie kolana i zamienianie ćwiczenia w hip extension.','Kolano pozostaje zgięte pod kątem 90° przez cały czas. Na szczycie napnij mocno pośladek i utrzymaj przez chwilę.','Wydech podczas wypchnięcia nogi, wdech podczas powrotu.','Reguluj ciężar tak, by zakres ruchu był pełny bez rotowania miednicy.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne','Hipertrofia'],'Zawiasowe','Strzałkowa','Jednostronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,2,'Średni',true,false,'Umiarkowana',NULL),(195,'Wspięcia na palce jednostronne stojąc','wspiecia-na-palce-jednostronne-stojac','Łydki',ARRAY[]::text[],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Wyprost kolana','Wspięcia na palce jednostronne to najtrudniejsza wersja ćwiczenia na łydki z masą ciała, wymagająca pełnego uniesienia na jednej nodze przez pełen zakres ruchu — skutecznie zastępuje maszynę do wspięć.','Stań na jednej nodze na krawędzi schodka lub podwyższenia, piętą opuszczoną w dół. Trzymaj się czegoś dla równowagi. Wznieś się maksymalnie na palce, napinając łydkę. Powoli opuść piętę poniżej poziomu podwyższenia dla pełnego rozciągnięcia.','Wykonywanie małego zakresu ruchu — piętę trzeba opuścić poniżej poziomu stopy. Zbyt szybkie tempo, eliminujące ekscentryczną pracę mięśnia.','Pełen zakres ruchu — od maksymalnego rozciągnięcia do maksymalnego skurczu. Możesz dodać obciążenie, trzymając hantlę w wolnej ręce.','Wdech podczas opuszczania, wydech podczas wspięcia.','Trzymaj się uchwytu dla bezpieczeństwa, szczególnie na śliskiej powierzchni.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Pchanie','Strzałkowa','Jednostronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',1,1,3,'Średni',true,NULL,'Prosta',NULL),(196,'Odwodzenie biodra na wyciągu','odwodzenie-biodra-na-wyciagu','Odwodziciele',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Odwodzenie','Odwodzenie biodra na wyciągu to izolowane ćwiczenie na mięsień pośladkowy średni i odwodziciele, uzupełniające maszynę abduktorową o stały opór przez pełen zakres ruchu.','Przymocuj nakolannik do wyciągu dolnego na zewnętrzną stronę kostki. Stań bokiem do maszyny, trzymając się uchwytu. Odwiedź nogę w bok na tyle wysoko, na ile pozwala mobilność biodra bez rotowania miednicy. Powoli wróć do pozycji startowej.','Pochylanie tułowia na bok zamiast pracy samym biodrem. Zakres ruchu zbyt mały — unoszenie nogi tylko kilka centymetrów.','Miednica i tułów muszą pozostać nieruchome — pracuje tylko noga. Skup się na napięciu pośladka średniego na szczycie ruchu.','Wydech podczas odwodzenia, wdech podczas powrotu.','Bezpieczne ćwiczenie dla większości osób — dobre uzupełnienie treningu pośladków i profilaktyki kolan.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Ciągnięcie','Czołowa','Jednostronne','Wyciąg',false,'Z ostrożnością','Niskie',2,1,2,'Średni',true,NULL,'Umiarkowana',NULL),(197,'Hollow body hold','hollow-body-hold','Brzuch',ARRAY[]::text[],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Anti-ekstensja','Hollow body hold to statyczne ćwiczenie anti-ekstensji z gimnastyki, w którym utrzymanie płaskiego, wydrążonego kształtu ciała intensywnie angażuje cały anterior core — mięsień poprzeczny i prosty brzucha.','Połóż się na plecach, wyciągnij ramiona za głowę. Dociśnij mocno lędźwie do podłogi. Jednocześnie unieś ramiona, głowę, barki i nogi kilkanaście centymetrów nad podłogę — ciało tworzy kształt wydrążonej łódki. Utrzymaj pozycję przez 20–60 sekund bez odrywania lędźwi od podłogi.','Odrywanie lędźwi od podłogi — to podstawowy błąd niszczący cel ćwiczenia. Zbyt wysoko uniesione kończyny — zacznij od wyższego ustawienia jeśli lędźwie nie leżą.','Jeśli nie możesz utrzymać lędźwi na podłodze, unieś nogi wyżej lub zegnij kolana. Progresja: wydłużaj czas utrzymania lub opuść nogi bliżej podłogi.','Krótkie, kontrolowane oddechy podczas utrzymywania pozycji — nie wstrzymuj oddechu.','Idealne ćwiczenie prewencyjne dla dolnego odcinka pleców. Bezpieczne dla wszystkich grup.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Siła'],'Core','Strzałkowa','Obustronne','Masa własnego ciała',false,'Tak','Niskie',2,1,2,'Wysoki',true,NULL,'Umiarkowana','{"brzuch": 1}'::jsonb),(198,'Rotacje rosyjskie','rotacje-rosyjskie','Brzuch',ARRAY[]::text[],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Rotacja','Rotacje rosyjskie (Russian twist) to ćwiczenie rotacyjne angażujące mięśnie skośne brzucha i poprzeczny brzucha, wykonywane w siadzie z uniesionym tułowiem i obracaniem ramion na boki.','Usiądź na podłodze z kolanami ugiętymi, pięty uniesione lub oparte. Pochyl tułów pod kątem 45° do tyłu. Złącz ręce przed sobą lub trzymaj ciężar. Obracaj ramiona na przemian w lewo i prawo, skręcając wyraźnie w klatce piersiowej i brzuchu.','Rotacja samymi ramionami bez skrętu tułowia — nie angażuje skośnych. Zbyt szybkie tempo bez kontroli.','Skręt musi pochodzić z tułowia — wyobraź sobie, że chwytasz coś daleko za sobą. Możesz dodać hantlę lub talerz dla progresji.','Wydech podczas rotacji, wdech podczas powrotu do środka.','Osoby z bólem dolnych pleców powinny unikać tego ćwiczenia lub wykonywać z ograniczonym zakresem rotacji.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Core','Poprzeczna','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',1,1,2,'Średni',true,NULL,'Prosta',NULL),(199,'Woodchop na wyciągu','woodchop-na-wyciagu','Brzuch',ARRAY['Barki','Plecy'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Rotacja','Woodchop na wyciągu (cable woodchop / cable chop) to funkcjonalne ćwiczenie rotacyjne angażujące skośne brzucha w pełnym zakresie ruchu z oporem wyciągu — naśladuje ruch cięcia drewna siekierą.','Ustaw wyciąg wysoko po jednej stronie. Chwyć uchwyt oburącz, stań bokiem do maszyny. Ciągnij uchwyt po przekątnej w dół i przez tułów, skręcając razem z ruchem. Prowadź ręce od pozycji wysoko z boku ku dołowi po przeciwnej stronie bioder. Powoli wróć.','Wykonywanie ruchu ramionami zamiast rotacją tułowia. Zbyt duży ciężar, który uniemożliwia kontrolowany ruch.','Rotacja zaczyna się od bioder i miednicy, tułów podąża za nimi — nie odwrotnie. Stopy pozostają w miejscu przez cały ruch.','Wydech podczas ciągnięcia i rotacji, wdech podczas powrotu.','Lekki do umiarkowanego opór. Osoby z bólem kręgosłupa powinny skonsultować się ze specjalistą.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Core','Poprzeczna','Jednostronne','Wyciąg',false,'Z ostrożnością','Niskie',3,2,2,'Średni',true,NULL,'Umiarkowana',NULL),(200,'Unoszenie nóg w leżeniu','unoszenie-nog-w-lezeniu','Brzuch',ARRAY[]::text[],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Zgięcie tułowia','Unoszenie nóg w leżeniu to ćwiczenie zgięcia tułowia ze szczególnym naciskiem na dolną część mięśnia prostego brzucha, w którym nogi unoszą się przy nieruchomym tułowiu.','Połóż się na plecach, ręce pod pośladkami lub wzdłuż ciała. Wyprostuj nogi lub lekko zegnij kolana. Unoś nogi do pionu (lub do kąta 90°), docisnąwszy mocno lędźwie do podłogi. Powoli opuść nogi bez dotykania podłogi i powtórz.','Odrywanie lędźwi od podłogi podczas opuszczania nóg — największy błąd. Zamach nogami zamiast kontrolowanego ruchu.','Lędźwie muszą być dociśnięte do podłogi przez cały ruch. Jeśli to trudne, zegnij kolana lub skróć zakres. Zatrzymaj nogi tuż nad podłogą na chwilę przed kolejnym powtórzeniem.','Wydech podczas unoszenia nóg, wdech podczas opuszczania.','Przy bólu dolnych pleców zmniejsz zakres ruchu lub wykonuj z ugiętymi kolanami.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Core','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',2,1,2,'Średni',true,NULL,'Umiarkowana',NULL),(201,'Superman','superman','Plecy',ARRAY['Pośladki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Stabilizacja tułowia','Superman to proste ćwiczenie na prostowniki grzbietu i pośladki wykonywane w leżeniu przodem, w którym jednoczesne unoszenie ramion i nóg aktywuje mięśnie tylnego łańcucha ciała.','Połóż się na brzuchu, ramiona wyciągnięte przed siebie. Jednocześnie unieś ręce, głowę, klatkę i nogi kilkanaście centymetrów nad podłogę. Napnij pośladki i prostowniki. Utrzymaj przez 2–3 sekundy i powoli opuść.','Zbyt gwałtowne unoszenie, generujące zamach. Unoszenie tylko rąk bez nóg lub odwrotnie.','Wyobraź sobie, że coś ciągnie cię jednocześnie za ręce i stopy w przeciwnych kierunkach. Ruch powinien być spokojny i kontrolowany.','Wdech w pozycji na podłodze, wydech podczas unoszenia.','Bezpieczne ćwiczenie dla większości osób. Osoby ze stenozą kanału kręgowego powinny skonsultować się ze specjalistą.','Izolowane',ARRAY['Brak aktywności fizycznej','Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Core','Strzałkowa','Obustronne','Masa własnego ciała',false,'Tak','Niskie',1,1,1,'Średni',true,NULL,'Prosta',NULL),(202,'Uginanie nadgarstków ze sztangą','uginanie-nadgarstkow-ze-sztanga','Przedramiona',ARRAY[]::text[],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Początkujący','Zgięcie łokcia','Uginanie nadgarstków ze sztangą to izolowane ćwiczenie na zginacze nadgarstka i palców, wykonywane w siadzie z przedramionami opartymi na udach — podstawowe ćwiczenie wzmacniające chwyt.','Usiądź, ułóż przedramiona na udach z nadgarstkami zwisającymi za kolan. Chwyć sztangę podchwytem. Ugnij nadgarstki, unosząc sztangę ku górze. Napnij zginacze na szczycie i powoli opuść poniżej neutralnej pozycji.','Unoszenie łokci od ud i angażowanie bicepsów. Zbyt duży ciężar, uniemożliwiający pełen zakres ruchu.','Przedramiona muszą leżeć nieruchomo na udach — tylko nadgarstek się porusza. Lekki ciężar z dużą liczbą powtórzeń (15–20) daje najlepsze wyniki.','Oddychaj swobodnie — ćwiczenie izolowane, niskie obciążenie.','Stopniowo zwiększaj ciężar — nadgarstki są delikatne. Przerwij przy bólu nadgarstków.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Niskie',1,1,2,'Średni',true,NULL,'Prosta',NULL) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,main_muscle_group=EXCLUDED.main_muscle_group,secondary_muscle_groups=EXCLUDED.secondary_muscle_groups,equipment=EXCLUDED.equipment,training_location=EXCLUDED.training_location,difficulty_level=EXCLUDED.difficulty_level,movement_pattern=EXCLUDED.movement_pattern,exercise_type=EXCLUDED.exercise_type,suitable_experience_levels=EXCLUDED.suitable_experience_levels,training_goals=EXCLUDED.training_goals,movement_category=EXCLUDED.movement_category,is_active=EXCLUDED.is_active,exercise_priority=EXCLUDED.exercise_priority,sub_target_biases=EXCLUDED.sub_target_biases`;

const SQL_EXERCISES_3 = `INSERT INTO exercises (id,name,slug,main_muscle_group,secondary_muscle_groups,equipment,equipment_other,training_location,difficulty_level,movement_pattern,description,execution_instructions,common_mistakes,coaching_tips,breathing_tips,safety_notes,exercise_type,suitable_experience_levels,training_goals,movement_category,plane_of_motion,execution,resistance_type,requires_spotter,can_be_performed_to_failure,joint_stress,learning_difficulty,neurological_fatigue,doms_potential,exercise_priority,is_active,suitable_for_no_activity,movement_complexity,sub_target_biases) VALUES (203,'Prostowanie nadgarstków ze sztangą','prostowanie-nadgarstkow-ze-sztanga','Przedramiona',ARRAY[]::text[],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Początkujący','Wyprost łokcia','Prostowanie nadgarstków ze sztangą to izolowane ćwiczenie na prostowniki nadgarstka i palców — antagonistów zginaczy, ważne dla równowagi sił przedramion i profilaktyki kontuzji łokcia tenisisty.','Usiądź, ułóż przedramiona na udach z nadgarstkami zwisającymi za kolan. Chwyć sztangę nachwytem (dłonie w dół). Unieś nadgarstki ku górze w pełnym zakresie. Napnij prostowniki na szczycie i powoli opuść.','Używanie zbyt dużego ciężaru — prostowniki są słabsze od zginaczy. Ruch łokciami zamiast tylko nadgarstkami.','To ćwiczenie jest trudniejsze niż wygląda — prostowniki nadgarstka są znacznie słabsze od zginaczy. Zacznij od minimalnego obciążenia.','Oddychaj swobodnie podczas całego ćwiczenia.','Kluczowe dla równowagi sił przedramienia i zdrowia łokcia. Szczególnie ważne dla osób z tenisowym łokciem.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Niskie',1,1,2,'Średni',true,NULL,'Prosta',NULL),(204,'Uginanie ramion ze sztangą nachwytem','uginanie-ramion-ze-sztanga-podchwytem','Biceps',ARRAY['Przedramiona'],ARRAY['Sztanga'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Zgięcie łokcia','Uginanie ze sztangą podchwytem (reverse curl) angażuje brachialis i prostowniki nadgarstka poprzez pronowany chwyt — wzmacnia całą strefę łokciową i skutecznie trenuje mięśnie przedniego przedramienia.','Stań z nogami na szerokość bioder, chwyć sztangę nachwytem (dłonie skierowane w dół) na szerokość barków. Trzymając łokcie przy tułowiu i nadgarstki wyprostowane, ugnij ramiona ku barkom. Napnij mięśnie na szczycie i powoli opuść.','Zginanie nadgarstków — muszą być neutralne lub lekko wyprostowane przez cały czas. Zamach tułowia przy dużych ciężarach.','Używaj znacznie mniejszego ciężaru niż przy zwykłym uginaniu. Prostowniki nadgarstka i brachialis są słabsze niż biceps — nie przeciążaj ich.','Wydech podczas uginania, wdech podczas opuszczania.','Ćwiczenie może obciążać nadgarstki — wykonuj z lekkim ciężarem i nie forsuj zakresu. Przy bólu łokcia przerwij.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Sztanga',false,'Z ostrożnością','Niskie',2,1,2,'Średni',true,NULL,'Umiarkowana',NULL),(205,'Ściąganie jednorącz wyciągu górnego','sciaganie-jednoracz-wyciagu-gornego','Plecy',ARRAY['Biceps','Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Przyciąganie pionowe','Jednostronne ściąganie drążka wyciągu górnego pozwala na większy zakres ruchu i lepszą izolację mięśnia najszerszego grzbietu po każdej stronie osobno. Idealne do wyrównywania asymetrii siłowej i poprawy połączenia neuromięśniowego z latissimus dorsi.','Usiądź przy wyciągu górnym, chwyć uchwyt jednoręczny dłonią w chwyt neutralny lub podchwyt. Ciągnij łokieć w dół i ku tyłu, prowadząc go blisko ciała. Na dole napnij mocno mięsień najszerszy i łopatkę obniż. Powoli wróć do pełnego rozciągnięcia, kontrolując ciężar.','Odchylanie tułowia za daleko w tył (przenosi obciążenie na prostowniki). Brak pełnego rozciągnięcia na górze. Angażowanie bicepsa jako motoru zamiast pleców.','Wyobraź sobie, że łokciem chcesz dosięgnąć kieszeni spodni. Inicjuj ruch depresją łopatki, nie bicepsem. Możesz lekko obrócić tułów dla większego rozciągnięcia.','Wdech w górnej pozycji, wydech podczas ściągania.','Kontroluj powrót ciężaru — gwałtowne rozluźnienie może nadwyrężyć bark lub staw łokciowy.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Czołowa','Jednostronne','Wyciąg',false,'Tak','Niskie',2,2,3,'Średni',true,NULL,'Umiarkowana','{"lats": 0.7, "upper_back": 0.3}'::jsonb),(206,'Uginanie ramion w podporze klatki (Spider Curl)','uginanie-ramion-w-podporze-klatki-spider-curl','Biceps',ARRAY['Przedramiona'],ARRAY['Hantle','Sztanga','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Zgięcie łokcia','Spider Curl to uginanie ramion w podporze klatki piersiowej na ławce pochyłej ustawionej pod kątem 45-60°. Dzięki pozycji ramion przed tułowiem długa głowa bicepsa jest w skróceniu przez cały ruch — eliminuje to możliwość pomocniczego zamachu i maksymalizuje izolację.','Połóż się przodem na ławce skośnej dodatniej (kąt 45-60°), klatka na podparciu, ramiona swobodnie zwisają ku dołowi. Chwyć hantle lub sztangę podchwytem. Ugnij ramiona, unosząc ciężar ku barkom bez odrywania ramion od podparcia. Napnij biceps na szczycie i powoli opuść do pełnego wyprostu.','Odrywanie ramion od ławki w górnej fazie ruchu. Zbyt szybkie tempo powrotu. Brak pełnego wyprostu na dole.','Długa głowa bicepsa jest skrócona w tej pozycji — używaj mniejszego ciężaru niż przy standardowym uginaniu. Skup się na wolnym, kontrolowanym opuszczaniu.','Wdech w dolnej pozycji, wydech podczas uginania.','Nie przeprostowuj gwałtownie stawu łokciowego w dolnej fazie — utrzymuj minimalne napięcie przez cały ruch.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Obustronne','Hantle',false,'Tak','Niskie',2,1,3,'Niski',true,NULL,'Umiarkowana',NULL),(207,'Uginanie ramienia na wyciągu zza ciała (Bayesian Curl)','uginanie-ramienia-na-wyciagu-zza-cia-a-bayesian-curl','Biceps',ARRAY['Przedramiona'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Zgięcie łokcia','Bayesian Curl to uginanie jednej ręki na wyciągu dolnym z liną przeprowadzoną zza ciała. Ramię jest maksymalnie wyciągnięte za tułów, co rozciąga długą głowę bicepsa w pozycji wyjściowej i poddaje ją napięciu w pełnym zakresie rozciągnięcia — jest to mechanicznie optymalne dla hipertrofii.','Stań przodem od wyciągu dolnego, chwyć uchwyt jednoręczny i cofnij się o krok. Wyprostuj ramię za tułów tak, by biceps był maksymalnie rozciągnięty. Ugnij ramię, prowadząc łokieć do przodu i ku górze. Napnij biceps na szczycie i powoli wróć do pełnego rozciągnięcia za tułowiem.','Zbyt mały cofnięty krok — biceps nie jest w pełni rozciągnięty. Przemieszczanie łokcia do boku zamiast ruchu w płaszczyźnie strzałkowej.','Im bardziej cofniesz ramię za tułów, tym większe rozciągnięcie długiej głowy. Możesz lekko przechylić tułów do przodu dla jeszcze większego zakresu. Ćwiczenie jest wyjątkowo skuteczne z powolną fazą ekscentryczną.','Wdech na dole (rozciągnięcie), wydech podczas uginania.','Nie stosuj obciążeń powodujących ból w przodzie barku lub bicepsie w pozycji dolnej.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Ciągnięcie','Strzałkowa','Jednostronne','Wyciąg',false,'Tak','Niskie',3,1,3,'Niski',true,NULL,'Umiarkowana',NULL),(208,'Jednorącz odwodzenie ramienia w tył na wyciągu','jednoracz-odwodzenie-ramienia-w-ty-na-wyciagu','Barki',ARRAY['Plecy'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Odwodzenie','Jednostronne odwodzenie ramienia w tył na wyciągu (cable rear delt pull-back) izoluje tylną głowę mięśnia naramiennego. Wyciąg utrzymuje stałe napięcie przez cały zakres ruchu — przewaga nad hantlami, które mają zerowe napięcie w pozycji dolnej.','Stań bokiem do wyciągu, chwyć uchwyt jednoręczny ręką bliższą pulei. Utrzymaj ramię proste lub minimalnie ugięte w łokciu. Wyprowadź ramię w tył i na zewnątrz poziomo, skupiając się na napięciu tylnej delty. Kontroluj powrót — nie pozwól ciężarowi na gwałtowne przeciągnięcie ramienia.','Zginanie łokcia i zamiana ruchu w wiosłowanie. Rotacja tułowia wspomagająca ruch. Zbyt duży ciężar uniemożliwiający izolację.','Utrzymuj łokcieć na tej samej wysokości co bark przez cały ruch. Wyobraź sobie, że chcesz dotknąć łokciem ściany za sobą.','Wydech podczas odwodzenia, wdech podczas powrotu.','Ćwiczenie bezpieczne — stosuj lekki ciężar i kontrolowany ruch, by nie przeciążać stawu barkowego.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Ciągnięcie','Poprzeczna','Jednostronne','Wyciąg',false,'Tak','Niskie',2,1,2,'Niski',true,NULL,'Umiarkowana','{"rear_delt": 0.5, "lateral_delt": 0.5}'::jsonb),(209,'Rozciąganie gumy przed klatką (Band Pull-Apart)','rozciaganie-gumy-przed-klatka-band-pull-apart','Barki',ARRAY['Plecy'],ARRAY['Gumy oporowe'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Odwodzenie','Band Pull-Apart to ćwiczenie profilaktyczne i wzmacniające tylną deltę, środkowy trapez i równoległoboczne. Rozciągając gumę poziomo przed klatką i rozdzielając ją do boku, angażujemy mięśnie retrakcji łopatki i zewnętrznych rotatorów. Świetne jako rozgrzewka barków i korekcja postawy.','Stań prosto, trzymaj gumę oporową obiema rękami na szerokość barków na wysokości klatki (ramiona wyprostowane). Rozciągaj gumę, rozkładając ręce szeroko na boki, ściskając łopatki razem. Wróć powoli do pozycji wyjściowej. Utrzymuj łokcie lekko ugięte przez cały czas.','Uginanie łokci i zamiana ruchu w wiosłowanie. Unoszenie ramion ku górze zamiast poziomego odwiedzenia. Zbyt szybkie tempo bez kontroli powrotu.','Wyobraź sobie, że starasz się dotknąć łopatkami razem za plecami. Tempo 2-0-2 lub wolniejsze jest optymalne. Guma o niskim oporze — to ćwiczenie techniczne, nie siłowe.','Wydech podczas rozciągania gumy, wdech podczas powrotu.','Ćwiczenie w pełni bezpieczne. Idealne jako prehab i korekta zaokrąglonych ramion.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Ciągnięcie','Poprzeczna','Obustronne','Gumy oporowe',false,'Tak','Niskie',1,1,1,'Niski',true,NULL,'Prosta','{"rear_delt": 0.6, "upper_back": 0.1, "lateral_delt": 0.3}'::jsonb),(210,'Rotacja zewnętrzna barku na wyciągu','rotacja-zewnetrzna-barku-na-wyciagu','Barki',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Początkujący','Rotacja','Ćwiczenie prehab/akcesorialne stożka rotatorów — infraspinatus i teres minor. Rotacja zewnętrzna na wyciągu zapewnia stałe napięcie przez cały zakres ruchu. Stosowane jako prewencja kontuzji barku, element rozgrzewki przed treningiem pchania i ćwiczenie rehabilitacyjne. Nie jest ćwiczeniem hipertroficznym — celem jest zdrowie i stabilność stawu barkowego.','Stań bokiem do wyciągu dolnego lub środkowego, chwyć uchwyt jednoręczny ręką dalszą od pulei. Zegnij łokieć do 90° i dociśnij go do boku tułowia (możesz podłożyć zwinięty ręcznik dla stabilizacji). Obracaj przedramię na zewnątrz, utrzymując łokieć przy boku. Powoli wróć do pozycji wyjściowej.','Odrywanie łokcia od tułowia — traci izolację rotatorów. Zamach nadgarstkiem zamiast rotacji w stawie barkowym.','Ciężar powinien być bardzo lekki — to ćwiczenie rehabilitacyjne i prewencyjne. Skupiaj się na odczuwaniu rotacji w stawie barkowym, nie na pokonaniu ciężaru. Wykonuj jako rozgrzewkę lub akcesorialne zakończenie sesji.','Swobodny oddech — ciężar jest zbyt mały, by wymagał kontroli oddechu.','Przy bólu barku podczas rotacji skonsultuj się z fizjoterapeutą. Nie forsuj zakresu ruchu. Nie wykonuj do upadku — to ćwiczenie stabilizacyjne.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Ciągnięcie','Poprzeczna','Jednostronne','Wyciąg',false,'Nie','Niskie',2,1,1,'Niski',true,NULL,'Umiarkowana',NULL),(211,'Rotacja zewnętrzna barku z gumą oporową','rotacja-zewnetrzna-barku-z-guma-oporowa','Barki',ARRAY[]::text[],ARRAY['Gumy oporowe'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Rotacja','Ćwiczenie prehab/akcesorialne stożka rotatorów z gumą oporową — wszechstronne i dostępne bez siłownianego sprzętu. Guma uczy kontroli w zakresie rotacji zewnętrznej. Stosowane jako prewencja kontuzji barku, rozgrzewka przed treningiem pchania i ćwiczenie rehabilitacyjne. Nie jest ćwiczeniem hipertroficznym — celem jest zdrowie i stabilność stawu barkowego.','Przymocuj gumę do stałego punktu na wysokości łokcia. Stań bokiem, chwyć gumę ręką dalszą. Zegnij łokieć do 90°, dociśnij go do boku. Obracaj przedramię na zewnątrz, utrzymując łokieć przy tułowiu. Powoli wróć. Można też wykonywać oburącz, trzymając gumę przed sobą i rozciągając ją poziomo.','Odrywanie łokcia od ciała. Zbyt mocna guma uniemożliwiająca pełny zakres ruchu.','Guma o najlżejszym oporze, jaki masz dostępny. Priorytetem jest czysty zakres ruchu, nie pokonanie oporu. Wykonuj jako rozgrzewkę lub akcesorialne zakończenie sesji — nie jako główne ćwiczenie treningowe.','Swobodny oddech.','Bezpieczne ćwiczenie rehabilitacyjne. Stosuj przy pierwszych objawach bólu barku jako prewencja. Nie wykonuj do upadku — to ćwiczenie stabilizacyjne.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne'],'Ciągnięcie','Poprzeczna','Jednostronne','Gumy oporowe',false,'Nie','Niskie',1,1,1,'Niski',true,NULL,'Prosta',NULL),(212,'Katana Extension','jednoracz-prostowanie-ramienia-zza-g-owy-na-wyciagu-katana-extension','Triceps',ARRAY[]::text[],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Wyprost łokcia','Katana Extension to jednostronne prostowanie ramienia zza głowy na wyciągu. Ramię jest w pełni uniesionym, co rozciąga długą głowę tricepsa (jedyna głowa biartykułarna). Stałe napięcie wyciągu przez cały zakres ruchu czyni to ćwiczenie jednym z najbardziej efektywnych dla hipertrofii długiej głowy tricepsa.','Stań tyłem do wyciągu górnego, chwyć uchwyt jednoręczny lub linkę. Unieś łokieć nad głowę, tak by przedramię było za głową. Wyprostuj ramię w łokciu, prowadząc ciężar ku górze. Napnij triceps w górnej pozycji, następnie powoli wróć do pełnego ugięcia — przedramię za głową.','Opuszczanie łokcia — zmniejsza to napięcie długiej głowy. Zamach tułowia przy dużych ciężarach. Brak pełnego rozciągnięcia w dolnej fazie.','Utrzymuj łokieć skierowany ku górze przez cały czas. Wyciąg zmienia kierunek siły w porównaniu do hantla — odczujesz napięcie już od samego startu ruchu.','Wydech podczas prostowania, wdech podczas powrotu.','Nie stosuj ciężarów powodujących ból w stawie łokciowym lub barkowym. Ćwiczenie wymaga dobrej ruchomości barku.','Izolowane',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła','Hipertrofia'],'Pchanie','Strzałkowa','Jednostronne','Wyciąg',false,'Tak','Niskie',3,1,3,'Niski',true,false,'Umiarkowana',NULL),(213,'Wyciskanie JM (JM Press)','wyciskanie-jm-jm-press','Triceps',ARRAY['Klatka piersiowa','Barki'],ARRAY['Sztanga','Ławka'],NULL,ARRAY['Siłownia'],'Zaawansowany','Pchanie poziome','JM Press (od JM Blakley) to hybrydowe ćwiczenie łączące wyciskanie wąskim chwytem z francuskim prostowaniem — idealne do budowania siły lockoutu w wyciskaniu i masy długiej głowy tricepsa. Popularny w pracy siłaczy i zawodników powerlifterskich.','Połóż się na ławce poziomej, chwyć sztangę wąskim chwytem (szer. barków lub węziej). Opuść sztangę kontrolując łokcie — ugną się lekko na zewnątrz i sztanga zbliży się do twarzy (okolice nosa/czoła). W dolnym punkcie łokcie są nisko, zanikający przedramię leży pod kątem. Wypchnij sztangę z powrotem w górę, prostując łokcie.','Zbyt szeroki chwyt (traci charakter ćwiczenia). Opuszczanie zbyt głęboko bez kontroli. Stosowanie zbyt dużego ciężaru przed opanowaniem techniki.','Zacznij od bardzo lekkiego ciężaru i opanuj tor ruchu — to ćwiczenie techniczne. Połącz z wyciskaniem wąskim chwytem jako superset dla maksymalnej stymulacji tricepsa.','Wdech podczas opuszczania, wydech podczas wyciskania.','Ćwiczenie zaawansowane — stosuj asekuratora. Błędy techniczne mogą prowadzić do urazu łokcia lub barku.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Strzałkowa','Obustronne','Sztanga',true,'Z ostrożnością','Średnie',4,3,3,'Niski',true,NULL,'Złożona',NULL),(214,'Francuskie prostowanie ramion gumą oporową zza głowy','francuskie-prostowanie-ramion-guma-oporowa-zza-g-owy','Triceps',ARRAY[]::text[],ARRAY['Gumy oporowe'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Wyprost łokcia','Overhead triceps extension z gumą oporową — dostępna i skuteczna wersja klasycznego francuskiego prostowania. Guma zapewnia opór w środkowym i końcowym zakresie wyprostu, gdzie mięsień trójgłowy jest najsilniejszy. Idealne jako ćwiczenie domowe lub uzupełniające.','Stań na środku gumy oporowej stopami. Chwyć oba końce gumy, unieś ramiona nad głowę. Zegnij łokcie, opuszczając dłonie za głowę — guma rozciągnięta. Wyprostuj łokcie ku górze, napinając triceps. Utrzymuj łokcie skierowane ku górze przez cały ruch.','Opadanie łokci na zewnątrz. Brak pełnego zakresu ugięcia łokcia (skrócony zakres ruchu). Zbyt mocna guma ograniczająca prawidłowy ruch.','Dobierz gumę o oporze umożliwiającym pełne ugięcie łokci za głowę. Możesz wykonywać jednostronnie dla lepszej koncentracji.','Wydech podczas prostowania, wdech podczas powrotu.','Bezpieczne ćwiczenie przy użyciu odpowiednio lekkiej gumy. Przy bólu łokcia przejdź na wyciąg lub hantlę.','Izolowane',ARRAY['Początkujący','Średniozaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Pchanie','Strzałkowa','Obustronne','Gumy oporowe',false,'Tak','Niskie',2,1,2,'Niski',true,NULL,'Umiarkowana',NULL),(215,'Wyciskanie jednorącz na wyciągu','wyciskanie-jednoracz-na-wyciagu','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Wyciąg'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie poziome','Jednostronne wyciskanie na wyciągu — tzw. cable chest press — daje stałe napięcie na mięsień piersiowy w całym zakresie ruchu, włącznie z fazy powrotu (ekscentryczną). Wersja jednostronna umożliwia wyrównanie asymetrii i większą rotację tułowia aktywizującą dodatkowe włókna piersiowego.','Ustaw wyciąg na wysokości klatki lub barku. Chwyć uchwyt jednoręczny, stań w wykroku przodem od maszyny. Wypchnij ramię do przodu i ku środkowi ciała, spinając klatkę. Powoli wróć do pozycji wyjściowej z lekkim rozciągnięciem mięśnia piersiowego.','Za mały wykrok — brak stabilności. Obrót tułowia wspomagający zamiast kontrolowanego. Brak pełnego zakresu ruchu.','Możesz lekko skręcić tułów do środka przy pełnym wyprostu — angażuje to bardziej włókna środkowe klatki. Eksperymentuj z kątem ustawienia wyciągu (nisko, środkowo, wysoko).','Wdech podczas cofania ramienia, wydech podczas wyciskania.','Stabilna podstawa (szeroki wykrok) jest kluczowa dla bezpiecznego wykonania.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Pchanie','Poprzeczna','Jednostronne','Wyciąg',false,'Tak','Niskie',3,2,3,'Niski',true,NULL,'Umiarkowana','{"mid_chest": 0.6, "lower_chest": 0.2, "upper_chest": 0.2}'::jsonb),(216,'Wyciskanie hantli z dociskiem (Squeeze Press)','wyciskanie-hantli-z-dociskiem-squeeze-press','Klatka piersiowa',ARRAY['Triceps'],ARRAY['Hantle','Ławka'],NULL,ARRAY['Siłownia'],'Średniozaawansowany','Pchanie poziome','Squeeze Press (wyciskanie z dociskiem) to wyciskanie hantli leżąc z jednoczesnym mocnym dociskiem hantli do siebie przez cały czas trwania serii. Addukacja ramion tworzy ciągłe izometryczne napięcie w mięśniu piersiowym, wzmacniając połączenie neuromięśniowe i aktywację środkowych włókien klatki.','Połóż się na ławce poziomej z hantlami w dłoniach, chwytem neutralnym lub supinowanym. Dociśnij hantle mocno do siebie — utrzymaj ten docisk przez całą serię. Wyciśnij hantle ku górze i lekko ku sobie, nie rozluźniając ucisku. Powoli opuść utrzymując hantle razem.','Zwalnianie docisku na szczycie ruchu lub podczas opuszczania. Zbyt duże hantle uniemożliwiające utrzymanie napięcia.','Wyobraź sobie, że zgniatasz gąbkę między hantlami. Im silniejszy docisk, tym większa aktywacja środkowej klatki. Używaj umiarkowanego ciężaru — celem jest napięcie, nie masa obciążenia.','Wdech podczas opuszczania, wydech podczas wyciskania.','Ćwiczenie bezpieczne — docisk hantli eliminuje ryzyko ich rozjechania się.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Hantle',false,'Tak','Niskie',2,2,3,'Niski',true,NULL,'Umiarkowana','{"mid_chest": 0.65, "lower_chest": 0.15, "upper_chest": 0.2}'::jsonb),(217,'Wyciskanie na maszynie zbieżnej','wyciskanie-na-maszynie-zbieznej','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Pchanie poziome','Wyciskanie na maszynie zbieżnej (converging/plate-loaded machine press) naśladuje naturalny łuk ruchu mięśnia piersiowego — ramiona zbiegają się ku środkowi ciała na szczycie ruchu. Zapewnia bezpieczne, kontrolowane obciążenie z pełnym zakresem ruchu klatki bez ryzyka nierównowagi.','Ustaw siedzisko tak, by uchwyty były na wysokości dolnej części klatki piersiowej. Chwyć uchwyty, stopy płasko na podłodze. Wypchnij ramiona do przodu i ku środkowi, napinając klatkę. Powoli wróć do pełnego rozciągnięcia — łopatki cofnięte.','Zbyt wysokie ustawienie siedziska przenosące pracę na barki. Odbijanie od stopu maszyny zamiast kontrolowanego opuszczania.','Maszyny zbieżne różnią się profilem oporu — znajdź punkt, w którym czujesz maksymalne napięcie klatki. Doskonałe do pompowania krwi na końcu sesji piersiowej.','Wdech podczas cofania ramion, wydech podczas wyciskania.','Ćwiczenie w pełni bezpieczne. Brak ryzyka upadku sztangi lub hantli.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Pchanie','Poprzeczna','Obustronne','Maszyna',false,'Tak','Niskie',1,2,3,'Średni',true,NULL,'Prosta','{"mid_chest": 0.6, "lower_chest": 0.2, "upper_chest": 0.2}'::jsonb),(218,'Pompki z gumą oporową','pompki-z-guma-oporowa','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Gumy oporowe','Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Pchanie poziome','Pompki z gumą oporową przeprowadzoną za plecami to progresja pompek klasycznych — guma dodaje opór w górnej fazie ruchu, gdzie mięsień piersiowy jest w skróceniu. Idealne do przebicia plateau w pompkach i zwiększenia siły lockoutu.','Połóż gumę oporową za plecami na wysokości łopatek i chwyć jej końce dłońmi przy podłodze. Przyjmij pozycję pompki. Wykonaj pełne pompki — guma stawia coraz większy opór podczas wyprostu. Powoli opuść ciało kontrolując gumę.','Zbyt mocna guma uniemożliwiająca pełny zakres ruchu. Opadanie bioder lub garbienie pleców.','Zaczynaj od lekkiej gumy i stopniowo zwiększaj opór. Możesz używać dwóch gum dla większego oporu. Połącz z pompkami klasycznymi w drop-secie.','Wdech podczas opuszczania, wydech podczas wyciskania.','Upewnij się, że guma jest stabilnie ułożona i nie ześlizgnie się podczas ćwiczenia.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Tak','Niskie',2,2,3,'Niski',true,NULL,'Umiarkowana','{"mid_chest": 0.55, "lower_chest": 0.25, "upper_chest": 0.2}'::jsonb),(219,'Pompki na uchwytach','pompki-na-uchwytach','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Masa własnego ciała','Inny'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Pchanie poziome','Pompki na uchwytach (push-up handles) zwiększają zakres ruchu w fazie opuszczania w porównaniu do pompek klasycznych — klatka schodzi niżej, co intensywniej rozciąga mięsień piersiowy. Ponadto neutralny chwyt redukuje stres na nadgarstkach, co czyni je bezpieczniejszą alternatywą dla osób z dyskomfortem nadgarstków.','Ustaw uchwyty na szerokość barków lub nieco szerzej. Przyjmij pozycję pompki z dłońmi na uchwytach. Opuść klatkę poniżej poziomu uchwytów, utrzymując łokcie pod kątem ok. 60-75° do tułowia. Wypchnij się do góry do pełnego wyprostu ramion.','Opadanie bioder lub wystawianie pośladków ku górze. Brak pełnego zakresu ruchu w dół.','Im szerzej ustawisz uchwyty, tym bardziej angażujesz klatkę. Im wężej — tym więcej tricepsa. Skorzystaj z większego zakresu ruchu — to główna zaleta uchwytów.','Wdech podczas opuszczania, wydech podczas wyciskania.','Upewnij się, że uchwyty są stabilne i nie będą się przesuwać na wybranej nawierzchni.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Tak','Niskie',2,2,3,'Niski',true,NULL,'Umiarkowana','{"mid_chest": 0.55, "lower_chest": 0.25, "upper_chest": 0.2}'::jsonb),(220,'Pompki na kółkach gimnastycznych','pompki-na-ko-kach-gimnastycznych','Klatka piersiowa',ARRAY['Triceps','Barki','Brzuch'],ARRAY['Masa własnego ciała','Inny'],NULL,ARRAY['Siłownia','Plener'],'Zaawansowany','Pchanie poziome','Pompki na kółkach gimnastycznych (ring push-ups) wymagają stałej stabilizacji niestabilnego podłoża. Pierścienie umożliwiają swobodny obrót chwytów, co redukuje stres na nadgarstkach i naturalny ruch ramion, a niestabilność angażuje dodatkowe mięśnie stabilizujące bark i tułów w stopniu znacznie wyższym niż pompki klasyczne.','Ustaw kółka gimnastyczne na niskiej wysokości (15-30 cm od podłogi) lub chwyć je ze stojaka. Przyjmij pozycję pompki z rękoma na kółkach. Utrzymując stabilizację tułowia i bioder, opuść klatkę ku podłodze. Wypchnij się do góry, obracając kółka naturalnymi ruchem dłoni.','Brak stabilizacji tułowia — kółka zaczynają się wahać niekontrolowanie. Zbyt wysoko zawieszone kółka zmieniające ćwiczenie w wyciskanie na pierścieniach.','Zacznij od kółek ustawionych na podwyższeniu (piersi na poziomie kółek) — łatwiejsza wersja. Progresja: obniżaj kółka stopniowo. Skup na zwieraniu kółek do siebie w górnej fazie.','Wdech podczas opuszczania, wydech podczas wyciskania.','Ćwiczenie zaawansowane — opanuj najpierw pompki na uchwytach. Upewnij się, że mocowanie kółek jest pewne i wytrzyma Twój ciężar ciała.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',4,2,3,'Niski',true,NULL,'Złożona','{"mid_chest": 0.55, "lower_chest": 0.25, "upper_chest": 0.2}'::jsonb),(221,'Pompki z nogami na podwyższeniu','pompki-z-nogami-na-podwyzszeniu','Klatka piersiowa',ARRAY['Triceps','Barki'],ARRAY['Masa własnego ciała','Ławka'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Pchanie poziome','Pompki ze stopami na podwyższeniu (decline push-ups) kierują wektor siły ku dołowi klatki piersiowej i przednim deltom — odwrotnie niż pompki na podwyższeniu rękoma. Kąt pochylenia zwiększa udział górnej klatki i przednich deltoidów oraz podnosi ogólną trudność ćwiczenia.','Ustaw stopy na ławce, krześle lub pudełku plyometrycznym. Dłonie na podłodze nieco szerzej niż barki. Opuść klatkę ku podłodze, utrzymując ciało w linii od głowy przez biodra do nóg. Wypchnij się do góry do pełnego wyprostu.','Opadanie bioder — brak napięcia tułowia. Zbyt wysokie podwyższenie utrudniające kontrolę.','Im wyżej stopy, tym większy udział górnej klatki i deltoidów przednich, tym też trudniejsze ćwiczenie. Możesz dodać pauzę w dolnej pozycji.','Wdech podczas opuszczania, wydech podczas wyciskania.','Upewnij się, że podwyższenie jest stabilne i nie ześlizgnie się podczas ćwiczenia.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Pchanie','Poprzeczna','Obustronne','Masa własnego ciała',false,'Tak','Niskie',2,2,3,'Niski',true,NULL,'Umiarkowana','{"mid_chest": 0.35, "lower_chest": 0.1, "upper_chest": 0.55}'::jsonb),(222,'Szrugsy z hantlami','szrugsy-z-hantlami','Plecy',ARRAY['Przedramiona'],ARRAY['Hantle'],NULL,ARRAY['Siłownia'],'Początkujący','Inne','Szrugsy z hantlami to izolowane ćwiczenie mięśnia czworobocznego grzbietu (zwłaszcza górnej i środkowej części). Hantle pozwalają na naturalną pozycję ramion po bokach ciała z lekką rotacją zewnętrzną, co jest wygodniejsze dla wielu ćwiczących niż wersja ze sztangą.','Stań prosto z hantlami w opuszczonych rękach po bokach ciała, dłonie zwrócone ku sobie. Wzrusz ramionami ku górze maksymalnie wysoko — próbując dotknąć barkami uszu. Napnij czworoboczny na szczycie, utrzymaj 1-2 sekundy i powoli opuść ramiona.','Rolowanie barkami do przodu lub do tyłu zamiast czystego unoszenia. Używanie pędu zamiast siły mięśniowej. Zbyt szybkie tempo bez zatrzymania na szczycie.','Ruch powinien być czysto pionowy — żadnych kółek. Izometryczne zatrzymanie na górze mocno zwiększa aktywację czworobocznego. Używaj pasków jeśli grip jest ograniczeniem.','Wydech podczas unoszenia ramion, wdech podczas opuszczania.','Nie rotuj ramionami w zakresie ruchu — to niepotrzebnie obciąża staw barkowy. Kontroluj powrót.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Czołowa','Obustronne','Hantle',false,'Tak','Niskie',1,1,2,'Niski',true,NULL,'Prosta',NULL),(223,'Szrugsy na suwnicy Smitha','szrugsy-na-suwnicy-smitha','Plecy',ARRAY['Przedramiona'],ARRAY['Maszyna'],NULL,ARRAY['Siłownia'],'Początkujący','Inne','Szrugsy na suwnicy Smitha (Smith machine shrugs) ograniczają stopień swobody do czysto pionowego ruchu. To eliminuje konieczność stabilizacji sztangi i pozwala skupić się wyłącznie na maksymalnej aktywacji mięśnia czworobocznego. Idealne do treningu z dużymi ciężarami lub w fazie zmęczeniowej serii.','Ustaw sztangę na suwnicy Smitha na poziomie bioder. Stań pod sztangą, chwyć ją nachwytem na szerokość barków, odblokuj. Stań prosto. Wzrusz ramionami pionowo ku górze i napnij czworoboczny na szczycie. Kontroluj powrót do pozycji wyjściowej.','Uginanie łokci i próba przenoszenia ciężaru ramionami. Brak pełnego zakresu ruchu na dole.','Suwnica Smitha pozwala na stosowanie cięższych ciężarów bezpiecznie. Możesz ustawić sztangę nieco za sobą, by ramiona były lekko odciągnięte do tyłu — lepsze rozciągnięcie czworobocznego na dole.','Wydech podczas unoszenia, wdech podczas opuszczania.','Ćwiczenie bezpieczne dzięki prowadnicy suwnicy. Zablokuj sztangę po każdej serii.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Siła'],'Ciągnięcie','Czołowa','Obustronne','Maszyna',false,'Tak','Niskie',1,1,2,'Niski',true,NULL,'Prosta',NULL),(224,'High Pull','high-pull','Plecy',ARRAY['Barki','Całe ciało'],ARRAY['Sztanga','Hantle','Kettlebell'],NULL,ARRAY['Siłownia'],'Zaawansowany','Przyciąganie pionowe','High Pull to eksplozywne ćwiczenie złożone wywodzące się z olimpijskiego podnoszenia ciężarów. Łączy dynamiczny zawias biodrowy z eksplozywnym ciągnięciem sztangi powyżej wysokości bioder ku barkom. Angażuje w kolejności: kulszowo-goleniowe, pośladki, prostowniki grzbietu (faza wyprostu bioder), następnie barki i trapez (pull). Klasyfikowane jako ruch mocy.','Ustaw sztangę na podłodze lub na wysokości kolan. Chwyć ją nachwytem na szerokość barków lub nieco szerzej. Przyjmij pozycję zawiasu biodrowego. Eksploduj biodrami do przodu, prostując jednocześnie kolana i stając na palcach. Momentum przenosi się przez tułów — unieś łokcie wysoko, ciągnąc sztangę do wysokości barków lub powyżej. Kontrolowany powrót do pozycji wyjściowej.','Używanie ramion zamiast bioder jako motoru ruchu — to ćwiczenie mocy, nie wiosłowanie pionowe. Zbyt powolne tempo pozbawia ćwiczenie charakteru eksplozywnego. Brak pełnego wyprostu bioder.','Biodra, a nie barki, generują moc. Ramiona są tylko dźwignią przenoszącą siłę. Tempo: eksplozywny ruch w górę, kontrolowany w dół. Ćwiczenie najlepiej wykonywać jako pierwsze w sesji, gdy układ nerwowy jest wypoczęty.','Wdech przed ruchem, wydech gwałtowny podczas eksplozji bioder.','Ćwiczenie zaawansowane — opanuj najpierw martwy ciąg i wznosy obciążone. Błędy techniczne mogą prowadzić do urazu dolnych pleców lub barków. Nie stosuj do upadku mięśniowego.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Zdrowie ogólne'],'Ciągnięcie','Czołowa','Obustronne','Sztanga',false,'Nie','Średnie',4,4,3,'Niski',true,NULL,'Złożona','{"lats": 0.4, "upper_back": 0.6}'::jsonb),(225,'Przysiad na jednej nodze (Pistol Squat)','przysiad-na-jednej-nodze-pistol-squat','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda','Brzuch'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Zaawansowany','Przysiad','Pistol Squat to jednostronne przysiady na jednej nodze do pełnego głębokiego przysiadu, z drugą nogą wyciągniętą poziomo przed siebie. Wymaga wyjątkowej siły, ruchomości kostki i stawu biodrowego oraz propriocepcji. Jest testem symetrii siłowej i mobilności dolnych partii.','Stań na jednej nodze. Wyciągnij drugą nogę poziomo przed siebie. Powoli opuść się do głębokiego przysiadu na jednej nodze, trzymając wyciągniętą nogę prosto. Kolano nogi podporowej podąża za palcami stopy. Wstań ze szczytu dolnego do pełnego wyprostu. Trzymaj ręce przed sobą dla balansu.','Kolano zapada się do wewnątrz (valgus). Brak ruchomości kostki ograniczający głębokość. Pochylanie tułowia za daleko do przodu.','Progresja: zacznij od Pistol Squat z asekuracją (trzymaj się drążka), potem box pistol (do skrzyni), potem pełny. Ruchomość kostki jest kluczem — rozciągaj ją regularnie.','Wdech podczas schodzenia, wydech podczas wstawania.','Ćwiczenie zaawansowane — nie wykonuj z bólem kolana lub kostki. Opanuj pełny obustronny przysiad zanim przejdziesz do Pistol Squat.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Zdrowie ogólne'],'Przysiad','Strzałkowa','Jednostronne','Masa własnego ciała',false,'Z ostrożnością','Wysokie',5,3,4,'Niski',true,NULL,'Złożona',NULL),(226,'Przysiad Zerchera (Zercher Squat)','przysiad-zerchera-zercher-squat','Mięśnie czworogłowe uda',ARRAY['Pośladki','Przywodziciele','Plecy','Brzuch'],ARRAY['Sztanga','Ławka'],NULL,ARRAY['Siłownia'],'Zaawansowany','Przysiad','Zercher Squat to głęboki przysiad ze sztangą trzymaną w zgięciu łokci przed klatką. Pozycja obciążenia wymusza pionowy tułów i głęboki przysiad, intensywnie angażując czworogłowe, pośladki i przywodziciele. Znaczne wymagania stabilizerów tułowia i siły chwytu/łokci.','Podnieś sztangę z ławki lub z kucki do zgięcia łokci — sztanga leży w zagłębieniu łokciowym, ramiona splecione lub dłonie złączone. Stój z nogami na szerokość bioder lub szerzej, palce nieco na zewnątrz. Schodź do pełnego głębokiego przysiadu, utrzymując tułów pionowo. Wstań, napinając całe ciało.','Pochylanie tułowia do przodu (obniża cel ćwiczenia). Za wąski rozstaw nóg ograniczający głębokość. Zbyt ciężka sztanga powodująca ból łokci.','Otulaj sztangę rękawem lub używaj maty barbell sleeve dla komfortu łokci. Zercher wymaga dobrej ruchomości bioder i kostki. Zacznij od lekkiego ciężaru. Trzymaj łokcie wysokim — to utrzymuje tułów w pionie.','Wdech i napięcie tłoczni brzusznej przed zejściem, wydech na górze.','Może powodować ból łokci przy dużych ciężarach — stosuj ochronę. Ćwiczenie zaawansowane — opanuj front squat jako wstęp.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Masa mięśniowa'],'Przysiad','Strzałkowa','Obustronne','Sztanga',true,'Z ostrożnością','Wysokie',4,4,4,'Niski',true,NULL,'Złożona',NULL),(227,'Skłony boczne z hantlem','sk-ony-boczne-z-hantlem','Brzuch',ARRAY[]::text[],ARRAY['Hantle'],NULL,ARRAY['Siłownia','Dom'],'Początkujący','Inne','Skłony boczne z hantlem izolują mięśnie skośne brzucha i kwadratowy lędźwi poprzez boczne zgięcie tułowia. Prosta mechanika, szeroka dostępność i przydatność w profilaktyce bólu dolnych pleców.','Stań prosto z hantlem w jednej ręce. Powoli pochyl tułów w bok, opuszczając hantlę wzdłuż uda. Zakres ruchu: do końca komfortowego zasięgu. Wróć do pozycji pionowej siłą mięśni bocznych tułowia. Wykonaj wszystkie powtórzenia na jedną stronę, następnie zmień ręce.','Pochylanie do przodu lub rotacja tułowia zamiast czystego ruchu bocznego. Zbyt duży ciężar skracający zakres ruchu.','Ruch powinien być czysto boczny w płaszczyźnie czołowej — wyobraź sobie stanie plecami do ściany. Możesz wykonywać jednostronnie (obciążona ręka po boku) lub z obciążeniem po obu stronach naprzemiennie.','Wydech podczas bocznego zgięcia, wdech podczas powrotu.','Osoby z bólem dolnych pleców powinny skonsultować to ćwiczenie z fizjoterapeutą.','Izolowane',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Masa mięśniowa','Zdrowie ogólne'],'Core','Czołowa','Jednostronne','Hantle',false,'Tak','Niskie',1,1,2,'Niski',true,NULL,'Prosta',NULL),(228,'Jefferson Curl','jefferson-curl','Plecy',ARRAY['Mięśnie dwugłowe uda'],ARRAY['Sztanga','Hantle','Kettlebell'],NULL,ARRAY['Siłownia'],'Zaawansowany','Zgięcie tułowia','Jefferson Curl to ćwiczenie loaded mobility — wielostawowe, kontrolowane zwijanie całego kręgosłupa pod obciążeniem, stojąc na podwyższeniu. Angażuje jednocześnie mięśnie przykręgosłupowe, kulszowo-goleniowe i pośladki, co czyni je ruchem złożonym. Nie jest ćwiczeniem siłowym ani hipertroficznym i nie powinno być dobierane jako główny ruch wielostawowy — celem jest mobilność i elastyczność tkanek łącznych pod kontrolowanym obciążeniem. Przeznaczone wyłącznie dla zaawansowanych ćwiczących bez problemów kręgosłupa.','Stań na podwyższeniu (skrzynce lub stopniu) stopami razem. Trzymaj lekkie obciążenie w opuszczonych rękach. Zacznij od pochylenia głowy ku przodowi, następnie zaokrąglaj kręgosłup segment po segmencie — szyjny, piersiowy, lędźwiowy — aż ciężar zwisa możliwie nisko. Utrzymaj 2-3 sekundy. Wróć odwijając kręgosłup w odwrotnej kolejności — od dołu ku górze.','Stosowanie zbyt dużego ciężaru (to ćwiczenie mobilnościowe, nie siłowe). Pośpiech — każdy segment kręgosłupa musi być świadomie zwijany. Brak podwyższenia ograniczającego zakres ruchu.','Zacznij od minimalnego ciężaru (2-5 kg) i przez wiele tygodni stopniowo go zwiększaj. Podwyższenie musi być stabilne. Miej poczucie, że ''wydłużasz'' kręgosłup przez grawitację. Jefferson Curl nie jest dla osób z aktywnym bólem pleców lub hernią dysku. Nie stosuj jako główne ćwiczenie złożone sesji — zawsze jako akcesorialne lub zamykające.','Długi, spokojny wydech podczas zwijania, wdech podczas powrotu.','TYLKO DLA ZAAWANSOWANYCH — wyłącznie dla osób z dobrą techniką martwego ciągu i bez istniejących problemów kręgosłupa. Zawsze zaczynaj od bardzo lekkiego ciężaru. Przy bólu lub dyskomforcie przerwij natychmiast. Nie dobieraj dla początkujących ani jako główny ruch wielostawowy.','Złożone',ARRAY['Zaawansowany'],ARRAY['Zdrowie ogólne'],'Inne','Strzałkowa','Obustronne','Hantle',false,'Nie','Wysokie',5,2,2,'Niski',true,NULL,'Złożona',NULL),(249,'Skoki pogo','skoki-pogo','Łydki',ARRAY['Mięśnie czworogłowe uda','Pośladki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Inne','Skoki pogo to reaktywne skoki o małej amplitudzie, w których energia sprężysta gromadzona jest w ścięgnie Achillesa i mięśniach łydki. Stopa kontaktuje się z podłożem na ułamek sekundy, a napęd pochodzi niemal wyłącznie z kostki — kolano pozostaje prawie nieruchome.','Stań wyprostowany, stopy na szerokość bioder. Wykonaj szybkie, rytmiczne skoki z minimalnymi ugięciami kolana — napęd pochodzi ze ścięgien Achillesa i mięśni łydki. Utrzymuj sztywny tułów i ręce lekko przed ciałem. Cel: jak najkrótszy kontakt z podłożem przy zachowaniu rytmu.','Zbyt duże ugięcie kolan — zamienia ćwiczenie w zwykłe podskoki. Lądowanie na piętach wydłuża czas kontaktu i traci reaktywność. Zbyt wolny rytm — traci się efekt sprężynowania.','Myśl o ziemi jak o gorącej blasze — odbij się jak najszybciej. Pracuj wyłącznie kostką; kolano pozostaje prawie nieruchome. Zacznij od 3 serii 10 s, stopniowo zwiększaj do 20–30 s.','Oddech swobodny przez cały czas; nie wstrzymuj oddechu. Rytm oddechu dostosuj do rytmu skoków.','Nie wykonuj na twardym betonie bez amortyzacji. Stopniuj objętość — przeciążenie ścięgna Achillesa grozi tendinopatią. Odłóż ćwiczenie przy bólu piętowym lub łydkowym.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Przysiad','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',3,3,2,'Wysoki',true,NULL,'Umiarkowana','{"łydki": 1}'::jsonb),(250,'Skok z zamachem','skok-z-zamachem','Mięśnie czworogłowe uda',ARRAY['Pośladki','Łydki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Przysiad','Skok z zamachem (countermovement jump) to eksplozywny wyskok pionowy, w którym wstępne ugięcie kolan i bioder magazynuje energię sprężystą, a gwałtowne wyprostowanie i zamach ramionami maksymalizują wysokość wybicia. Podstawowy test mocy kończyn dolnych.','Stań w rozkroku na szerokość barków. Szybko obniż biodra i zamachaj ramionami w dół, następnie natychmiast wypchnij się ku górze, prostując biodra, kolana i kostki jednocześnie. W szczycie lotu ciało jest w pełni wyprostowane. Ląduj miękko na śródstopiu, amortyzując ugięciem kolan.','Zbyt powolne przejście z fazy opuszczania do wybicia — traci się efekt odbicia. Niepełne wyprostowanie w wyskoku. Twarde lądowanie na piętach bez amortyzacji.','Kluczowy jest szybki, gwałtowny przeskok z fazy ekscentrycznej do koncentrycznej — im krótszy czas zatrzymania, tym wyższy wyskok. Zamach ramionami dodaje 5–10% wysokości.','Wdech w fazie opuszczania, wydech podczas wybicia. Nie wstrzymuj oddechu przez wiele powtórzeń.','Ćwicz na nawierzchni z dobrą amortyzacją. Nie wykonuj przy bólu kolan lub bioder. Upewnij się, że wokół jest wystarczająco dużo miejsca.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Przysiad','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Średnie',2,3,2,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.45, "czworogłowe": 0.55}'::jsonb),(251,'Skok w dal z miejsca','skok-w-dal-z-miejsca','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda','Łydki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Przysiad','Skok w dal z miejsca to maksymalny wyskok horyzontalny z dwóch nóg. Angażuje całe ciało w kierunku poziomym i jest klasycznym testem mocy eksplozywnej dolnej partii ciała. Wymaga koordynacji pracy bioder, kolan, kostek i ramion.','Stań za linią w rozkroku na szerokość bioder. Ugnij kolana, pochyl tułów lekko do przodu i zamachaj ramionami do tyłu. Gwałtownie wypchnij się do przodu i ku górze, prostując biodra i kolana. Ląduj na obu stopach jednocześnie, amortyzując ugięciem kolan i opadając do przysiadu.','Zbyt pionowe wybicie — traci się dystans. Lądowanie z wyprostowanymi kolanami — przeciążenie stawów. Brak zamachu ramionami — ogranicza dystans o 10–15%.','Optymalny kąt wybicia to około 45°. Użyj energii zamachu ramionami jako katapulty. Mierz dystans od linii do pięt przy lądowaniu.','Głęboki wdech przed wybiciem, wydech przy lądowaniu. Nie wstrzymuj oddechu dłużej niż jedno powtórzenie.','Ląduj na miękkiej nawierzchni lub macie. Nie wykonuj przy bólu kolan, bioder lub kostek. Rozgrzej stawy kończyn dolnych przed seriami maksymalnymi.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Przysiad','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Średnie',2,3,2,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.5, "czworogłowe": 0.5}'::jsonb),(252,'Zeskok z natychmiastowym wybiciem','zeskok-z-natychmiastowym-wybiciem','Mięśnie czworogłowe uda',ARRAY['Pośladki','Łydki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Plener'],'Zaawansowany','Przysiad','Zeskok z natychmiastowym wybiciem (depth jump) to ćwiczenie reaktywne, w którym sportowiec zeskakuje z podwyższenia i natychmiast po kontakcie minimalizuje czas lądowania, wyskakując jak najwyżej. Intensywnie trenuje cykl rozciągnięcia-skurczu mięśni i ścięgien.','Stań na podwyższeniu 20–40 cm. Zeskocz swobodnie, lądując na śródstopiu obu nóg jednocześnie. Natychmiast, bez pauzy, wypchnij się maksymalnie ku górze. Czas kontaktu z podłożem powinien być jak najkrótszy — cel poniżej 200 ms. Ląduj miękko po wyskoku.','Za wysokie podwyższenie — zwiększa ryzyko bez proporcjonalnego efektu. Pauza między lądowaniem a wybiciem — traci się reaktywność. Zbyt głębokie ugięcie kolan przy lądowaniu.','Zacznij od niższego podwyższenia (20 cm) i stopniowo zwiększaj. Mierz czas kontaktu — to klucz do jakości ćwiczenia. Wykonuj wyłącznie wypoczęty, nie na koniec treningu.','Wdech przed zeskokiem, wydech i napięcie brzucha podczas wybicia. Zresetuj oddech między powtórzeniami.','Wyłącznie dla sportowców z solidną bazą siłową i techniczną. Nie wykonuj przy bólu kolan, kostek lub bioder. Ogranicz objętość — maksymalnie 40 kontaktów na sesję.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Przysiad','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Wysokie',4,4,3,'Wysoki',true,NULL,'Złożona','{"pośladki": 0.45, "czworogłowe": 0.55}'::jsonb),(253,'Wskok na podwyższenie','wskok-na-podwyzszenie','Pośladki',ARRAY['Mięśnie czworogłowe uda','Mięśnie dwugłowe uda','Łydki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Plener'],'Średniozaawansowany','Przysiad','Wskok na podwyższenie (box jump) to eksplozywny skok obunóż na skrzynię lub podwyższenie. Łączy generowanie mocy w wyskoku z kontrolowanym lądowaniem na wyższym poziomie. Angażuje pośladki, czworogłowe i łydki; wymaga koordynacji i pewności w fazie lotu.','Stań 30–50 cm od skrzyni w rozkroku na szerokość bioder. Wykonaj szybki przysiad z zamachem ramion, a następnie wypchnij się ku górze i do przodu. Ląduj na obu stopach jednocześnie na środku podwyższenia, miękko amortyzując ugięciem kolan. Zejdź tyłem lub krokowo — nie skacz z powrotem.','Zbyt wysokie podwyższenie — ryzyko urazu przy nieudanym skoku. Lądowanie tylko na palcach bez amortyzacji. Odbijanie się bezpośrednio z powrotem bez pauzy.','Wybierz wysokość, którą możesz pokonać ze swobodą i pewną techniką. Skup się na lądowaniu — powinno być ciche. Progresja: najpierw opanuj technikę lądowania, potem zwiększaj wysokość.','Wdech przed wybiciem, wydech podczas lądowania i stabilizacji. Nie wstrzymuj oddechu przy seriach.','Upewnij się, że podwyższenie jest stabilne. Nie skacz na mokrą lub śliską powierzchnię. Przy nieudanym wyskoku chwyć krawędź lub zejdź z boku.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Przysiad','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Średnie',3,3,2,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.5, "czworogłowe": 0.5}'::jsonb),(254,'Skoki boczne jednonóż','skoki-boczne-jednonoz','Mięśnie czworogłowe uda',ARRAY['Pośladki','Łydki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Zaawansowany','Odwodzenie','Skoki boczne jednonóż to seria eksplozywnych skoków w bok wykonywanych na jednej nodze. Ćwiczenie trenuje boczną moc wybicia, kontrolę lądowania jednonóż i stabilność stawu kolanowego, kluczowe dla sportów wymagających zmiany kierunku.','Stań na jednej nodze, lekko uginając kolano. Wypchnij się dynamicznie w bok, lądując na tej samej nodze z miękką amortyzacją. Utrzymaj równowagę przez 1 s, a następnie odbij się z powrotem. Powtarzaj rytmicznie. Aktywne biodro i tułów zapewniają stabilizację przy lądowaniu.','Zbyt duży zakres — traci się kontrolę lądowania. Kolano zapada się do środka przy lądowaniu. Brak pauzy stabilizacyjnej — ćwiczenie traci charakter reaktywny.','Zacznij od mniejszego dystansu bocznego. Dbaj o to, aby kolano było nad palcami stóp w chwili lądowania. Wzmocnij pośladek średni zanim przejdziesz do tej progresji.','Równomierne oddychanie między skokami. Napnij core podczas fazy lotu dla stabilizacji.','Wymagana solidna baza jednostronnej stabilności kolana. Nie wykonuj przy bólu stawu kolanowego lub kostki. Ćwicz w butach z dobrą stabilizacją boczną.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Wykrok','Czołowa','Jednostronne','Masa własnego ciała',false,'Z ostrożnością','Średnie',4,4,3,'Wysoki',true,NULL,'Złożona','{"pośladki": 0.55, "czworogłowe": 0.45}'::jsonb),(255,'Skok jednonóż','skok-jednonoz','Mięśnie czworogłowe uda',ARRAY['Pośladki','Łydki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Zaawansowany','Wykrok','Skok jednonóż to eksplozywny wyskok w przód lub w górę z jednej nogi. Ujawnia asymetrie siłowe między kończynami i jest kluczowym elementem zarówno treningu sportowego, jak i rehabilitacji po urazach kończyny dolnej.','Stań na jednej nodze, lekko uginając kolano. Zamachaj ramionami i wypchnij się dynamicznie do przodu lub ku górze. Ląduj miękko na tej samej lub przeciwnej nodze, amortyzując ruch ugięciem kolana i biodra. Utrzymaj równowagę przez 2–3 s przed kolejnym powtórzeniem.','Twarde lądowanie z wyprostowanym kolanem. Kolano zapada się do środka (koślawość dynamiczna). Niekontrolowane cofnięcie środka ciężkości przy lądowaniu.','Porównuj odległości między nogami — asymetria powyżej 10% może wskazywać na ryzyko urazu. Progresja: najpierw opanuj lądowanie jednonóż, potem dodaj fazę odbicia. Użyj taśmy na podłodze jako celu odległości.','Wdech przed wybiciem, wydech i napięcie core podczas lotu i lądowania.','Wymagana dobra siła stabilizatorów kolana i kostki. Praca jednostronna mocno obciąża staw kolanowy — nie wykonuj przy istniejącej niestabilności więzadłowej.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Wykrok','Strzałkowa','Jednostronne','Masa własnego ciała',false,'Z ostrożnością','Wysokie',4,4,3,'Wysoki',true,NULL,'Złożona','{"pośladki": 0.5, "czworogłowe": 0.5}'::jsonb),(256,'Nauka lądowania','nauka-ladowania','Mięśnie czworogłowe uda',ARRAY['Pośladki','Mięśnie dwugłowe uda','Brzuch'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Początkujący','Przysiad','Nauka lądowania to fundamentalne ćwiczenie kontroli dezaktywacji i mechaniki stawów przy przyjmowaniu obciążenia. Uczy prawidłowej sekwencji amortyzacji (kostka → kolano → biodro), niezbędnej przed przejściem do ćwiczeń plyometrycznych. Kluczowe dla prewencji urazów.','Stań wyprostowany. Wykonaj małe odbicie lub zeskok i ląduj na obu stopach jednocześnie, miękko amortyzując przez ugięcie kostek, kolan i bioder w tej kolejności. Kolana podążają za palcami stóp, tułów lekko pochylony do przodu. Zatrzymaj ruch kontrolowanie, utrzymując pozycję przez 3 s.','Lądowanie na piętach z wyprostowanymi kolanami. Koślawość kolan przy lądowaniu. Brak kontroli po lądowaniu — brak fazy stabilizacji.','Ciche lądowanie = dobre lądowanie. Naucz klientów słuchać dźwięku lądowania jako wskaźnika jakości. Progresja: obunóż → jednostronne → z większej wysokości.','Wdech przed lądowaniem, wydech i napięcie core w momencie kontaktu. Utrzymuj napięcie brzucha przez całą fazę stabilizacji.','To ćwiczenie bazowe — nie pomijaj go przed przejściem do skoków o dużej intensywności. Odpowiednie dla każdego poziomu jako wprowadzenie do treningu plyometrycznego.','Złożone',ARRAY['Początkujący','Średniozaawansowany','Zaawansowany'],ARRAY['Zdrowie ogólne','Siła'],'Przysiad','Strzałkowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Niskie',2,2,2,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.35, "czworogłowe": 0.65}'::jsonb),(257,'Skok boczny z zatrzymaniem','skok-boczny-z-zatrzymaniem','Pośladki',ARRAY['Mięśnie czworogłowe uda','Łydki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Zaawansowany','Odwodzenie','Skok boczny z zatrzymaniem (lateral jump and stick) to ćwiczenie bocznej mocy wybicia z akcentem na kontrolowane lądowanie jednonóż. Po wyskoku bocznym sportowiec utrzymuje równowagę na lądującej nodze przez 2–3 s. Trenuje zmianę kierunku i kontrolę dezaktywacji.','Stań na jednej nodze. Wypchnij się dynamicznie w bok, lądując na przeciwnej nodze z ugiętym kolanem i biodrem. Natychmiast stabilizuj pozycję — kolano nad palcami, tułów w równowadze. Utrzymaj przez 2–3 s, a następnie zmień kierunek. Wymagana pełna kontrola przed kolejnym skokiem.','Pośpiech przy lądowaniu — brak pauzy stabilizacyjnej. Koślawość kolana w chwili kontaktu. Zbyt szeroki skok przekraczający możliwości stabilizacji.','Wyobraź sobie lądowanie w błocie — masz zostać tam i nie ruszyć się. Progresja: małe skoki, stopniowo zwiększaj dystans. Wzmocnij pośladek średni przed tą progresją.','Wdech przed skokiem, wydech i napięcie core przy lądowaniu. Utrzymaj napięcie przez fazę stabilizacji.','Wymaga dobrej jednostronnej kontroli kolana. Nie wykonuj na śliskiej nawierzchni. Przy pierwszych próbach zapewnij klientowi werbalną asekurację.','Złożone',ARRAY['Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Wykrok','Czołowa','Jednostronne','Masa własnego ciała',false,'Z ostrożnością','Średnie',4,4,2,'Wysoki',true,NULL,'Złożona','{"pośladki": 0.6, "czworogłowe": 0.4}'::jsonb),(258,'Przeskoki boczne z nogi na nogę','przeskoki-boczne-z-nogi-na-noge','Mięśnie czworogłowe uda',ARRAY['Pośladki','Łydki'],ARRAY['Masa własnego ciała'],NULL,ARRAY['Siłownia','Dom','Plener'],'Średniozaawansowany','Lokomocja','Przeskoki boczne z nogi na nogę (lateral bounds) to rytmiczne skoki boczne, w których sportowiec przemieszcza się naprzemiennie między lewą a prawą nogą. Ćwiczenie trenuje boczną reaktywność, koordynację, rytm ruchowy i symetrię siłową kończyn dolnych.','Stań na jednej nodze, lekko uginając kolano. Wypchnij się dynamicznie w bok, lądując na przeciwnej nodze z krótkim amortyzowaniem. Natychmiast odbij się z powrotem w przeciwnym kierunku. Utrzymuj rytmiczne przeskoki. Ramiona pracują naprzemiennie jak u sprinterów.','Zatrzymywanie się przed każdym odbiciem — traci się rytm. Zbyt szeroki krok — wychodzi się poza kontrolę. Asymetryczny rytm wskazujący na słabszą stronę.','Ustaw dwie taśmy lub stożki jako cele lądowania. Mierz rytm metronomem — regularność jest kluczem. Porównuj szerokość skoku lewej i prawej nogi, żeby wykryć asymetrię.','Równomierne oddychanie w rytm skoków. Nie wstrzymuj oddechu — to ćwiczenie kondycyjne o dużym zapotrzebowaniu tlenowym.','Zacznij od mniejszego dystansu bocznego. Unikaj wykonywania przy zmęczeniu, gdy technika lądowania się pogarsza. Ćwicz na nawierzchni z dobrą przyczepnością.','Złożone',ARRAY['Średniozaawansowany','Zaawansowany'],ARRAY['Siła','Poprawa kondycji'],'Wykrok','Czołowa','Obustronne','Masa własnego ciała',false,'Z ostrożnością','Średnie',3,3,2,'Wysoki',true,NULL,'Umiarkowana','{"pośladki": 0.5, "czworogłowe": 0.5}'::jsonb) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,main_muscle_group=EXCLUDED.main_muscle_group,secondary_muscle_groups=EXCLUDED.secondary_muscle_groups,equipment=EXCLUDED.equipment,training_location=EXCLUDED.training_location,difficulty_level=EXCLUDED.difficulty_level,movement_pattern=EXCLUDED.movement_pattern,exercise_type=EXCLUDED.exercise_type,suitable_experience_levels=EXCLUDED.suitable_experience_levels,training_goals=EXCLUDED.training_goals,movement_category=EXCLUDED.movement_category,is_active=EXCLUDED.is_active,exercise_priority=EXCLUDED.exercise_priority,sub_target_biases=EXCLUDED.sub_target_biases`;

