const EX_BATCH_SQLS = [SQL_EXERCISES_0,SQL_EXERCISES_1,SQL_EXERCISES_2,SQL_EXERCISES_3];


export async function seedCatalogue(): Promise<void> {
  // Skip if catalogue already present
  const countRes = await db.execute(sql`SELECT COUNT(*)::int AS c FROM exercises`);
  const existing = Number((countRes.rows[0] as { c: number }).c);
  if (existing >= 156) {
    logger.info({ existing }, 'Catalogue seed: already present, skipping');
    return;
  }
  logger.info({ existing }, 'Catalogue seed: starting');

  // 1. specific_muscles
  await db.execute(sql.raw(SQL_SPECIFIC_MUSCLES));
  await db.execute(sql.raw(SQL_SM_SETVAL));

  // 2. exercises (batched)
  for (const batchSql of EX_BATCH_SQLS) {
    await db.execute(sql.raw(batchSql));
  }
  await db.execute(sql.raw(SQL_EX_SETVAL));

  // 3. exercise_muscle_assignments
  await db.execute(sql.raw(SQL_EMA));
  await db.execute(sql.raw(SQL_EMA_SETVAL));

  // 4. exercise_substitutions
  await db.execute(sql.raw(SQL_ESUBS));
  await db.execute(sql.raw(SQL_ESUBS_SETVAL));

  // 5. Exercise patches: new exercises + metadata corrections (idempotent).
  //    Split into separate statements because drizzle sql.raw() handles one statement at a time.
  const patchStatements = SQL_EXERCISES_PATCH
    .split(';')
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
  for (const stmt of patchStatements) {
    await db.execute(sql.raw(stmt));
  }
  await db.execute(sql.raw(SQL_EX_SETVAL));

  const afterRes = await db.execute(sql`SELECT COUNT(*)::int AS c FROM exercises`);
  const after = Number((afterRes.rows[0] as { c: number }).c);
  logger.info({ inserted: after - existing }, 'Catalogue seed: complete');
}
